window.HB_TR["ezekiel"]["ur"]=["1۔ اب یہ تیسویں سال میں ہوا، چوتھے مہینے میں، مہینے کے پانچویں دن، جب میں قیدیوں میں دریا چبار کے کنارے تھا، آسمان کھل گئے، اور میں نے خدا کے خواب دیکھے۔ {قیدی: عبرانی۔ قید}\n2۔ مہینے کے پانچویں {دن} میں، جو {تھا} بادشاہ یہویاکین کی قید کا پانچواں سال،\n3۔ خداوند کا کلام واضح طور پر حزقی ایل کاہن، بوزی کے بیٹے، کو کلدانیوں کی زمین میں دریائے چبار کے کنارے آیا؛ اور خداوند کا ہاتھ اس پر تھا۔ {ایزیکیئل: عبرانی۔ Jehezkel}\n4۔ اور میں نے دیکھا، اور دیکھو، شمال سے ایک طوفان آیا، ایک بڑا بادل، اور آگ خود کو لپیٹ رہی تھی، اور اس کے ارد گرد ایک روشنی تھی، اور اس کے بیچ سے عنبر کے رنگ کی طرح، آگ کے بیچ سے۔ {انفولڈنگ...: عبرانی۔ خود کو پکڑنا}\n5۔ اسی کے بیچ سے چار جانداروں کی شکل بھی سامنے آئی۔ اور یہ ان کی ظاہری شکل تھی؛ ان کی شکل ایک مرد جیسی تھی۔\n6۔ اور ہر ایک کے چار چہرے تھے، اور ہر ایک کے چار پر تھے۔\n7۔ اور ان کے پاؤں سیدھے تھے؛ اور ان کے پاؤں کا تلا بچھڑے کے پاؤں کی طرح تھا: اور وہ چمکدار پیتل کے رنگ کی طرح چمک رہے تھے۔ {سیدھا...: عبرانی۔ سیدھا پاؤں}\n8۔ اور ان کے چاروں طرف ایک آدمی کے ہاتھ اپنے پروں کے نیچے تھے؛ اور ان چاروں کے چہرے اور پر تھے۔\n9۔ ان کے پر ایک دوسرے سے جڑے ہوئے تھے؛ جب وہ گئے تو مڑے نہیں؛ انہوں نے ہر ایک کو سیدھا سادہ انداز اپنایا۔\n10۔ جہاں تک ان کے چہروں کی مشابہت ہے، ان چاروں کا چہرہ انسان کا تھا اور دائیں طرف شیر کا چہرہ تھا؛ اور ان چاروں کے چہرے کے بائیں طرف بیل کا تھا؛ ان چاروں کا چہرہ بھی عقاب جیسا تھا۔\n11. یوں ان کے چہرے اور ان کے پر اوپر کی طرف پھیلے ہوئے تھے؛ ہر ایک کے دو {پر} ایک دوسرے سے جڑے ہوئے تھے، اور دو ان کے جسموں کو ڈھانپے ہوئے تھے۔ {پھیلا ہوا...: یا، اوپر تقسیم کیا گیا}\n12۔ اور وہ سب سیدھے سیدھے گئے: جہاں روح جانا تھی، وہ گئے؛ {اور} جب وہ گئے تو مڑے نہیں۔\n13۔ جہاں تک جانداروں کی شبیہ کا تعلق ہے، ان کی شکل جلتی ہوئی آگ کے انگاروں کی مانند تھی، {اور} چراغوں کی طرح تھی: یہ جانداروں کے درمیان اوپر نیچے جاتی تھی؛ اور آگ روشن تھی، اور آگ سے بجلی نکلی۔\n14۔ اور زندہ مخلوق بجلی کی چمک کی طرح دوڑی اور واپس آئیں۔\n15۔ اب جب میں نے زندہ مخلوقات کو دیکھا، دیکھو ایک پہیہ زمین پر زندہ مخلوقات کے چار چہروں کے ساتھ۔\n16۔ پہیوں کی شکل اور ان کا کام {بیریل کے رنگ کی طرح تھا}: اور ان چاروں کی ایک ہی شکل تھی: اور ان کی شکل اور کام {تھا} جیسے وہ پہیے کے درمیان میں ایک پہیہ ہو۔\n17۔ جب وہ گئے، تو چاروں طرف چلے گئے: {اور} جب وہ گئے تو مڑے نہیں۔\n18۔ جہاں تک ان کی انگوٹھیوں کا تعلق ہے، وہ اتنی اونچی تھیں کہ خوفناک تھیں؛ اور ان کی انگوٹھیاں ان چاروں کے گرد آنکھوں سے بھری ہوئی تھیں۔ {اور ان کی انگوٹھیاں: یا، اور ان کی سٹرائیک}\n19۔ اور جب جاندار گئے، تو پہیے ان کے پاس سے گزرے: اور جب زندہ مخلوقات زمین سے اٹھائی گئیں، تو پہیے اٹھ گئے۔\nجہاں بھی روح جانا ہوتی، وہ جاتے، وہاں ان کی روح جاتی؛ اور پہیے ان کے خلاف اٹھا دیے گئے: کیونکہ زندہ مخلوق کی روح پہیوں میں تھی۔ {کا...: یا، زندگی کا}\n21. جب وہ گئے، {یہ} گئے؛ اور جب وہ کھڑے ہوئے، {یہ} کھڑے ہوئے؛ اور جب وہ زمین سے اٹھائے گئے، تو پہیے ان کے خلاف اٹھ گئے: کیونکہ جاندار کی روح پہیوں میں تھی۔ {کا...: یا، زندگی کا}\n22۔ اور زندہ مخلوق کے سروں پر آسمان کی شکل خوفناک کرسٹل کے رنگ کی طرح تھی، جو ان کے سروں کے اوپر پھیلا ہوا تھا۔\n23۔ اور آسمان کے نیچے ان کے پر سیدھے تھے، ایک دوسرے کی طرف: ہر ایک کے دو تھے، جو اس طرف تھے، اور ہر ایک کے دو تھے، جو اس طرف ان کے جسم کو ڈھانپے ہوئے تھے۔\n24۔ اور جب وہ گئے، میں نے ان کے پروں کی آواز سنی، جیسے عظیم پانیوں کی آواز، جیسے خدا کی آواز، بولنے کی آواز، جیسے ایک میزبان کی آواز: جب وہ کھڑے ہوئے، تو انہوں نے اپنے پر چھوڑ دیے۔\n25۔ اور جب وہ کھڑے ہوئے، {اور} نے اپنے پر چھوڑ دیے تو آسمان سے ایک آواز آئی جو {تھا} ان کے سر کے اوپر تھی۔\n26۔ اور اس آسمان کے اوپر جو {تھا} ان کے سروں پر {تھا} تخت کی شکل تھی، جیسے نیلم کے پتھر کی شکل: اور تخت کی شکل پر {تھا} جیسا کہ اوپر ایک آدمی کا ظہور تھا۔\n27۔ اور میں نے عنبر کے رنگ کو دیکھا، اس کے اندر آگ کی ظہور، اس کی کمر کی اوپر کی طرف، اور اس کی کمر کی ظاہری شکل سے جو نیچے کی طرف تھی، میں نے آگ کی شکل دیکھی، اور اس کے گرد روشنی تھی۔\n28. جیسے بارش کے دن بادلوں میں کمان کی ظاہری شکل ہوتی ہے، ویسے ہی ارد گرد روشنی کی ظاہری شکل بھی تھی۔ یہ {تھا} خداوند کی جلال کی ظاہری شکل۔ اور جب میں نے اسے دیکھا، تو میں منہ کے بل گر گیا، اور میں نے ایک آواز سنی جو بول رہی تھی۔","1۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، اپنے قدموں پر کھڑے ہو جاؤ، اور میں تم سے بات کروں گا۔\n2۔ اور روح میرے اندر داخل ہوئی جب اس نے مجھ سے بات کی، اور مجھے اپنے قدموں پر کھڑا کیا، کہ میں نے اسے سنا جو مجھ سے بول رہا تھا۔\n3۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، میں تمہیں بنی اسرائیل کے پاس بھیجتا ہوں، ایک باغی قوم کے پاس جو میرے خلاف بغاوت کر چکی ہے: وہ اور ان کے باپ و اجداد آج تک میرے خلاف زیادتی کرتے آئے ہیں۔ {قوم: عبرانی۔ قومیں}\n4۔ کیونکہ {وہ} گستاخ بچے اور ضدی ہیں۔ میں تمہیں ان کے پاس بھیجتا ہوں؛ اور تم ان سے کہو گے، خداوند خدا یہی فرماتا ہے۔ {گستاخ: عبرانی۔ سخت چہرہ}\n5۔ اور وہ، چاہے وہ سنیں یا برداشت کریں، (کیونکہ وہ باغی گھرانے ہیں)، پھر بھی جان لیں گے کہ ان میں ایک نبی تھا۔\n6۔ اور تو، انسان کے بیٹے، ان سے نہ ڈرو، نہ ان کی باتوں سے ڈرو، چاہے وہ کانٹے اور کانٹے تمہارے ساتھ ہوں، اور تم بچھوؤں کے درمیان رہتے ہو: ان کی باتوں سے نہ ڈرو، نہ ان کی نظروں سے مایوس ہو، چاہے وہ باغی گھرانے کیوں نہ ہوں۔ {بریئرز...: یا، باغی}\n7۔ اور تم میرے الفاظ ان سے کہے گا، چاہے وہ سنیں یا برداشت کریں: کیونکہ وہ سب سے زیادہ باغی ہیں۔ {زیادہ تر...: عبرانی۔ بغاوت}\n8. لیکن تو، انسان کے بیٹے، جو میں تم سے کہتا ہوں وہ سنو؛ تم اس باغی گھر کی طرح باغی نہ ہو: اپنا منہ کھولو، اور جو میں تمہیں دیتا ہوں وہ کھاؤ۔\n9۔ اور جب میں نے دیکھا، دیکھو، ایک ہاتھ {بھیجا} گیا ہے؛ اور، دیکھو، اس میں ایک کتاب کا رول تھا؛\n10۔ اور اس نے اسے میرے سامنے پھیلایا؛ اور یہ {تھا} اندر اور باہر لکھا تھا: اور {وہاں لکھا تھا} نوحے، ماتم اور افسوس۔","1۔ اس کے علاوہ اس نے مجھ سے کہا، اے انسان کے بیٹے، جو کچھ ملے وہ کھاؤ؛ یہ رول کھاؤ، اور اسرائیل کے گھر سے بات کرو۔\n2۔ تو میں نے منہ کھولا، اور اس نے مجھے وہ رول کھانے پر مجبور کیا۔\n3۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، اپنے پیٹ کو کھلا دے، اور اپنی آنتیں اس رول سے بھر دے جو میں تمہیں دیتا ہوں۔ پھر میں نے اسے کھا لیا؛ اور یہ مٹھاس کے لیے شہد کی طرح میرے منہ میں تھا۔\n4۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، جاؤ، اسرائیل کے گھر جا کر میرے الفاظ سے ان سے بات کرو۔\n5. کیونکہ تو کسی عجیب زبان اور سخت زبان والے قوم کے پاس نہیں بھیجا گیا، بلکہ اسرائیل کے گھر بھیجا گیا ہے؛ {ایک...: عبرانی ہونٹ گہرا، اور زبان بھاری\n6. زیادہ تر لوگوں کے لیے نہیں، جن کی زبان عجیب ہے اور سخت زبان رکھتی ہے، جن کے الفاظ تم سمجھ نہیں سکتے۔ یقینا، اگر میں نے تمہیں ان کے پاس بھیجا ہوتا تو وہ تمہاری بات سنتے۔ {ایک...: عبرانی ہونٹوں کی گہری، اور بھاری زبان میں} {یقینا...: یا، اگر میں نے تمہیں بھیجا ہوتا، وغیرہ، کیا وہ تمہاری بات نہ سنتے؟}\n7۔ لیکن اسرائیل کا گھر تمہاری بات نہیں سنے گا؛ کیونکہ وہ میری بات نہیں سنیں گے: کیونکہ اسرائیل کے تمام خاندان گستاخ اور سخت دل ہیں۔ {گستاخ...: عبرانی۔ ماتھے کی سختی، اور دل سخت}\n8۔ دیکھو، میں نے تمہارا چہرہ ان کے چہروں کے خلاف مضبوط کر دیا ہے، اور تمہارا ماتھا ان کے ماتھے کے خلاف مضبوط کر دیا ہے۔\n9۔ میں نے تمہاری پیشانی کو چقماق سے بھی زیادہ سخت بنایا ہے: ان سے نہ ڈرو، نہ ان کی شکل سے مایوس ہو، چاہے وہ باغی گھرانے کیوں نہ ہوں۔\n10۔ اس کے علاوہ اس نے مجھ سے کہا، اے انسان کے بیٹے، میرے تمام الفاظ جو میں تم سے کہوں گا، وہ سب تمہارے دل میں قبول کرو اور تمہارے کانوں سے سنوں۔\n11۔ اور جاؤ، قید سے ان کے پاس آؤ، اپنے قوم کے بچوں کے پاس، اور ان سے بات کرو، اور انہیں بتاؤ، خداوند خدا یہ فرماتا ہے؛ چاہے وہ سنیں گے، یا برداشت کریں گے۔\n12۔ پھر روح نے مجھے اٹھایا، اور میں نے اپنے پیچھے ایک بڑی دوڑتی ہوئی آواز سنی، {کہہ رہی تھی} کہ خداوند کی جلال اس کی جگہ سے مبارک ہو۔\n13۔ {میں نے سنا} جانداروں کے پروں کی آواز بھی سنی جو ایک دوسرے کو چھو رہے تھے، اور پہیوں کی ان کے خلاف ٹکرانے کی آواز، اور ایک بڑی دوڑ کی آواز۔ {متاثر ہوا: عبوری۔ چوم لیا}\n14۔ تو روح نے مجھے اٹھایا، اور لے گئی، اور میں تلخی میں اپنی روح کی حرارت میں چلا گیا؛ لیکن خداوند کا ہاتھ مجھ پر مضبوط تھا۔ {تلخی میں: عبرانی۔ کڑوا} {حرارت: عبرانی گرم غصہ}\n15۔ پھر میں ان کے پاس تلبیب کی قید کے بارے میں آیا، جو دریائے چبار کے کنارے رہتا تھا، اور میں وہیں بیٹھا رہا جہاں وہ بیٹھے تھے، اور سات دن ان کے درمیان حیران رہ گیا۔\n16۔ اور سات دن کے آخر میں ہوا کہ خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n17۔ اے انسان کے بیٹے، میں نے تمہیں اسرائیل کے گھر کا محافظ بنا دیا ہے، پس میرے منہ سے لفظ سنو اور میری طرف سے انہیں خبردار کر۔\n18۔ جب میں بدکاروں سے کہتا ہوں، تو ضرور مر جاؤ گے؛ اور تم اسے خبردار نہیں کرتے، نہ ہی برے کو اس کے برے راستے سے خبردار کرنے کے لیے بولتے ہو، تاکہ اس کی جان بچاؤ؛ وہی بدکار {انسان} اپنی بدکاری میں مرے گا؛ لیکن اس کا خون مجھے تمہارے ہاتھ میں چاہیے۔\n19۔ لیکن اگر تم بدکاروں کو خبردار کرو، اور وہ اپنی بدکاری یا برے راستے سے نہ منہ موڑے، تو وہ اپنی بدکاری میں مر جائے گا؛ لیکن تم نے اپنی جان بچا لی ہے۔\n20۔ دوبارہ، جب ایک نیک انسان اپنی راستبازی سے منہ موڑ لیتا ہے اور گناہ کرتا ہے، اور میں اس کے سامنے رکاوٹ ڈالتا ہوں، تو وہ مر جائے گا: کیونکہ تم نے اسے خبردار نہیں کیا، وہ اپنے گناہ میں مر جائے گا، اور اس کی راستبازی یاد نہیں رکھی جائے گی؛ لیکن اس کا خون مجھے تمہارے ہاتھ میں چاہیے۔ {راستبازی جو: عبرانی۔ راستبازی}\n21۔ پھر بھی اگر تم نیک انسان کو خبردار کرو کہ نیک گناہ نہیں کرتا، اور وہ گناہ نہیں کرتا، تو وہ ضرور زندہ رہے گا، کیونکہ اسے خبردار کیا گیا ہے؛ اور تم نے اپنی جان بھی بچا لی ہے۔\n22۔ اور خداوند کا ہاتھ میرے اوپر تھا؛ اور اس نے مجھ سے کہا، اٹھو، میدان میں جاؤ، اور میں وہاں تم سے بات کروں گا۔\n23۔ پھر میں اٹھا اور میدان میں نکل آیا: اور دیکھو، خداوند کی شان وہاں کھڑی تھی، جیسا کہ میں نے چبار کے دریا کے کنارے دیکھی تھی: اور میں اپنے چہرے پر گر پڑا۔\n24۔ پھر روح میرے اندر داخل ہوئی، مجھے کھڑا کیا، مجھ سے بات کی، اور کہا، جاؤ، اپنے گھر میں بند ہو جاؤ۔\n25. لیکن تو، اے انسان کے بیٹے، دیکھو، وہ تم پر لکڑیاں لگا دیں گے، اور تمہیں ان کے ساتھ باندھیں گے، اور تم ان کے درمیان باہر نہیں جاؤ گے:\n26۔ اور میں تمہاری زبان کو تمہارے منہ کی چھت سے چپکاؤں گا، تاکہ تم گونگے ہو جاؤ اور ان کے لیے ملامت نہ کرو، کیونکہ وہ باغی گھرانے ہیں۔ {ایک سرزنش کرنے والا: عبوری۔ ایک آدمی جو ڈانٹ رہا ہے}\n27. لیکن جب میں تم سے بات کروں گا، تو میں تمہارا منہ کھولوں گا، اور تم ان سے کہو گے، خداوند خدا یہ فرماتا ہے؛ جو سنتا ہے، وہ سنے؛ اور جو صبر کرتا ہے، وہ برداشت کرے: کیونکہ وہ باغی گھرانے ہیں۔","1۔ اے انسان کے بیٹے، تو بھی ایک ٹائل لے کر اپنے سامنے رکھ دو، اور اس پر شہر بھر دو، حتیٰ کہ یروشلم بھی:\n2۔ اور اس کا محاصرہ کرو، اس کے خلاف قلعہ بناؤ، اور اس کے خلاف ایک گھوڑا کھڑا کرو؛ کیمپ کو بھی اس کے ساتھ لگا دیں، اور اس کے ارد گرد {مارتے ہوئے} مینڈوں کو بھی لگا دیں۔ {مار پیٹ...: چیف لیڈرز}\n3۔ اس کے علاوہ ایک لوہے کا پین اپنے پاس لے آؤ، اور اسے اپنے اور شہر کے درمیان لوہے کی دیوار بنا دو، اور اپنا چہرہ اس کے خلاف رکھو، اور وہ محاصرے میں آ جائے گا، اور تم اس کا محاصرہ کرو گے۔ یہ {ہوگی} اسرائیل کے گھر کے لیے ایک نشانی ہوگی۔ {ایک...: یا، ایک فلیٹ پلیٹ، یا، سلائس}\n4۔ تم بھی اپنے بائیں طرف لیٹ جاؤ، اور اسرائیل کے خاندان کی گناہوں کو اس پر رکھو: ان دنوں کی تعداد کے مطابق جو تم اس پر رکھو گے، تم ان کی گناہوں کو برداشت کرو گے۔\n5۔ کیونکہ میں نے تم پر ان کی بدکاری کے سال دنوں کے حساب سے تین سو نوے دن مقرر کیے ہیں: یوں تم اسرائیل کے خاندان کی بدکاری برداشت کرو گے۔\n6۔ اور جب تم یہ سب کر لو، تو دوبارہ اپنے دائیں طرف لیٹ جاؤ، اور تم یہوداہ خاندان کی بدکاری چالیس دن برداشت کرو گے: میں نے تمہیں ہر دن ایک سال کے لیے مقرر کیا ہے۔ {ہر ایک...: عبرانی۔ ایک دن ایک سال کے لیے، ایک دن ایک سال کے لیے}\n7۔ اس لیے تم یروشلم کے محاصرے کی طرف منہ کرو، اور تمہارا بازو کھل جائے گا، اور اس کے خلاف نبوت کرو گے۔\n8۔ اور دیکھو، میں تم پر لشکریاں لگا دوں گا، اور تم تمہیں ایک طرف سے دوسری طرف نہیں موڑو گے، جب تک کہ تم محاصرے کے دن ختم نہ کر لو۔ {ایک سے...: عبرانی۔ تیری طرف سے تمہارے پہلو تک}\n9۔ تم گندم، جو، پھلیاں، دال، باجرہ اور فچز بھی اپنے پاس لے آؤ، انہیں ایک برتن میں ڈال کر اس سے روٹی بنا لو، ان دنوں کے حساب سے جو تم اپنے پہلو میں لیٹے رہو گے، تین سو نوے دن اس میں سے کھاؤ گے۔ {fitches: or, spellt}\n10۔ اور تمہارا گوشت جو تم کھاؤ گے، وزن کے حساب سے بیس شیکل روزانہ ہوگا: کبھی کبھار تم اسے کھاؤ گے۔\n11۔ تم پانی کو بھی پیو گے، ایک ہین کا چھٹا حصہ: وقتا فوقتا پیو گے۔\n12۔ اور تم اسے جو کے کیک کی طرح کھاؤ گے، اور اسے اس گوبر سے پکاؤ گے جو انسان سے نکلتا ہے، ان کی نظر میں۔\n13۔ اور خداوند نے فرمایا، اسی طرح بنی اسرائیل اپنی ناپاک روٹی غیر یہودیوں کے درمیان کھائیں گے، جہاں میں انہیں نکالوں گا۔\n14۔ پھر میں نے کہا، اے خداوند خدا! دیکھو، میری روح آلودہ نہیں ہوئی: کیونکہ اپنی جوانی سے لے کر اب تک میں نے اس چیز کو نہیں کھایا جو خود بخود مر جاتی ہے یا ٹکڑے ٹکڑے ہو جاتی ہے؛ نہ ہی کوئی گھناونا گوشت میرے منہ میں آیا۔\n15۔ پھر اس نے مجھ سے کہا، دیکھو، میں نے تمہیں گائے کا گوبر انسان کی گوبر کے بدلے دے دیا ہے، اور تم اسی سے اپنی روٹی تیار کرو گے۔\n16۔ اس کے علاوہ اس نے مجھ سے کہا، اے انسان کے بیٹے، دیکھو، میں یروشلم میں روٹی کی چھڑی توڑوں گا: اور وہ وزن کے حساب سے اور احتیاط سے روٹی کھائیں گے؛ اور وہ پیمائش کے ساتھ اور حیرت کے ساتھ پانی پیئیں گے:\n17۔ تاکہ وہ روٹی اور پانی چاہیں، ایک دوسرے سے حیران ہو جائیں، اور اپنی گناہوں کے بدلے کھا جائیں۔","1۔ اور تم، انسان کے بیٹے، ایک تیز چاقو لے آؤ، ایک حجام کا ریزر لے آؤ، اور اسے اپنے سر اور داڑھی پر لگا دو، پھر اپنے توازن لے کر وزن کرو، اور بال تقسیم کرو۔\n2۔ جب محاصرے کے دن مکمل ہو جائیں گے تو شہر کے بیچ میں ایک تہائی حصہ آگ سے جلاؤ گے: اور ایک تہائی حصہ لے کر اس کے گرد چھری سے وار کرو گے؛ اور تیسرا حصہ ہوا میں بکھیر دو گے؛ اور میں ان کے پیچھے تلوار نکالوں گا۔\n3۔ تم ان میں سے چند کو بھی لے کر اپنی چادروں میں باندھنا۔ {اسکرٹس: ہیب۔ ونگز}\n4۔ پھر انہیں دوبارہ لے لو، آگ کے بیچ میں پھینک دو، اور آگ میں جلا دو؛ {کیونکہ} اسی سے ایک آگ پورے اسرائیل کے گھر میں پھوٹے گی۔\n5۔ خداوند خدا یہ فرماتا ہے؛ یہ {ہے} یروشلم: میں نے اسے ان قوموں اور ممالک کے درمیان رکھا ہے جو اس کے ارد گرد ہیں۔\n6۔ اور اس نے میرے فیصلوں کو قوموں سے زیادہ برائی میں بدل دیا ہے، اور میرے قوانین کو ان ممالک سے زیادہ جو اس کے ارد گرد ہیں، کیونکہ انہوں نے میرے فیصلوں اور قوانین کو رد کیا ہے، وہ ان میں نہیں چلے گئے۔\n7۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ کیونکہ تم نے ان قوموں سے زیادہ بڑھ گئے جو تمہارے ارد گرد ہیں، {اور} میرے قوانین میں نہیں چلے، نہ میرے فیصلے پورے کیے، نہ ہی ان قوموں کے فیصلوں کے مطابق کیا جو تمہارے ارد گرد ہیں؛\n8۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ دیکھو، میں، خود میں بھی، تمہارے خلاف ہوں، اور تمہارے درمیان قوموں کی نظر میں فیصلے کروں گا۔\n9۔ اور میں تم میں وہ کروں گا جو میں نے نہیں کیا، اور جس کے لیے میں مزید ایسا نہیں کروں گا، تیری تمام گناہوں کی وجہ سے۔\n10۔ لہٰذا باپ تمہارے درمیان بیٹوں کو کھائیں گے، اور بیٹے اپنے باپوں کو کھائیں گے؛ اور میں تم پر فیصلے کروں گا، اور تمہاری باقی ماندہ سب ہواؤں میں بکھیر دوں گا۔\n11۔ لہٰذا، {جیسا کہ میں زندہ ہوں}، خداوند خدا فرماتا ہے؛ یقینا، چونکہ تم نے میری پناہ گاہ کو اپنی تمام نفرت انگیز چیزوں اور اپنی تمام گناہوں سے آلودہ کیا ہے، اسی لیے میں بھی تمہیں کم تر کروں گا؛ نہ ہی میری آنکھ چھوڑے گی، نہ ہی مجھے کوئی رحم آئے گا۔\n12۔ تمہارا ایک تہائی حصہ وبا سے مر جائے گا، اور قحط سے وہ تمہارے درمیان میں ختم ہو جائے گا؛ اور تیسرا حصہ تلوار سے تمہارے گرد گر جائے گا؛ اور میں تیسرا حصہ تمام ہواؤں میں بکھیر دوں گا، اور ان کے پیچھے تلوار نکالوں گا۔\n13۔ یوں میرا غصہ ختم ہوگا، اور میں اپنا غصہ ان پر نازل کروں گا، اور مجھے تسلی ملے گی: اور وہ جان لیں گے کہ میں خداوند نے اپنی جوش میں یہ بات کہی ہے، جب میں نے ان میں اپنا غصہ پورا کیا ہے۔\n14۔ مزید برآں، میں تمہیں تباہ کر دوں گا، اور ان قوموں میں ملامت کروں گا جو تمہارے ارد گرد ہیں، ہر گزرنے والے کی نظر میں۔\n15. تو یہ ایک ملامت اور طعن، ایک ہدایت اور حیرت ہوگی ان قوموں کے لیے جو آپ کے ارد گرد ہیں، جب میں آپ پر غصے، غصے اور شدید سرزنش میں فیصلے کروں گا۔ میں نے خداوند نے کہا ہے۔\n16۔ جب میں ان پر قحط کے برے تیر بھیجوں گا، جو {ان} کی تباہی کے لیے ہوں گے، {اور} جنہیں میں تمہیں تباہ کرنے کے لیے بھیجوں گا: اور میں تم پر قحط بڑھاؤں گا، اور تمہاری روٹی کی چھڑی توڑ دوں گا:\n17. اسی طرح میں تم پر قحط اور برے جانور بھیجوں گا، اور وہ تمہیں غمگین کر دیں گے؛ اور وبا اور خون تمہارے جسم سے گزریں گے؛ اور میں تلوار تم پر لاؤں گا۔ میں نے خداوند نے کہا ہے۔","1۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، اپنا چہرہ اسرائیل کے پہاڑوں کی طرف موڑو اور ان کے خلاف پیش گوئی کرو،\n3۔ اور کہو، اے اسرائیل کے پہاڑوں، خداوند خدا کا کلام سنو؛ خداوند خدا پہاڑوں، پہاڑوں، دریاؤں اور وادیوں سے یوں فرماتا ہے؛ دیکھو، میں، {حتیٰ کہ} میں، تم پر تلوار لاؤں گا، اور تمہارے بلند مقامات کو تباہ کر دوں گا۔\n4۔ اور تمہارے محراب ویران ہوں گے، اور تمہاری تصویریں توڑ دی جائیں گی: اور میں تمہارے مارے گئے {لوگ} تمہارے بتوں کے سامنے پھینک دوں گا۔ {تصاویر: یا، سورج کی تصاویر}\n5۔ اور میں بنی اسرائیل کی مردہ لاشیں ان کے بتوں کے سامنے رکھوں گا؛ اور میں تمہاری ہڈیاں تمہارے قربان گاہوں کے ارد گرد بکھیر دوں گا۔ {lay: heb. دیں}\n6۔ تمہارے تمام گھروں میں شہر تباہ ہو جائیں گے، اور اونچی جگہیں ویران ہو جائیں گی؛ تاکہ تمہارے محراب تباہ ہو جائیں اور ویران ہو جائیں، تمہارے بتوں کو توڑ کر بند کر دیا جائے، تمہارے مجسمے کاٹ دیے جائیں، اور تمہارے اعمال ختم ہو جائیں۔ {تصاویر: یا، سورج کی تصاویر}\n7۔ اور جو مارے گئے وہ تمہارے درمیان گر جائیں گے، اور تم جان لو گے کہ میں خداوند ہوں۔\n8۔ پھر بھی میں ایک باقیات چھوڑوں گا، تاکہ تمہیں کچھ ملے جو قوموں میں تلوار سے بچ جائے، جب تم ملکوں میں بکھر جاؤ گے۔\n9۔ اور جو تم سے بچ نکلیں گے وہ مجھے ان قوموں میں یاد کریں گے جہاں انہیں قیدی بنایا جائے گا، کیونکہ میں ان کے بدکار دل سے ٹوٹ گیا ہوں جو مجھ سے جدا ہو گیا ہے، اور ان کی آنکھوں سے جو اپنے بتوں کے پیچھے بدکاری کرتی ہیں: اور وہ اپنی تمام گناہوں میں کی گئی برائیوں پر خود کو نفرت کریں گے۔\n10۔ اور وہ جان جائیں گے کہ میں خداوند ہوں، اور میں نے بے سود نہیں کہا کہ میں ان کے ساتھ یہ برائی کرنا چاہتا ہوں۔\n11۔ خداوند خدا یہ فرماتا ہے؛ اپنے ہاتھ سے مارو، اور اپنے پاؤں سے پاؤں مارو، اور کہو، اسرائیل کے گھر کی تمام برائیوں پر افسوس کرو! کیونکہ وہ تلوار، قحط اور وبا سے گریں گے۔\n12۔ جو دور ہے وہ وبا سے مر جائے گا؛ اور جو قریب ہے وہ تلوار کے ہاتھوں مارا جائے گا؛ اور جو باقی رہے گا اور محاصرے میں ہے وہ قحط سے مر جائے گا: یوں میں ان پر اپنا غصہ مکمل کروں گا۔\n13۔ تب تم جان لو گے کہ میں خداوند ہوں، جب ان کے مارے گئے {لوگ} ان کے بتوں میں ان کے قربان گاہوں کے ارد گرد، ہر اونچی پہاڑی پر، پہاڑوں کی تمام چوٹیوں پر، ہر سبز درخت کے نیچے، اور ہر گھنے بلوط کے درخت کے نیچے، وہ جگہ ہوں گی جہاں انہوں نے اپنے تمام بتوں کو میٹھا ذائقہ پیش کیا۔\n14۔ اسی طرح میں ان پر ہاتھ بڑھاؤں گا، اور زمین کو ویران بنا دوں گا، ہاں، دبلات کی طرف ویرانے سے بھی زیادہ ویران بنا دوں گا، ان کے تمام بستوں میں: اور وہ جان جائیں گے کہ میں خداوند ہوں۔ {مزید...: یا، جنگل سے ویران ہوں}","1۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، خداوند خدا اسرائیل کی سرزمین سے یوں فرماتا ہے؛ ایک اختتام، اختتام زمین کے چاروں کونوں پر آتا ہے۔\n3۔ اب {ہے} انجام {آ رہا ہے} تم پر، اور میں اپنا غصہ تم پر نازل کروں گا، اور تمہارے طریقوں کے مطابق تمہیں فیصلہ کروں گا، اور تمہارے تمام گناہوں کا بدلہ دوں گا۔ {معاوضہ: عبرانی۔ دیں}\n4۔ اور میری آنکھ تمہیں نہیں بخشے گی، نہ ہی مجھے رحم آئے گا، بلکہ میں تمہارے راستے تم پر بدلہ دوں گا، اور تمہاری گناہوں کے بیچ میں ہوں گے، اور تم جان لو گے کہ میں خداوند ہوں۔\n5۔ خداوند خدا یہ فرماتا ہے؛ ایک برائی، واحد برائی، دیکھو، آ گئی ہے۔\n6۔ اختتام آ گیا ہے، انجام آ گیا ہے: وہ تمہاری نگرانی کرتا ہے؛ دیکھو، یہ آ گیا ہے۔ {دیکھتے ہیں: عبرانی۔ اس کے خلاف جاگنا}\n7. اے زمین پر رہنے والے تم پر صبح آ گئی ہے: وقت آ گیا ہے، مصیبت کا دن قریب ہے، اور پہاڑوں کی دوبارہ آواز نہیں۔ {آواز...: یا، گونج}\n8۔ اب میں جلد ہی اپنا غصہ تم پر نکالوں گا، اور اپنا غصہ تم پر پورا کروں گا: اور میں تمہارے طریقوں کے مطابق فیصلہ کروں گا، اور تمہیں تمہاری تمام گناہوں کا بدلہ دوں گا۔\n9۔ اور میری آنکھ رحم نہیں کرے گی، نہ ہی مجھے رحم ہوگا: میں تمہیں تمہارے طریقوں اور تمہارے گناہوں کے مطابق بدلہ دوں گا جو تمہارے درمیان ہیں؛ اور تم جان لو گے کہ میں وہ خداوند ہوں جو مارتا ہے۔ {آپ کے مطابق: عبرانی۔ تمہارے اوپر، وغیرہ}\n10۔ دیکھو دن آ گیا ہے: صبح گزر چکی ہے؛ چھڑی کھل چکی ہے، فخر پھول چکا ہے۔\n11. تشدد برائی کے لاٹھے میں اٹھا دیا جاتا ہے: نہ ان میں سے کوئی باقی رہے گا، نہ ان کی ہجوم سے، نہ ان میں سے کسی کے لیے: نہ ہی ان کے لیے رونے کی کوشش کی جائے گی۔ {ان کا: یا، ان کے ہنگامہ خیز شخصیات: عبرانی۔ ہنگامہ\n12۔ وقت آ گیا ہے، دن قریب آ رہا ہے: خریدار خوش نہ ہو، نہ بیچنے والا ماتم کرے: کیونکہ غصہ سب پر ہے۔\n13۔ کیونکہ بیچنے والا اس چیز پر واپس نہیں جائے گا جو بیچی گئی ہے، چاہے وہ زندہ ہی کیوں نہ ہو: کیونکہ وہ خواب {ہے} اس کی پوری کثرت کو چھو رہا ہے، {جو} واپس نہیں آئے گا؛ اور نہ ہی کوئی اپنی زندگی کی بدکاری میں خود کو مضبوط کرے گا۔ {اگرچہ وہ...: عبرانی۔ اگرچہ ان کی زندگی ابھی زندہ تھی} {میں...: یا، جس کی زندگی اس کی بدکاری میں ہے} {بدکاری: عبرانی۔ اس کی بدکاری}\n14۔ انہوں نے بگل بجایا، یہاں تک کہ سب کچھ تیار کرنے کے لیے؛ لیکن کوئی بھی جنگ میں نہیں جاتا: کیونکہ میرا غصہ ان سب پر ہے۔\n15۔ تلوار {ہے} باہر، اور وبا اور قحط اندر سے: جو {ہے} وہ تلوار کے ساتھ مر جائے گا؛ اور جو شہر میں ہے، قحط اور وبا اسے نگل جائے گی۔\n16۔ لیکن جو ان سے بچ نکلیں گے وہ بھاگ جائیں گے، اور پہاڑوں پر وادیوں کے کبوتر کی طرح ہوں گے، سب سوگ منائیں گے، ہر ایک اپنی گناہ کے لیے۔\n17۔ تمام ہاتھ کمزور ہوں گے، اور تمام گھٹنے پانی کی طرح کمزور ہوں گے۔ {کمزور رہو...: عبرانی۔ پانی میں جاؤ}\n18۔ وہ خود کو تھیلے کے کپڑے سے بھی باندھیں گے، اور خوف انہیں ڈھانپے گا؛ اور شرمندگی ہر چہرے پر، اور گنج پن سب کے سروں پر۔\n19۔ وہ اپنی چاندی گلیوں میں پھینکیں گے، اور ان کا سونا نکال دیا جائے گا: ان کی چاندی اور سونا انہیں خداوند کے غضب کے دن نجات نہیں دے سکیں گے، نہ اپنی روحیں مطمئن کریں گے، نہ ہی اپنی آنتیں بھر سکیں گے، کیونکہ یہ ان کی گناہوں کی رکاوٹ ہے۔ {ہٹا دیا گیا: عبرانی۔ جدائی کے لیے، یا، ناپاکی} {یہ ہے...: یا، ان کی بدکاری ان کی رکاوٹ ہے}\n20۔ جہاں تک اس کے زیور کی خوبصورتی کا تعلق ہے، اس نے اسے شان سے سجایا ہے: لیکن انہوں نے اپنی گندی چیزوں کی تصویریں {اور} ان میں اپنی نفرت انگیز چیزوں کی بنا دی: اسی لیے میں نے اسے ان سے دور رکھا ہے۔ {دور رکھو...: یا، انہیں ناپاک بنا دیا}\n21۔ اور میں اسے اجنبیوں کے ہاتھوں میں شکار کے طور پر دوں گا، اور زمین کے بدکاروں کو مال غنیمت کے طور پر؛ اور وہ اسے آلودہ کریں گے۔\n22. میں بھی میرا چہرہ ان سے منہ موڑوں گا، اور وہ میری خفیہ جگہ کو آلودہ کریں گے: کیونکہ ڈاکو اس میں داخل ہوں گے اور اسے ناپاک کریں گے۔ {ڈاکو: یا، چور}\n23۔ زنجیر بناؤ: کیونکہ زمین خونریز جرائم سے بھری ہوئی ہے، اور شہر تشدد سے بھرا ہوا ہے۔\n24۔ اسی لیے میں بدترین کافروں کو لاؤں گا، اور وہ اپنے گھروں پر قبضہ کر لیں گے: میں طاقتوروں کی شان و شوکت کو بھی روک دوں گا؛ اور ان کی مقدس جگہیں بے حرمتی کی جائیں گی۔ {ان کے مقدس...: یا، وہ اپنے مقدس مقامات کے وارث بنیں گے}\n25۔ تباہی آتی ہے؛ اور وہ امن کی تلاش کریں گے، اور کوئی نہیں ہوگا۔ {تباہی: عبرانی۔ کٹ آؤٹ}\n26۔ شرارت مصیبت پر آتی ہے، اور افواہ افواہ پر؛ پھر وہ نبی کا خواب تلاش کریں گے؛ لیکن قانون پادری سے فنا ہو جائے گا، اور قدیم لوگوں سے نصیحت بھی۔\n27۔ بادشاہ سوگ منائے گا، اور شہزادہ ویرانی میں ملبوس ہو جائے گا، اور ملک کے لوگوں کے ہاتھ پریشان ہوں گے: میں ان کے راستے کے مطابق ان کے ساتھ کروں گا، اور ان کے راستے کے مطابق ان کا فیصلہ کروں گا؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔ {مطابق...: عبرانی ان کے فیصلوں کے ساتھ}","1۔ اور چھٹے سال میں، چھٹے مہینے میں، مہینے کے پانچویں دن میں، جب میں اپنے گھر میں بیٹھا تھا اور یہوداہ کے بزرگ میرے سامنے بیٹھے تھے، تو خداوند خدا کا ہاتھ مجھ پر پڑا۔\n2. پھر میں نے آگ کی شکل دیکھی: اس کی کمر کی ظاہری شکل سے نیچے کی طرف آگ؛ اور اس کی کمر سے اوپر کی طرف، روشنی کی ظاہری شکل، عنبر رنگ کی طرح۔\n3۔ اور اس نے ہاتھ کی شکل اختیار کی، اور میرے سر کے گچھے سے پکڑ لیا؛ اور روح نے مجھے زمین اور آسمان کے درمیان اٹھایا، اور خدا کے خوابوں میں مجھے یروشلم لے آیا، اس اندرونی دروازے کے دروازے تک جو شمال کی طرف دیکھتا ہے؛ جہاں حسد کی تصویر کی نشست تھی، جو حسد کو ابھارتی ہے۔\n4۔ اور دیکھو، اسرائیل کے خدا کی شان وہاں تھی، جیسا کہ میں نے میدان میں دیکھا۔\n5۔ پھر اس نے مجھ سے کہا، اے انسان کے بیٹے، اب اپنی آنکھیں شمال کی طرف اٹھاؤ۔ تو میں نے شمال کی طرف اپنی آنکھیں اٹھائیں، اور شمال کی طرف قربان گاہ کے دروازے پر حسد کی تصویر دیکھی۔\n6۔ اس نے مجھ سے مزید کہا، اے انسان کے بیٹے، کیا تم دیکھتے ہو کہ وہ کیا کرتے ہیں؟ {حتیٰ کہ} وہ عظیم گنایاں جو اسرائیل کے گھر نے یہاں کی ہیں، کہ میں اپنی پناہ گاہ سے دور چلا جاؤں؟ لیکن پھر سے مڑ جاؤ، {اور} تم اس سے بھی بڑی مکروہ چیزیں دیکھو گے۔\n7۔ اور وہ مجھے عدالت کے دروازے تک لے آیا؛ اور جب میں نے دیکھا تو دیوار میں ایک سوراخ تھا۔\n8۔ پھر اس نے مجھ سے کہا، اے انسان کے بیٹے، اب دیوار میں کھودو: اور جب میں نے دیوار میں کھودا تو دیکھو ایک دروازہ۔\n9۔ اور اس نے مجھ سے کہا، اندر جاؤ، اور دیکھو یہاں وہ کون سی بدکار حرکتیں کرتے ہیں۔\n10۔ تو میں اندر گیا اور دیکھا؛ اور دیکھو کہ ہر قسم کی رینگنے والی چیزیں، مکروہ جانور، اور اسرائیل کے گھر کے تمام بت، دیوار پر بکھرے ہوئے ہیں۔\n11۔ اور ان کے سامنے اسرائیل کے گھر کے قدیم افراد کے ستر مرد کھڑے تھے، اور ان کے درمیان شافان کا بیٹا یعقوبیاہ کھڑا تھا، ہر آدمی کے ہاتھ میں بخور تھا؛ اور دھوئیں کا ایک گھنا بادل اوپر اٹھا۔\n12۔ پھر اس نے مجھ سے کہا، اے انسان کے بیٹے، کیا تم نے دیکھا ہے کہ اسرائیل کے قدیم لوگ اندھیرے میں کیا کرتے ہیں، ہر آدمی اپنی تصویروں کے کمروں میں؟ کیونکہ وہ کہتے ہیں، خداوند ہمیں نہیں دیکھتا؛ خداوند نے زمین کو چھوڑ دیا ہے۔\n13۔ اس نے مجھ سے یہ بھی کہا، ایک بار پھر پلٹ جاؤ، {اور} تم ان سے بھی بڑی گناہوں کو دیکھو گے۔\n14۔ پھر وہ مجھے خداوند کے گھر کے دروازے کے دروازے تک لے گیا جو شمال کی طرف تھا؛ اور دیکھو، وہاں عورتیں بیٹھی تھیں جو تموز کے لیے رو رہی تھیں۔\n15۔ پھر اس نے مجھ سے کہا، کیا تم نے یہ دیکھا ہے، اے انسان کے بیٹے؟ ایک بار پھر مڑو، {اور} تم ان سے بھی بڑی گنایاں دیکھو گے۔\n16۔ اور اس نے مجھے خداوند کے گھر کے اندرونی صحن میں لے جایا، اور دیکھتے ہوئے، خداوند کے مندر کے دروازے پر، برآمدے اور قربان گاہ کے درمیان، تقریبا پانچ بیس آدمی تھے، جن کی پیٹھ خداوند کے مندر کی طرف اور چہرے مشرق کی طرف تھے؛ اور وہ مشرق کی طرف سورج کی عبادت کرتے تھے۔\n17۔ پھر اس نے مجھ سے کہا، اے انسان کے بیٹے، کیا تم نے یہ دیکھا ہے؟ کیا یہوداہ خاندان کے لیے یہ کوئی آسان بات ہے کہ وہ یہاں جو مکروہ کام کرتے ہیں وہ کرتے ہیں؟ کیونکہ انہوں نے زمین کو تشدد سے بھر دیا ہے، اور واپس آئے ہیں تاکہ مجھے غصہ دلا سکیں: اور دیکھو، انہوں نے شاخ اپنی ناک سے لگا دی۔ {کیا یہ...: یا، کیا اس سے زیادہ ہلکی کوئی چیز ہے جو کرنا ضروری ہے}\n18۔ لہٰذا میں بھی غصے میں مبتلا ہوں گا: میری آنکھ رحم نہیں کرے گی، نہ ہی رحم کرے گا: اور اگرچہ وہ میرے کانوں میں زور سے پکار رہے ہیں، {پھر بھی} میں انہیں سنوں گا نہیں۔","1۔ اس نے میرے کانوں میں بھی زور سے پکارا، کہا، جو شہر پر قابض ہیں انہیں قریب لے آؤ، حتیٰ کہ ہر آدمی کے ہاتھ میں تباہ کن ہتھیار ہے۔\n2۔ اور دیکھو، چھ آدمی شمال کی طرف واقع اونچے دروازے کے راستے سے آئے، اور ہر آدمی کے ہاتھ میں ذبح کا ہتھیار تھا؛ اور ان میں سے ایک آدمی کپڑے میں ملبوس تھا، اس کے ساتھ ایک مصنف کا سیاہی کا سینگ تھا: اور وہ اندر گئے، اور براسن کے محراب کے پاس کھڑے ہو گئے۔ {جو لیتھ: عبرانی۔ جو تبدیل ہو جاتا ہے} {ایک ذبح...: عبرانی۔ ایک ہتھیار جو اس کے ٹکڑوں میں ٹوٹ رہا ہے} {اس کی...: عبرانی کے ذریعے۔ اس کی کمر پر}\n3۔ اور اسرائیل کے خدا کی شان فرشتہ سے لے کر گھر کے دہانے تک پہنچ گئی۔ اور اس نے اس آدمی کو بلایا جو کپڑے میں ملبوس تھا، جس کے ساتھ مصنف کا سیاہی کا سینگ تھا؛\n4۔ اور خداوند نے اس سے کہا، شہر کے بیچ، یروشلم کے بیچ سے گزر جا، اور ان لوگوں کے ماتھے پر نشان لگا دو جو آہیں بھرتے ہیں اور ان تمام گناہوں کے لیے پکار رہے ہیں جو اس کے درمیان ہوں گی۔ {نشان لگاؤ: عبوری۔ مارک کریں}\n5۔ اور دوسروں سے اس نے میری سماعت میں کہا، شہر میں اس کے پیچھے جاؤ اور مارو: اپنی آنکھ نہ چھوڑو، نہ رحم کرو: {میری سماعت: عبرانی۔ میرے کان}\n6۔ بوڑھے اور جوانوں کو مکمل طور پر قتل کرو، دونوں، چھوٹے بچوں اور عورتوں کو، لیکن کسی ایسے آدمی کے قریب نہ آؤ جس پر {نشان} لگا ہو؛ اور میرے مقدس مقام سے شروع کریں۔ پھر انہوں نے قدیم انسانوں کی طرف دیکھا جو گھر سے پہلے تھے۔ {مکمل طور پر: عبرانی۔ تباہی تک}\n7۔ اور اس نے ان سے کہا، گھر کو ناپاک کرو، اور درباروں کو مقتولوں سے بھر دو: باہر جاؤ۔ اور وہ آگے بڑھے، اور شہر میں قتل کر دیا۔\n8۔ اور جب وہ انہیں مار رہے تھے، اور میں چھوڑ گیا، تو میں اپنے چہرے پر گر گیا، رونے لگا، اور کہا، اے خداوند! کیا تم یروشلم پر اپنے غصے میں اسرائیل کی تمام باقیات کو تباہ کر دو گے؟\n9۔ پھر اس نے مجھ سے کہا، اسرائیل اور یہوداہ کے گھرانے کی بدکاری بہت بڑی ہے، اور زمین خون سے بھری ہوئی ہے، اور شہر گناہوں سے بھرا ہوا ہے: کیونکہ وہ کہتے ہیں، خداوند نے زمین کو چھوڑ دیا ہے، اور خداوند نہیں دیکھتا۔ خون سے بھرا ہوا: عبرانی۔ وغیرہ} سے بھرا ہوا {انحراف: یا، فیصلے کی کشمکش}\n10۔ اور جہاں تک میرا تعلق ہے، میری آنکھ رحم نہیں کرے گی، نہ ہی مجھے رحم ہوگا، {لیکن} میں ان کے سر پر ان کے راستے کا بدلہ دوں گا۔\n11۔ اور دیکھو، وہ آدمی جو چادروں میں ملبوس تھا، جس کے پاس سیاہی کا سینگ تھا، نے معاملہ بیان کیا، کہہ رہا تھا، میں نے وہی کیا جو تم نے مجھے حکم دیا ہے۔ {رپورٹ شدہ...: عبرانی۔ جواب دیا}","1۔ پھر میں نے دیکھا، اور دیکھو، فرشتہوں کے سر کے اوپر جو آسمان تھا، ان کے اوپر نیلم کا پتھر تھا، تخت کی شکل کی طرح۔\n2۔ اور اس نے کپڑے پہنے ہوئے آدمی سے کہا، اور کہا، پہیوں کے درمیان جاؤ، {حتی} فرشتہ کے نیچے بھی، اور اپنے ہاتھ کو کروب کے درمیان سے آگ کے کوئلے سے بھر دو، اور انہیں شہر میں بکھیر دو۔ اور وہ میری نظر میں آ گیا۔ {تمہارا ہاتھ: عبرانی۔ تمہارے ہاتھ کا کھوکھلا}\n3۔ جب وہ آدمی اندر گیا تو فرشتے گھر کے دائیں طرف کھڑے تھے؛ اور بادل نے اندرونی صحن کو بھر دیا۔\n4۔ پھر خداوند کی شان فرشتہ سے اوپر چڑھی، {اور گھر کے دہانے پر کھڑا ہوا}؛ اور گھر بادلوں سے بھر گیا، اور دربار خداوند کی جلال کی روشنی سے بھر گیا۔ {اوپر گیا: عبوری۔ اٹھا دیا گیا}\n5۔ اور کروبیوں کے پروں کی آواز بیرونی صحن تک بھی سنی گئی، جیسے قادر مطلق خدا کی آواز جب وہ بولتا ہے۔\n6۔ اور ایسا ہوا، {و} جب اس نے کپڑے پہنے آدمی کو حکم دیا کہ پہیوں کے درمیان، فرشتے کے درمیان سے آگ لو؛ پھر وہ اندر گیا، اور پہیوں کے پاس کھڑا ہو گیا۔\n7۔ اور {ایک} فرشتہ نے اپنا ہاتھ کروبیوں کے درمیان سے آگ کی طرف بڑھایا جو کربیوں کے درمیان تھی، اور {اس سے} لے کر {وہ} کے ہاتھوں میں دیا جو کپڑوں میں ملبوس تھا، جس نے {یہ} لیا اور باہر چلا گیا۔ {آگے بڑھتے ہوئے: عبرانی۔ بھیجا گیا}\n8۔ اور فرشتے میں ان کے پروں کے نیچے ایک آدمی کے ہاتھ کی شکل ظاہر ہوئی۔\n9۔ اور جب میں نے دیکھا، تو دیکھو فرشتہ کے چار پہیے، ایک پہیہ ایک فرشتہ، اور دوسرا پہیہ دوسرے فرشتہ سے: اور پہیوں کی شکل بیریل پتھر کے رنگ کی طرح تھی۔\n10۔ اور ان کی ظاہری شکل کے بارے میں، ان چاروں کی ایک ہی شکل تھی، جیسے کوئی پہیہ پہیے کے بیچ میں ہو۔\n11۔ جب وہ گئے، تو چاروں طرف چلے گئے؛ وہ جاتے ہوئے نہیں بلکہ اس جگہ کی طرف مڑے جہاں سر نظر آتا تھا؛ وہ جاتے ہوئے مڑے نہیں۔\n12۔ اور ان کا پورا جسم، ان کی پیٹھ، ان کے ہاتھ، اور ان کے پر، اور پہیے، {تھا} آنکھوں سے بھرے ہوئے تھے، {حتی} کہ وہ پہیے جو ان چاروں کے پاس تھے۔ {جسم: عبوری۔ گوشت}\n13. جہاں تک پہیوں کا تعلق ہے، یہ میرے سامنے ان سے پکارا گیا، اے پہیہ۔ {یہ تھا...: یا، وہ میری سماعت میں پکارے گئے، پہیہ، یا، گلگل}\n14۔ اور ہر چہرہ چار چہرے تھے: پہلا چہرہ ایک فرشتہ کا چہرہ تھا، دوسرا چہرہ انسان کا چہرہ تھا، تیسرا چہرہ شیر کا تھا، اور چوتھا چہرہ عقاب کا تھا۔\n15۔ اور کروبی کو اٹھا لیا گیا۔ یہ وہ زندہ مخلوق ہے جسے میں نے چبار دریا کے کنارے دیکھا تھا۔\n16۔ اور جب کروبی چلے گئے، تو پہیے ان کے پاس سے گزرے: اور جب کروبی اپنے پر اٹھا کر زمین سے سوار ہوئے، تو وہی پہیے بھی ان کے پاس سے نہیں گھومے۔\n17۔ جب وہ کھڑے ہوئے، {یہ} کھڑے ہوئے؛ اور جب وہ اٹھے گئے، {یہ} خود بھی اٹھ گئے: کیونکہ زندہ مخلوق کی روح {تھی} ان میں تھی۔ {کا...: یا، زندگی کا}\n18۔ پھر خداوند کی شان گھر کے دہانے سے نکل کر کروبیوں کے اوپر کھڑی ہو گئی۔\n19۔ اور فرشتہوں نے اپنے پر اٹھا لیے، اور زمین سے میرے سامنے سوار ہو گئے: جب وہ باہر نکلے، تو پہیے بھی ان کے ساتھ تھے، اور {ہر ایک} خداوند کے گھر کے مشرقی دروازے کے دروازے پر کھڑا تھا؛ اور اسرائیل کے خدا کی شان ان پر اوپر تھی۔\n20. یہ وہ زندہ مخلوق ہے جسے میں نے اسرائیل کے خدا کے نیچے دریائے چبار کے کنارے دیکھا؛ اور میں جانتا تھا کہ وہ {کروبیم} تھے۔\n21. ہر ایک کے چار چہرے تھے، اور ہر ایک کے چار پر؛ اور ان کے پروں کے نیچے ایک آدمی کے ہاتھوں کی شکل تھی۔\n22۔ اور ان کے چہروں کی مماثلت وہی تھی جو میں نے چبار کے دریا کے کنارے دیکھی تھی، ان کی شکل و صورت اور خود: وہ سب سیدھے سیدھے تھے۔","1۔ اور روح نے مجھے اٹھایا اور مجھے خداوند کے گھر کے مشرقی دروازے تک لے گیا، جو مشرق کی طرف دیکھتا ہے: اور دیکھو دروازے کے دروازے پر پانچ اور بیس آدمی ہیں؛ جن میں میں میں نے یعزانیاہ کو آزور کا بیٹا اور پیلاطیا کو بنایا کا بیٹا دیکھا، جو قوم کے شہزادے تھے۔\n2۔ پھر اس نے مجھ سے کہا، اے انسان کے بیٹے، یہ وہ لوگ ہیں جو اس شہر میں شرارتیں کرتے ہیں اور برے مشورے دیتے ہیں:\n3۔ جو کہتا ہے، {یہ قریب نہیں ہے}؛ آئیے گھر بنائیں: یہ {شہر} دیگ ہے، اور ہم {جسم} ہیں۔ {یہ ہے...: یا، ہمارے کام نہیں کہ ہم قریب گھر بنائیں}\n4. لہٰذا ان کے خلاف نبوت کرو، اے انسان کے بیٹے۔\n5۔ اور خداوند کی روح میرے اوپر گری اور مجھ سے کہا، بولو؛ خداوند فرماتا ہے؛ تم نے یہی کہا، اے اسرائیل کے گھرانے کو، کیونکہ میں جانتا ہوں کہ تمہارے ذہن میں جو کچھ آتا ہے، {ہر ایک}۔\n6۔ تم نے اس شہر میں اپنے مارے گئے افراد کو بڑھا دیا ہے، اور اس کی گلیوں کو مارے گئے لوگوں سے بھر دیا ہے۔\n7۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ تمہارے قتل شدہ جنہیں تم نے اس کے بیچ میں رکھا، وہ جسم ہیں، اور یہ شہر دیگ ہے: لیکن میں تمہیں اس کے بیچ سے نکالوں گا۔\n8۔ تم تلوار سے ڈرتے رہے ہو؛ اور میں تم پر تلوار لاؤں گا، خداوند خدا فرماتا ہے۔\n9۔ اور میں تمہیں اس کے درمیان سے نکالوں گا، اور تمہیں اجنبیوں کے ہاتھوں میں دوں گا، اور تم دونوں میں فیصلے کروں گا۔\n10۔ تم تلوار کے ہاتھوں مارو گے؛ میں تمہیں اسرائیل کی سرحد پر فیصلہ کروں گا؛ اور تم جان لو گے کہ میں خداوند ہوں۔\n11. یہ {شہر} تمہارا دیگ نہیں ہوگا، نہ ہی تم اس کے بیچ میں جسم بنو گے؛ {لیکن} میں آپ کا فیصلہ اسرائیل کی سرحد پر کروں گا:\n12۔ اور تم جان لو گے کہ میں خداوند ہوں: کیونکہ تم نے میرے قوانین میں نہیں چلے، نہ میرے فیصلے پر عمل کیا، بلکہ ان کافروں کے آداب کی پیروی کی جو تمہارے ارد گرد ہیں۔ {کیونکہ تم...: یا، جو نہیں چلے}\n13۔ اور جب میں نے پیش گوئی کی تو ایسا ہوا کہ بنایاہ کا بیٹا پیلاطیا فوت ہو گیا۔ پھر میں اپنے چہرے کے بل گر گیا، زور سے رویا اور کہا، اے خداوند! کیا تم اسرائیل کے باقیات کا مکمل خاتمہ کرو گے؟\n14۔ پھر خداوند کا کلام میرے پاس آیا، اور کہا،\n15۔ اے انسان کے بیٹے، تمہارے بھائیو، {حتی} تمہارے بھائیو، اپنے خاندان کے لوگ، اور پورے اسرائیل کے گھر، وہی ہیں جنہیں یروشلم کے باشندوں نے کہا ہے، خداوند سے دور ہو جاؤ: یہ زمین ہمیں دی گئی ہے۔\n16۔ لہٰذا فرماو، خداوند خدا یہ فرماتا ہے؛ اگرچہ میں نے انہیں کافروں کے درمیان دور پھینک دیا ہے، اور اگرچہ میں نے انہیں ملکوں میں بکھیر دیا ہے، پھر بھی میں ان کے لیے ان ممالک میں ایک چھوٹا سا پناہ گاہ بن جاؤں گا جہاں وہ آئیں گے۔\n17۔ لہٰذا فرماو، خداوند خدا یہ فرماتا ہے؛ میں تمہیں لوگوں میں سے جمع کروں گا، اور ان ملکوں سے نکالوں گا جہاں تم بکھرے ہوئے ہو، اور تمہیں زمین اسرائیل دوں گا۔\n18۔ اور وہ وہاں آئیں گے، اور اس کی تمام نفرت انگیز چیزیں اور اس کی تمام گناہوں کو وہاں سے لے جائیں گے۔\n19۔ اور میں انہیں ایک دل دوں گا، اور تمہارے اندر ایک نئی روح ڈالوں گا؛ اور میں ان کے جسم سے پتھر کا دل نکال دوں گا، اور انہیں گوشت کا دل دوں گا:\n20۔ تاکہ وہ میرے قوانین میں چلیں، میرے احکامات کی پاسداری کریں، اور انہیں پورا کریں: اور وہ میرے لوگ ہوں گے، اور میں ان کا خدا بنوں گا۔\n21. لیکن {جہاں تک ان کا ہے} جن کا دل ان کی نفرت انگیز چیزوں اور گناہوں کے دل کے پیچھے چلتا ہے، میں ان کے اپنے سروں پر ان کا بدلہ دوں گا، خداوند خدا فرماتا ہے۔\n22۔ پھر کروبی نے اپنے پر اٹھا دیے، اور ان کے ساتھ والے پہیے؛ اور اسرائیل کے خدا کی شان ان پر اوپر تھی۔\n23۔ اور خداوند کی شان شہر کے وسط سے اٹھ کر اس پہاڑ پر کھڑی ہوئی جو شہر کے مشرقی کنارے پر ہے۔\n24۔ بعد میں روح نے مجھے اٹھایا، اور خدا کی روح کے ذریعے مجھے ایک خواب میں کلدیہ میں لے آیا، قید کے ان کے پاس۔ تو جو وژن میں نے دیکھا تھا وہ مجھ سے غائب ہو گیا۔\n25۔ پھر میں نے ان سے قید کے بارے میں وہ سب باتیں بتائیں جو خداوند نے مجھے دکھائی تھیں۔","1۔ خداوند کا کلام بھی میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، تو ایک باغی گھرانے کے بیچ میں رہتا ہے، جس کی آنکھیں دیکھنے کے لیے ہیں، لیکن دیکھنے کے لیے نہیں؛ ان کے کان سننے کے لیے ہیں، سننے کے لیے نہیں: کیونکہ وہ ایک باغی گھرانے ہیں۔\n3۔ لہٰذا، اے انسان کے بیٹے، اپنا سامان ہٹانے کے لیے تیار کر، اور دن میں ان کی نظر میں لے جا؛ اور تم اپنی جگہ سے ہٹ کر ان کی نظر میں کسی اور جگہ چلے جاؤ گے: شاید وہ سمجھیں، چاہے وہ باغی گھرانہ کیوں نہ ہو۔ {سامان: یا، آلات}\n4۔ پھر دن میں اپنی چیزیں ان کی نظر میں نکالو، تاکہ انہیں ہٹایا جا سکے، اور تم ان کی نظر میں بھی نکل جاؤ گے، جیسے وہ قید میں جاتے ہیں۔ {جب وہ...: عبرانی۔ قید کے بعد کے واقعات کے طور پر}\n5۔ ان کی نظر میں دیوار کھودو، اور وہاں سے نکل جاؤ۔ {کھودو...: عببرانی۔ کھودو تمہارے لیے}\n6۔ ان کی نظر میں تم اسے اپنے کندھوں پر اٹھا کر رات کے وقت اٹھاؤ گے: اپنا چہرہ ڈھانپو گے، تاکہ زمین نہ دیکھو، کیونکہ میں نے تمہیں اسرائیل کے گھر کے لیے ایک نشانی کے طور پر مقرر کیا ہے۔\n7۔ اور میں نے حکم کے مطابق کیا: دن میں اپنی چیزیں قید کے لیے نکالتا تھا، اور حتیٰ کہ میں نے اپنے ہاتھ سے دیوار کو کھودا؛ میں نے شام کے وقت اسے جنم دیا، اور میں نے اسے اپنے کندھے پر ان کی نظر میں دکھایا۔ {کھودنا: عببرانی۔ میرے لیے کھودیں}\n8۔ اور صبح خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n9۔ اے انسان کے بیٹے، کیا اسرائیل کے گھر، باغی گھر، نے تم سے نہیں کہا، تو کیا کر رہے ہو؟\n10۔ ان سے کہو، خداوند خدا یہ فرماتا ہے؛ یہ بوجھ یروشلم کے شہزادے اور ان میں موجود تمام اسرائیلی گھرانے سے متعلق ہے۔\n11۔ کہو، میں تمہارا نشان ہوں: جیسے میں نے کیا، ویسا ہی ان کے ساتھ بھی ہوگا: وہ لے جائیں گے اور قید میں چلے جائیں گے۔ {وہ...: عبرانی۔ قید میں جانے کو نکال کر}\n12۔ اور ان میں سے جو شہزادہ ہے وہ شام کے وقت اپنے کندھے پر اٹھائے گا، اور نکلے گا: وہ دیوار کھودیں گے تاکہ اس سے نکل سکیں: وہ اپنا چہرہ ڈھانپے گا، تاکہ وہ زمین کو اپنی آنکھوں سے نہ دیکھے۔\n13۔ میں اپنا جال بھی اس پر پھیلاؤں گا، اور وہ میرے جال میں پکڑا جائے گا: اور میں اسے بابل لے جاؤں گا {کلدانیوں کی زمین}؛ پھر بھی وہ اسے نہیں دیکھے گا، چاہے وہ وہاں مر جائے۔\n14۔ اور میں ہر ہوا کی طرف اس کے ارد گرد جو کچھ ہے اسے اور اس کے تمام گروہوں کی مدد کے لیے بکھیر دوں گا؛ اور میں ان کے پیچھے تلوار نکالوں گا۔\n15۔ اور وہ جان جائیں گے کہ میں خداوند ہوں، جب میں انہیں قوموں میں بکھیر دوں گا اور ملکوں میں بکھیر دوں گا۔\n16۔ لیکن میں ان میں سے چند آدمیوں کو تلوار، قحط اور وبا سے چھوڑ دوں گا؛ تاکہ وہ اپنی تمام گنایاں ان کافروں کے سامنے ظاہر کر سکیں جہاں وہ آتے ہیں؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔ {کچھ...: عبرانی۔ تعداد میں مرد}\n17۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا،\n18۔ اے انسان کے بیٹے، اپنی روٹی لرزتے ہوئے کھاؤ، اور اپنا پانی کانپتے اور احتیاط سے پیو؛\n19۔ اور زمین کے لوگوں سے فرماو، یہی فرماتا ہے خداوند خدا یروشلم کے باشندوں کا، {اور} زمین اسرائیل کے؛ وہ اپنی روٹی احتیاط سے کھائیں گے، اور حیرت سے اپنا پانی پیئیں گے، تاکہ اس کی زمین اس میں موجود تمام لوگوں کی تشدد کی وجہ سے ویران ہو جائے۔ {یہ سب...: عبرانی۔ اس کی مکمل شدت}\n20۔ اور جو شہر آباد ہیں وہ ویران ہو جائیں گے، اور زمین ویران ہو جائے گی؛ اور تم جان لو گے کہ میں خداوند ہوں۔\n21۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا،\n22۔ اے انسان کے بیٹے، وہ کہاوت کیا ہے جو تمہارے پاس اسرائیل کی سرزمین میں ہے، کہتی ہے، دن لمبے ہو جاتے ہیں اور ہر خواب ناکام ہو جاتا ہے؟\n23۔ لہٰذا انہیں بتاؤ، خداوند خدا یہ فرماتا ہے؛ میں اس کہاوت کو روک دوں گا، اور وہ اسے اسرائیل میں کہاوت کے طور پر استعمال نہیں کریں گے؛ بلکہ ان سے کہو، دن قریب ہیں، اور ہر بصیرت کا اثر۔\n24۔ کیونکہ اب اسرائیل کے گھر میں کوئی فضول بصیرت یا خوشامد کی پیش گوئی نہیں ہوگی۔\n25۔ کیونکہ میں خداوند ہوں: میں بولوں گا، اور جو کلام میں کہوں گا وہ پورا ہو جائے گا؛ یہ مزید طویل نہیں ہوگا: کیونکہ تیرے زمانے میں، اے باغی گھر، میں کلام کہوں گا اور اسے پورا کروں گا، خداوند خدا فرماتا ہے۔\n26. پھر خداوند کا کلام میرے پاس آیا، جس میں کہا،\n27۔ اے انسان کے بیٹے، دیکھو، {وہ اسرائیلی گھرانے کے لوگ کہتے ہیں: وہ خواب جو وہ دیکھتا ہے} کئی دنوں تک {آنے والے} کے لیے ہے، اور وہ دور کے زمانوں کی پیش گوئی کرتا ہے۔\n28۔ لہٰذا ان سے فرماو، خداوند خدا یہ فرماتا ہے؛ میرے الفاظ میں سے کوئی مزید طول نہیں پائے گا، لیکن جو کلام میں نے کہا ہے وہ کیا جائے گا، خداوند خدا فرماتا ہے۔","1۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، اسرائیل کے انبیاء کے خلاف نبوت کرو جو نبوت کرتے ہیں، اور جو اپنے دل سے نبوت کرتے ہیں ان سے کہ، خداوند کا کلام سنو؛ {وہ پیش گوئی...: عبرانی جو اپنے دلوں سے نکلے ہوئے نبی ہیں}\n3۔ خداوند خدا یہ فرماتا ہے؛ ان بے وقوف نبیوں پر افسوس جو اپنی روح کی پیروی کرتے ہیں اور کچھ نہیں دیکھتے! {فالو: عببرانی۔ اس کے بعد چلیں} {اور...: یا، اور وہ چیزیں جو انہوں نے نہیں دیکھی}\n4۔ اے اسرائیل، تیرے نبی صحرا میں لومڑیوں کی مانند ہیں۔\n5۔ تم نے نہ تو خلا میں اوپر گئے، نہ ہی اسرائیل کے گھر کے لیے باڑ بنائی تاکہ وہ خداوند کے دن جنگ میں کھڑا ہو سکے۔ {گیپس: یا، بریچز} {بنا...: عبرانی باڑ کو ہیج کیا}\n6۔ انہوں نے غرور اور جھوٹ پیش گوئی دیکھی ہے، کہتے ہوئے، خداوند فرماتا ہے: اور خداوند نے انہیں نہیں بھیجا، اور انہوں نے [دوسروں} کو امید دی ہے کہ وہ کلام کی تصدیق کریں گے۔\n7۔ کیا تم نے کوئی فضول خواب نہیں دیکھا، اور کیا تم نے جھوٹ بول کر پیش گوئی نہیں کی، جب تم کہتے ہو، خداوند کہتا ہے؛ اگرچہ میں نے بات نہیں کی؟\n8۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ کیونکہ تم نے بکواس کی اور جھوٹ دیکھا، تو دیکھو، میں تمہارے خلاف ہوں، خداوند خدا فرماتا ہے۔\n9۔ اور میرا ہاتھ ان پیغمبروں پر ہوگا جو باطل اور الہی جھوٹ دیکھتے ہیں: وہ میرے لوگوں کی جماعت میں نہیں ہوں گے، نہ ہی وہ اسرائیل کے گھر کی تحریر میں لکھے جائیں گے، نہ ہی وہ اسرائیل کی سرزمین میں داخل ہوں گے؛ اور تم جان لو گے کہ میں خداوند خدا ہوں۔ {اجتماع: یا، خفیہ، یا، مشورہ}\n10۔ کیونکہ، چاہے انہوں نے میرے لوگوں کو بہکایا ہو، یہ کہہ کر کہ امن ہے؛ اور {وہاں کوئی سکون نہیں تھا}؛ اور ایک نے دیوار بنائی، اور دیکھو، دوسروں نے اس پر بے تاثر {مورٹر} لگایا: {ایک دیوار: یا، ایک ہلکی سی دیوار}\n11۔ ان لوگوں سے کہو جو بے قابو {مورٹر} سے لگا رہے ہیں، کہ وہ برس جائے گا: بارش بہہ جائے گی؛ اور تم، اے بڑے اولے کے پتھر، گرو گے؛ اور ایک طوفانی ہوا اسے چیر دے گی۔\n12۔ دیکھو، جب دیوار گر جائے گی، کیا تم سے یہ نہیں کہا جائے گا، وہ نقش کہاں ہے جس سے تم نے اسے رنگا ہے؟\n13۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ میں اپنے غصے میں طوفانی ہوا سے بھی اسے پھاڑ دوں گا؛ اور میرے غصے میں بارش برسائے گی، اور {میری} غصے میں اولے برسیں گے تاکہ {اسے} کو نگل جاؤں۔\n14. تو میں وہ دیوار توڑ دوں گا جسے تم نے بے داغ {مورٹر} سے لگایا ہے، اور اسے زمین پر گرا دوں گا، تاکہ اس کی بنیاد دریافت ہو جائے، اور وہ گر جائے گی، اور تم اس کے بیچ میں نگل جاؤ گے: اور تم جان لو گے کہ میں خداوند ہوں۔\n15۔ یوں میں اپنی غضب دیوار پر اور ان پر نازل کروں گا جنہوں نے اسے بے داغ {مورتر} سے لگایا ہے، اور تم سے کہوں گا، دیوار {اب نہیں}، نہ ہی وہ جنہوں نے اسے لگایا؛\n16. {یعنی}، اسرائیل کے نبی جو یروشلم کے بارے میں نبوت کرتے ہیں، اور جو اس کے لیے امن کے خواب دیکھتے ہیں، اور {امن نہیں}، خداوند خدا فرماتا ہے۔\n17. اسی طرح، اے انسان کے بیٹے، اپنے لوگوں کی بیٹیوں کے خلاف اپنا چہرہ رکھ لو، جو اپنے دل سے پیش گوئی کرتی ہیں؛ اور ان کے خلاف پیش گوئی کرو،\n18۔ اور کہو، خداوند خدا یہ فرماتا ہے؛ ان عورتوں پر افسوس جو ہر بازو کے سوراخوں میں تکیے سی رہی ہیں، اور ہر قامت کے سر پر رومال بناتی ہیں تاکہ روحوں کا شکار کریں! کیا تم میرے لوگوں کی روحوں کا شکار کرو گے، اور زندہ روحوں کو بچاؤ گے جو تمہارے پاس آتی ہیں؟ {بازو کے سوراخ: یا، کہنی}\n19۔ اور کیا تم مجھے میرے لوگوں میں جو اور روٹی کے ٹکڑوں کے لیے آلودہ کرو گے، ان روحوں کو مارنے کے لیے جو مرنا نہیں چاہتیں، اور ان زندہ روحوں کو بچانے کے لیے جو زندہ نہیں رہنا چاہتیں، تمہاری جھوٹ بول کر جو میرے لوگوں سے جھوٹ بولتے ہیں جو تمہارے جھوٹ سنتے ہیں؟\n20۔ اسی لیے خداوند خدا یہ فرماتا ہے؛ دیکھو، میں تمہارے تکیوں کے ساتھ کھڑا ہوں، جن سے تم روحوں کا شکار کرتے ہو تاکہ وہ اڑ سکیں، اور میں انہیں تمہاری بانہوں سے چھین لوں گا، اور روحوں کو چھوڑ دوں گا، حتیٰ کہ ان روحوں کو بھی چھوڑ دوں گا جنہیں تم شکار کرتے ہو تاکہ انہیں اڑانے کے لیے تلاش کر رہے ہو۔ {بنانے کے لیے...: یا، باغات میں}\n21۔ میں تمہارے رومال بھی پھاڑ دوں گا، اور اپنے لوگوں کو تمہارے ہاتھ سے آزاد کروں گا، اور وہ تمہارے ہاتھ میں شکار کے لیے نہیں رہیں گے؛ اور تم جان لو گے کہ میں خداوند ہوں۔\n22۔ کیونکہ تم نے جھوٹ سے راستبازوں کے دل کو غمگین کر دیا، جنہیں میں نے غمگین نہیں کیا؛ اور بدکاروں کے ہاتھوں کو مضبوط کیا، تاکہ وہ اپنی برائی سے واپس نہ جائے، زندگی کا وعدہ کر کے: {by...: یا، کہ میں اس کی جان بچاؤں: عبرانی۔ اسے تیز کر کے}\n23۔ اس لیے تم مزید بےکاری یا الہی پیش گوئی نہیں دیکھو گے، کیونکہ میں اپنی قوم کو تیرے ہاتھوں سے آزاد کروں گا: اور تم جان لو گے کہ میں خداوند ہوں۔","1۔ پھر اسرائیل کے کچھ بزرگوں میں سے کچھ میرے پاس آئے اور میرے سامنے بیٹھ گئے۔\n2۔ اور خداوند کا کلام میرے پاس آیا، جس نے کہا،\n3۔ اے انسان کے بیٹے، ان لوگوں نے اپنے بتوں کو اپنے دلوں میں لگا دیا ہے، اور اپنے گناہوں کی رکاوٹ اپنے سامنے رکھ دی ہے: کیا وہ مجھ سے پوچھیں گے؟\n4۔ لہٰذا ان سے بات کرو، اور ان سے کہو، خداوند خدا یہ فرماتا ہے؛ اسرائیل کے گھر کا ہر وہ آدمی جو اپنے بت اپنے دل میں لگاتا ہے، اور اپنی گناہوں کی رکاوٹ اپنے سامنے رکھتا ہے، اور نبی کے پاس آتا ہے؛ میں، خداوند، اس کا جواب دوں گا جو اس کے بتوں کی کثرت کے مطابق آتا ہے؛\n5۔ تاکہ میں اسرائیل کے گھر کو ان کے دل میں لے سکوں، کیونکہ وہ سب اپنے بتوں کی وجہ سے مجھ سے دور ہیں۔\n6۔ لہٰذا اسرائیل کے گھر سے کہو، خداوند خدا یہ فرماتا ہے؛ توبہ کرو، اور اپنے بتوں سے منہ موڑ لو؛ اور اپنے چہروں کو اپنی تمام مکروہ حرکتوں سے دور رکھو۔ {تم خود: یا، دوسرے}\n7۔ اسرائیل کے گھرانے کے ہر فرد کے لیے، یا وہ اجنبی جو اسرائیل میں ٹھہرا ہوا ہے، جو مجھ سے الگ ہو جاتا ہے، اپنے بت اپنے دل میں رکھتا ہے، اپنی گناہ کی رکاوٹ اپنے سامنے رکھتا ہے، اور نبی کے پاس آتا ہے تاکہ اس سے میرے بارے میں پوچھے؛ میں، خداوند، خود اس کا جواب دوں گا:\n8۔ اور میں اس آدمی کے خلاف اپنا چہرہ رکھوں گا، اسے ایک علامت اور کہاوت بناؤں گا، اور اسے اپنی قوم کے درمیان سے کاٹ دوں گا؛ اور تم جان لو گے کہ میں خداوند ہوں۔\n9۔ اور اگر نبی کچھ کہہ کر دھوکہ کھا گیا، تو میں خداوند نے اس نبی کو دھوکہ دیا ہے، اور میں اس پر ہاتھ بڑھاؤں گا، اور اسے اپنی قوم اسرائیل کے درمیان سے تباہ کر دوں گا۔\n10۔ اور وہ اپنی گناہوں کی سزا برداشت کریں گے: نبی کی سزا اس کی سزا کے برابر ہوگی جو اس سے مانگتا ہے؛\n11۔ تاکہ اسرائیل کا گھر مجھ سے مزید دور نہ ہو، نہ ہی اپنی تمام گناہوں سے آلودہ ہو جائے؛ بلکہ تاکہ وہ میرے لوگ ہوں، اور میں ان کا خدا بن سکوں، خداوند خدا فرماتا ہے۔\n12۔ خداوند کا کلام دوبارہ میرے پاس آیا، اور کہا،\n13۔ اے انسان کے بیٹے، جب زمین میرے خلاف گناہ کرے گی، تو میں اس پر ہاتھ بڑھاؤں گا، اس کی روٹی کی چھڑی توڑ دوں گا، اس پر قحط ڈالوں گا، اور انسان و جانور اس سے کاٹ دوں گا:\n14۔ اگرچہ یہ تینوں لوگ، نوح، دانیال اور ایوب، اس میں شامل تھے، انہیں اپنی راستبازی سے اپنی جانوں کو نجات دینی چاہیے، خداوند خدا فرماتا ہے۔\n15۔ اگر میں بدتمیز جانوروں کو زمین سے گزرنے دوں، اور وہ اسے برباد کر دیں، تاکہ کوئی انسان ان جانوروں کی وجہ سے نہ گزر سکے: {لوٹنا: یا، سوگوار}\n16. {اگرچہ} یہ تینوں مرد {تھے} اس میں، {جت} میں زندہ ہوں، خداوند خدا فرماتا ہے، وہ نہ بیٹے دیں گے نہ بیٹیاں؛ صرف انہیں بچایا جائے گا، لیکن زمین ویران ہو جائے گی۔ {اس میں: عبرانی۔ اسی دوران}\n17۔ یا {اگر} میں اس زمین پر تلوار لاؤں اور کہوں، تلوار، زمین سے گزر جا؛ تاکہ میں انسان اور جانور کو اس سے کاٹ دوں:\n18۔ اگرچہ یہ تینوں مرد {جت} میں زندہ ہوں، خداوند خدا فرماتا ہے، وہ نہ بیٹے دیں گے نہ بیٹیاں، بلکہ صرف خود آزاد ہوں گے۔\n19۔ یا {اگر} میں اس زمین میں کوئی وبا بھیجوں، اور اپنا غصہ اس پر خون میں ڈال دوں، تاکہ انسان اور جانور کو کاٹ سکوں:\n20. اگرچہ نوح، دانیال اور ایوب اس میں تھے، {جیسا کہ میں زندہ ہوں}، خداوند خدا فرماتا ہے، وہ نہ بیٹا دیں گے نہ بیٹی کو؛ وہ اپنی راستبازی سے اپنی جان کو نجات دیں گے۔\n21۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ اور جب میں یروشلم، تلوار، قحط، اور اس خطرناک جانور اور وبا پر اپنے چار سخت فیصلے بھیجوں گا، تو انسان اور جانور کو اس سے کاٹ دوں؟ {کیسے...: یا، جب}\n22۔ پھر بھی، وہاں ایک باقیات رہ جائیں گی جو پیدا ہوں گی، {بیٹے} اور بیٹیاں دونوں: دیکھیں، وہ آپ کے پاس آئیں گے، اور آپ ان کے راستے اور اعمال دیکھیں گے: اور آپ کو یروشلم پر لائی گئی برائی پر تسلی ملے گی، {حتیٰ کہ} کہ میں نے اس پر جو کچھ بھی لایا ہے۔\n23۔ اور وہ تمہیں تسلی دیں گے، جب تم ان کے طریقے اور اعمال دیکھو گے: اور تم جان لو گے کہ میں نے جو کچھ بھی اس میں کیا بغیر وجہ کے نہیں کیا، خداوند خدا فرماتا ہے۔","1۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، بیل کا درخت کسی بھی درخت سے زیادہ کیا ہے، {یا} جنگل کے درختوں میں موجود شاخ سے زیادہ؟\n3۔ کیا اس سے لکڑی کسی کام کے لیے لی جائے گی؟ یا {مرد} اس میں سے ایک پن لے کر کسی بھی برتن کو اس پر لٹکائیں گے؟\n4۔ دیکھو، اسے ایندھن کے لیے آگ میں پھینک دیا جاتا ہے؛ آگ اس کے دونوں سروں کو نگل جاتی ہے، اور اس کے درمیان جل جاتا ہے۔ کیا یہ {کوئی} کام کے لیے موزوں ہے؟ {کیا یہ...: عبرانی۔ کیا یہ ترقی کرے گا؟}\n5۔ دیکھو، جب یہ مکمل تھا، تو اسے کوئی کام نہیں ملا: اور کتنا کم کام کے لیے پورا ہوگا، جب آگ نے اسے نگل لیا اور وہ جل جائے؟ {ملاقات: عبرانی۔ میڈ فٹ}\n6۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ جیسے جنگل کے درختوں میں بیل کا درخت، جسے میں نے آگ کو ایندھن کے طور پر دیا ہے، ویسے ہی میں یروشلم کے باشندوں کو دوں گا۔\n7۔ اور میں ان کے خلاف اپنا چہرہ رکھوں گا؛ وہ {ایک} آگ سے باہر نکلیں گے، اور {دوسری} آگ انہیں نگل جائے گی؛ اور تم جان جاؤ گے کہ میں خداوند ہوں، جب میں ان کے خلاف اپنا چہرہ رکھوں گا۔\n8۔ اور میں زمین کو ویران بنا دوں گا، کیونکہ انہوں نے گناہ کیا ہے، خداوند خدا فرماتا ہے۔ {کمیٹڈ...: ہیب۔ غیر قانونی داخلہ}","1۔ پھر خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ انسان کے بیٹے، یروشلم کو اس کے گناہوں کا علم دلاؤ،\n3۔ اور کہو، خداوند خدا یروشلم کو یوں فرماتا ہے؛ تمہاری پیدائش اور پیدائش کنعان کی سرزمین سے ہے؛ تمہارا باپ اموری تھا، اور تمہاری ماں ہٹی۔ {پیدائش: عبرانی۔ کاٹنا، یا، رہائش کاٹنا}\n4۔ اور جہاں تک تمہاری پیدائش کا تعلق ہے، جس دن تم پیدا ہوئے تھے تمہاری ناف نہ کاٹی گئی، نہ تمہیں پانی میں دھویا گیا تاکہ تم نرم ہو جاؤ؛ تمہیں بالکل نمک نہیں لگایا گیا، نہ ہی لپیٹا گیا۔ {نرم کرنے کے لیے...: یا، جب میں نے تمہیں دیکھا}\n5۔ کسی نے تم پر ترس نہیں کھایا، کہ وہ یہ سب تمہارے ساتھ کرے، تم پر رحم کرے؛ لیکن تمہیں کھلے میدان میں نکال دیا گیا، تمہاری ذات کی نفرت کے لیے، اس دن جب تم پیدا ہوئے تھے۔\n6۔ اور جب میں تمہارے پاس سے گزرا، اور تمہیں اپنے خون میں آلودہ دیکھا، میں نے تم سے کہا {جب تم اپنے خون میں ڈوبے ہو، زندہ رہو؛ ہاں، میں نے تم سے کہا {جب تم اپنے خون میں ڈوبے ہو}، جیو۔ {آلودہ: یا، پاؤں تلے روندنا}\n7۔ میں نے تمہیں کھیت کی کلی کی طرح بڑھایا، اور تم نے بڑا اور بڑا کیا، اور تم خوبصورت زیورات میں آ گئے ہو: تمہارے سینے بنے ہوئے ہیں، تمہارے بال بڑھے ہوئے ہیں، جبکہ تم ننگے اور ننگے ہو۔ {وجہ سے...: عبرانی۔ تمہیں ایک ملین بنایا} {بہترین...: عبرانی۔ زیورات کا زیور}\n8۔ اب جب میں تمہارے پاس سے گزرا اور تمہیں دیکھا، دیکھو، تمہارا وقت محبت کا وقت تھا؛ اور میں نے اپنی چادر تمہارے اوپر ڈال دی، اور تمہاری ننگی کو ڈھانپ لیا: ہاں، میں تم سے قسم کھاتا ہوں، اور تمہارے ساتھ عہد کیا ہے، خداوند خدا فرماتا ہے، اور تو میرا بن گیا۔\n9۔ پھر میں نے تمہیں پانی سے دھویا؛ ہاں، میں نے تیرا خون تم سے دھو دیا، اور تمہیں تیل سے مسح کیا۔ {خون: عبرانی۔ bloods}\n10۔ میں نے تمہیں بھی چوٹی کے کپڑے پہنائے، تمہیں بیجر کی کھال سے جوتے پہنائے، اور تمہیں عمدہ کپڑے سے باندھا، اور تمہیں ریشم سے ڈھانپ دیا۔\n11۔ میں نے تمہیں زیورات سے بھی سجایا، اور تمہارے ہاتھوں پر کنگن اور تمہارے گلے پر زنجیر باندھی۔\n12۔ اور میں تمہارے ماتھے پر ایک جواہر اور تمہارے کانوں میں بالیاں اور تمہارے سر پر خوبصورت تاج رکھتا ہوں۔ {پیشانی: عبرانی۔ ناک}\n13۔ یوں تم سونے اور چاندی سے مزین ہوئے؛ اور تمہارا لباس عمدہ کتان، ریشم اور کڑھائی کا تھا؛ تم نے عمدہ آٹا، شہد اور تیل کھایا، اور تم بہت خوبصورت تھے، اور تم ایک بادشاہت میں کامیاب ہوئے۔\n14۔ اور تیری شہرت کافروں میں تمہاری خوبصورتی کی وجہ سے پھیل گئی: کیونکہ وہ میری خوبصورتی سے مکمل تھی، جو میں نے تم پر ڈالی تھی، خداوند خدا فرماتا ہے۔\n15۔ لیکن تم نے اپنی خوبصورتی پر بھروسہ کیا، اور اپنی شہرت کی وجہ سے بدکردار بنایا، اور اپنی ہر گزرنے والے پر بہا دی؛ یہ اس کا تھا۔\n16۔ اور تم نے اپنے کپڑے اتارے، اور اپنی اونچی جگہوں کو مختلف رنگوں سے سجایا، اور وہاں بدکاری کا کردار ادا کیا: {ایسی چیزیں} نہیں آئیں گی، اور نہ ہی ہوں گی۔\n17۔ تم نے میرے سونے اور چاندی کے خوبصورت جواہرات بھی لے لیے، جو میں نے تمہیں دیے تھے، اور اپنے لیے انسانوں کی تصویریں دیکھی ہیں، اور ان کے ساتھ بدکاری کی، {انسانوں کی: عبرانی۔ ایک مرد کا}\n18۔ اور اپنے کپڑے پہنے، اور انہیں ڈھانپ دیا، اور ان کے سامنے میرا تیل اور لوبان رکھ دیا۔\n19۔ میرا گوشت بھی جو میں نے تمہیں دیا، عمدہ آٹا، تیل، اور شہد، {جس سے} میں نے تمہیں کھلایا، تو نے اسے ان کے سامنے میٹھا ذائقہ کے طور پر رکھا ہے: اور {یہ} تھا، خداوند خدا فرماتا ہے۔ {ایک میٹھا...: عبرانی۔ آرام کا ذائقہ}\n20۔ اس کے علاوہ تم نے اپنے بیٹے اور بیٹیاں بھی لے لی ہیں، جنہیں تم نے میرے لیے جنم دیا، اور انہیں ان کے لیے قربان کیا ہے تاکہ وہ کھا جائیں۔ {کیا یہ} تمہاری بدکاری کا ایک چھوٹا معاملہ ہے، {ہونا...: عبرانی۔ کھانے کے لیے}\n21۔ کہ تم نے میرے بچوں کو قتل کیا اور انہیں آگ سے گزرنے کے لیے آزاد کر دیا؟\n22۔ اور اپنی تمام گناہوں اور اپنی بدکاری میں تم نے اپنی جوانی کے دنوں کو یاد نہیں کیا، جب تم ننگے اور ننگے تھے، {اور} اپنے خون میں آلودہ تھے۔\n23۔ اور یہ تمہاری تمام برائیوں کے بعد ہوا، (ہائے تم پر افسوس! خداوند خدا فرماتا ہے؛)\n24۔ {یہ} کہ تم نے اپنے لیے ایک معزز مقام بھی بنایا ہے، اور ہر گلی میں اپنی جگہ بلند کر دی ہے۔ {معزز...: یا، کوٹھے کا گھر}\n25۔ تم نے ہر راستے پر اپنی اونچی جگہ بنائی ہے، اپنی خوبصورتی کو قابل نفرت بنا دیا ہے، اور ہر گزرنے والے کے لیے اپنے قدم کھولے ہیں، اور اپنی بدکاری کو بڑھا دیا ہے۔\n26۔ تم نے اپنے پڑوسیوں کے ساتھ بھی کیا ہے، جو بڑے جسمانی ہیں؛ اور اپنی بدکاری میں اضافہ کیا ہے، تاکہ مجھے غصہ دلایا جا سکے۔\n27۔ دیکھو، اس لیے میں نے اپنا ہاتھ تیرے اوپر بڑھایا ہے، اور تمہاری عام خوراک کم کر دی ہے، اور تمہیں ان لوگوں کی مرضی کے حوالے کر دیا ہے جو تم سے نفرت کرتی ہیں، فلسطینیوں کی بیٹیاں، جو تمہاری بے حیائی پر شرمندہ ہیں۔ {بیٹیاں: یا، شہر}\n28۔ تم نے آشوریوں کے ساتھ بھی طوائف کا کردار ادا کیا، کیونکہ تم بے تاب تھے؛ ہاں، تم نے ان کے ساتھ بدکردار کھیلا ہے، اور پھر بھی مطمئن نہیں ہو سکے۔\n29۔ تم نے کنعان کی سرزمین میں اپنی کو کلدیہ تک بڑھا دیا ہے؛ اور پھر بھی تم اس سے مطمئن نہیں تھے۔\n30۔ خداوند خدا فرماتا ہے کہ تمہارا دل کتنا کمزور ہے، جب تم یہ سب کچھ کر رہے ہو، جو ایک ظالم عورت کا کام ہے؛\n31۔ اس میں کہ تم ہر راستے میں اپنی نمایاں جگہ بناتے ہو، اور ہر گلی میں اپنی بلند جگہ بناتے ہو؛ اور تم نے کرائے کی حقیر میں طوائف کی طرح نہیں رہی؛ {جس میں تم بناتے ہو...: یا، تمہاری بیٹیوں میں تمہاری ہے، وغیرہ}\n32۔ {لیکن جیسے بیوی جو کرتی ہے، {جو} اپنے شوہر کی جگہ اجنبیوں کو قبول کرتی ہے!\n33۔ وہ تمام طوائفوں کو تحفے دیتے ہیں، لیکن تم اپنے تمام عاشقوں کو تحفے دیتے ہو، اور انہیں ملازمت دیتے ہو، تاکہ وہ تمہاری بدکاری کے لیے ہر طرف سے تمہارے پاس آ سکیں۔ {ہائرسٹ: عبوری۔ بریبیسٹ}\n34۔ اور اس کے برعکس آپ میں {دوسری عورتیں} ہیں جو آپ کی بدکاری میں ہیں، جبکہ کوئی آپ کے ساتھ بدکاری کے لیے نہیں آتا: اور اس میں کہ آپ انعام دیتے ہیں اور آپ کو کوئی انعام نہیں ملتا، اس لیے آپ مخالف ہیں۔\n35۔ اسی لیے، اے بدکار، خداوند کا کلام سنو:\n36۔ خداوند خدا یہ فرماتا ہے؛ کیونکہ تمہاری گندگی باہر نکلی گئی، اور تمہاری برہنگی تمہاری بدکاری کے ذریعے تمہارے عاشقوں کے ساتھ، اور تمہارے تمام گناہوں کے بتوں کے ساتھ، اور اپنے بچوں کے خون سے ظاہر ہوئی، جو تم نے انہیں دیے؛\n37۔ دیکھو، اس لیے میں تمہارے تمام عاشقوں کو جمع کروں گا، جن سے تم نے خوش کیا، اور ان سب سے جنہیں تم نے محبت کی، ان سب کے ساتھ جنہیں تم نے ناپسند کیا؛ میں انہیں تمہارے خلاف جمع کروں گا، اور تمہاری برہنگی ان کے سامنے دکھاؤں گا، تاکہ وہ تمہاری ساری برہنگی دیکھ سکیں۔\n38۔ اور میں تمہارا فیصلہ کروں گا، جیسے وہ عورتیں جو شادی توڑتی ہیں اور خون بہاتی ہیں؛ اور میں تمہیں غصے اور حسد میں خون دوں گا۔ {as: عبرانی فیصلوں کے ساتھ}\n39۔ اور میں تمہیں ان کے ہاتھ میں دے دوں گا، اور وہ تمہاری بلند جگہ گرا دیں گے، اور تمہاری اونچی جگہیں توڑ دیں گے، وہ بھی تمہارے کپڑے اتار دیں گے، تمہارے خوبصورت زیورات لے جائیں گے، اور تمہیں ننگے اور ننگے چھوڑ دیں گے۔ {تیری خوبصورت...: عبرانی۔ تمہارے آرائش کے آلات}\n40۔ وہ تمہارے خلاف ایک فوج بھی لائیں گے، تمہیں پتھروں سے ماریں گے، اور اپنی تلواروں سے تمہیں گھونپیں گے۔\n41۔ اور وہ تمہارے گھروں کو آگ سے جلا دیں گے، اور بہت سی عورتوں کے سامنے تم پر فیصلے کریں گے: اور میں تمہیں بدکاری سے باز رکھوں گا، اور تم بھی مزید کوئی معاوضہ نہیں دو گے۔\n42. اسی طرح میں اپنے غصے کو تم پر ختم کر دوں گا، اور میری حسد تم سے دور ہو جائے گی، اور میں خاموش رہوں گا، اور مزید غصہ نہیں ہوں گا۔\n43۔ کیونکہ تم نے اپنی جوانی کے دن یاد نہیں کیے، بلکہ ان سب باتوں میں مجھے پریشان کیا ہے؛ دیکھو، لہٰذا میں بھی تمہارے سر پر تمہاری راہ کا بدلہ دوں گا، خداوند خدا فرماتا ہے: اور تم یہ بے حیائی اپنی تمام گناہوں سے بالاتر نہ کرو گے۔\n44۔ دیکھو، ہر وہ شخص جو امثال استعمال کرے گا، وہ تمہارے خلاف {یہ} کہاوت استعمال کرے گا، جیسے {ہے} ماں ہے، {ویسے} اس کی بیٹی بھی ہے۔\n45۔ تم اپنی ماں کی بیٹی ہو، جو اپنے شوہر اور بچوں سے نفرت کرتی ہے؛ اور تم اپنی بہنوں کی بہن ہو، جو اپنے شوہروں اور بچوں سے نفرت کرتی تھیں: تمہاری ماں ہیتی تھی، اور تمہارے والد اموریت۔\n46۔ اور تمہاری بڑی بہن {ہے} سامریہ، وہ اور اس کی بیٹیاں جو تیرے بائیں ہاتھ میں رہتی ہیں؛ اور تمہاری چھوٹی بہن، جو تمہارے دائیں ہاتھ میں رہتی ہے، {ہے} سدوم اور اس کی بیٹیاں۔ {تمہارا چھوٹا: عبرانی۔ تم سے کم تر\n47۔ پھر بھی تم نے ان کے راستے نہیں چلے، نہ ہی ان کے گناہوں کے بعد کیا ہے، بلکہ اگر یہ بہت چھوٹی سی چیز ہو، تو تم اپنی تمام راہوں میں ان سے زیادہ خراب ہوئے۔ {جیسے...: یا، یہ چھوٹی سی بات سمجھی جاتی ہے}\n48۔ {جیسا کہ میں زندہ ہوں}، خداوند خدا فرماتا ہے، سدوم نے نہ تو اس نے کیا ہے اور نہ اس کی بیٹیوں نے، جیسا کہ تم نے کیا ہے، تم اور تمہاری بیٹیاں۔\n49۔ دیکھو، یہ تمہاری بہن سدوم کی بدکاری تھی، غرور، روٹی کی بھرپوری، اور سستی کی فراوانی اس میں اور اس کی بیٹیوں میں تھی، نہ ہی اس نے غریبوں اور محتاجوں کے ہاتھ کو مضبوط کیا۔\n50۔ اور وہ مغرور تھے، اور میرے سامنے گناہ کیے، اس لیے میں نے انہیں ویسا ہی لے لیا جیسا کہ میں نے اچھائی دیکھی۔\n51. نہ ہی سامریا نے تمہارے گناہوں کا آدھا حصہ کیا؛ لیکن تم نے اپنی گناہوں کو ان سے زیادہ بڑھا دیا ہے، اور اپنی بہنوں کو اپنی تمام گناہوں میں جائز ثابت کیا ہے جو تم نے کیے ہیں۔\n52۔ تم بھی، جس نے اپنی بہنوں کا فیصلہ کیا، اپنی شرمندگی اپنے گناہوں کی وجہ سے اٹھاؤ جو تم نے ان سے زیادہ گھناونے کیے ہیں: وہ تم سے زیادہ نیک ہیں: ہاں، تم بھی پریشان ہو جاؤ، اور اپنی شرمندگی برداشت کرو، اس بات پر کہ تم نے اپنی بہنوں کو انصاف دیا۔\n53۔ جب میں ان کی قید کو دوبارہ لاؤں گا، سدوم اور اس کی بیٹیوں کی قید کو، اور سامریا اور اس کی بیٹیوں کی قید کو دوبارہ لاؤں گا، تو پھر میں تمہارے قیدیوں کی قید کو دوبارہ ان کے درمیان لے آؤں گا:\n54۔ تاکہ تم اپنی شرمندگی برداشت کرو، اور جو کچھ تم نے کیا اس میں الجھن میں مبتلا ہو جاؤ، کیونکہ تم ان کے لیے تسلی بخش ہو۔\n55۔ جب تمہاری بہنیں، سدوم اور اس کی بیٹیاں، اپنی سابقہ جائیداد میں واپس جائیں گی، اور سامریہ اور اس کی بیٹیاں اپنی سابقہ جائیداد میں واپس جائیں گی، تو تم اور تمہاری بیٹیاں اپنی سابقہ جائیداد میں واپس چلی جائیں گی۔\n56۔ کیونکہ تمہاری بہن سدوم کا ذکر تمہارے غرور کے دن تمہارے منہ سے نہیں آیا، {ذکر شدہ: عبرانی۔ رپورٹ یا سماعت کے لیے} {فخر: عبرانی فخر، یا، ایکسیلنسیز}\n57۔ تمہاری برائی ظاہر ہونے سے پہلے، جیسا کہ شام کی بیٹیوں اور اس کے ارد گرد موجود تمام فلسطینیوں کی بیٹیوں پر ملامت کے وقت، جو تمہیں حقیر سمجھتی ہیں۔ {شام: عبرانی۔ آرام} {حقارت: یا، خراب کرنا}\n58. تو نے اپنی فحاشی اور اپنی گناہوں کو برداشت کیا ہے، خداوند فرماتا ہے۔ {بورن: عبوری۔ برداشت کیا}\n59۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ میں تمہارے ساتھ بھی ویسا ہی سلوک کروں گا جیسا تم نے کیا، جس نے عہد توڑنے کی قسم کو حقیر سمجھا۔\n60۔ پھر بھی میں تمہارے جوانی کے دنوں میں تم سے اپنا عہد یاد رکھوں گا، اور تمہارے ساتھ ایک دائمی عہد قائم کروں گا۔\n61۔ پھر تم اپنے طریقے یاد رکھو گے، اور شرمندہ ہو جاؤ گے جب تم اپنی بڑی اور چھوٹی بہنوں کو قبول کرو گے: اور میں انہیں بیٹیوں کے طور پر تمہیں دوں گا، لیکن تمہارے عہد کے ذریعے نہیں۔\n62۔ اور میں آپ کے ساتھ اپنا عہد قائم کروں گا؛ اور تم جان لو گے کہ میں خداوند ہوں:\n63. تاکہ تم یاد رکھو، شرمندہ ہو جاؤ، اور اپنی شرمندگی کی وجہ سے اپنا منہ نہ کھولو، جب میں تمہارے کیے ہوئے تمام کاموں کے لیے تمہارے لیے مطمئن ہو جاؤ، خداوند خدا فرماتا ہے۔","1۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، ایک پہیلی حل کرو اور اسرائیل کے گھر کے لیے ایک تمثیل سناؤ؛\n3۔ اور کہو، خداوند خدا یہ فرماتا ہے؛ ایک عظیم عقاب جس کے بڑے پروں والا، لمبے پروں والا، پروں سے بھرا ہوا، جس کے رنگ مختلف تھے، لبنان آیا اور دیودار کی سب سے اونچی شاخ لے لی: {غوطہ خور...: عبرانی۔ کشیدہ کاری}\n4۔ اس نے اپنے چھوٹے ٹہنیوں کا اوپر کاٹ کر تجارت کی سرزمین میں لے گیا؛ اس نے اسے تاجروں کے شہر میں قائم کیا۔\n5۔ اس نے زمین کے بیج سے بھی لیا اور اسے زرخیز کھیت میں بویا؛ اس نے اسے بڑے پانیوں کے کنارے رکھا، اور اسے بید کے درخت کی طرح رکھا۔ {لگا ہوا...: عبرانی۔ اسے بیج کے کھیت میں ڈالیں}\n6۔ اور وہ اگ گئی، اور ایک پھیلتی ہوئی بیل بن گئی، جس کی شاخیں اس کی طرف مڑیں، اور اس کی جڑیں اس کے نیچے تھیں، یوں وہ بیل بن گئی، شاخیں نکالی اور ٹہنیاں نکالیں۔\n7۔ ایک اور بڑا عقاب بھی تھا جس کے بڑے پر اور پر بہت تھے: اور دیکھو، یہ بیل اپنی جڑیں اس کی طرف موڑ کر اس کی طرف پھینک رہی تھی تاکہ وہ اسے اس کے کھیت کی کھالوں سے پانی دے سکے۔\n8۔ یہ اچھی مٹی میں بڑے پانی کے کنارے بویا گیا تاکہ شاخیں اگا سکے، پھل دے سکے، اور اچھی بیل بن سکے۔ {مٹی: عبرانی۔ فیلڈ}\n9۔ کہو، خداوند خدا یہ فرماتا ہے؛ کیا یہ ترقی کرے گا؟ کیا وہ اس کی جڑیں نہیں اتارے گا اور اس کے پھل کاٹ کر مرجھا جائے گا؟ یہ اس کے چشمے کے تمام پتوں میں مرجھا جائے گا، چاہے بڑی طاقت یا بہت سے لوگ اسے جڑوں سے توڑ سکیں۔\n10۔ ہاں، دیکھو، {بوئے ہوئے} کیا یہ ترقی کرے گا؟ کیا یہ مکمل طور پر مرجھا نہیں جائے گا، جب مشرقی ہوا اسے چھوئے؟ یہ ان گڑھوں میں مرجھا جائے گا جہاں یہ اگ رہا تھا۔\n11۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا،\n12۔ اب باغی گھر سے کہو، کیا تم نہیں جانتے کہ یہ {چیزیں} کیا معنی رکھتی ہیں؟ انہیں بتاؤ، دیکھو، بابل کا بادشاہ یروشلم آیا ہے، اس نے اس کے بادشاہ اور اس کے بادشاہوں کو لے کر انہیں اپنے ساتھ بابل لے گیا ہے؛\n13۔ اور اس نے بادشاہ کی نسل سے لیا ہے، اس سے عہد کیا ہے، اور اس سے قسم کھائی ہے: اس نے زمین کی طاقتور کو بھی قبول کیا ہے: {لیا ہے...: عبرانی۔ اسے قسم پر لے آیا}\n14۔ تاکہ بادشاہی پست ہو، خود کو بلند نہ کرے، {لیکن} کہ اس کے عہد کی پاسداری کر کے وہ قائم رہے۔ {لیکن...: عبرانی۔ اپنے عہد کو نچانے کے لیے، اس پر قائم رہنے کے لیے}\n15۔ لیکن اس نے اس کے خلاف بغاوت کی اور اپنے سفیر مصر بھیجے تاکہ وہ اسے گھوڑے اور بہت سے لوگ دے سکیں۔ کیا وہ خوشحال ہوگا؟ کیا وہ بچ جائے گا جو ایسا کرتا ہے؟ یا وہ عہد توڑ دے اور آزاد ہو جائے؟\n16. {جت} میں زندہ ہوں، خداوند خدا فرماتا ہے، یقینا اس جگہ {جہاں} بادشاہ {بستا ہے} جس نے اسے بادشاہ بنایا، جس کی قسم کو اس نے حقیر سمجھا، اور جس کا عہد توڑا، {حتیٰ کہ} اس کے ساتھ بابل کے بیچ میں مر جائے گا۔\n17۔ نہ ہی فرعون اپنی زبردست فوج اور بڑی کمپنی کے ساتھ جنگ میں اس کے لیے سواری کرے گا، قلعے بنا کر بہت سے لوگوں کو کاٹ ڈالے گا:\n18. چونکہ اس نے عہد توڑ کر حلف سے نفرت کی، جب کہ اس نے اپنا ہاتھ دے دیا اور یہ سب کچھ کیا، تو وہ بچ نہیں سکے گا۔\n19۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ {As} میں زندہ ہوں، یقینا میری وہ قسم جو اس نے نفرت کی، اور میرا عہد جو اس نے توڑ دیا، میں اس کے اپنے سر پر بدلہ دوں گا۔\n20۔ اور میں اس پر اپنا جال پھیلاؤں گا، اور وہ میرے جال میں پکڑا جائے گا، اور میں اسے بابل لے آؤں گا، اور وہاں اس سے اس کے گناہ کی درخواست کروں گا جو اس نے میرے خلاف کیا ہے۔\n21۔ اور اس کے تمام فراری اور اس کے تمام دستے تلوار کے ہاتھوں مارے جائیں گے، اور جو باقی رہ جائیں گے وہ ہر ہوا میں بکھر جائیں گے: اور تم جان لو گے کہ میں خداوند نے کہا ہے۔\n22۔ خداوند خدا یہ فرماتا ہے؛ میں اونچے دیودار کی سب سے اونچی شاخ بھی اٹھاؤں گا، اور {اسے} کو سیٹ کروں گا؛ میں اس کے چھوٹے ٹہنیوں کے اوپر سے ایک نرم شاخ کاٹوں گا، اور اسے ایک بلند اور بلند پہاڑ پر لگاؤں گا:\n23۔ میں اسے اسرائیل کی بلندی کے پہاڑ میں لگاؤں گا: اور یہ شاخیں نکلے گا، پھل دے گا، اور ایک خوبصورت دیودار ہوگا، اور اس کے نیچے ہر پرندہ رہتا ہے؛ وہ اس کی شاخوں کے سائے میں رہیں گے۔\n24۔ اور میدان کے تمام درخت جانیں گے کہ میں خداوند نے اونچا درخت گرا دیا ہے، نچلے درخت کو بلند کیا ہے، سبز درخت کو خشک کیا ہے، اور خشک درخت کو پھلوا پھولنے پر مجبور کیا ہے: میں خداوند نے کہا اور یہ کیا ہے۔","1۔ خداوند کا کلام دوبارہ میرے پاس آیا، اور کہا،\n2. آپ کا کیا مطلب ہے کہ آپ اسرائیل کی سرزمین کے بارے میں یہ کہاوت استعمال کرتے ہیں، کہ باپ اجداد نے کھٹے انگور کھائے، اور بچوں کے دانت سخت ہو گئے ہیں؟\n3. {جت} میں زندہ ہوں، خداوند خدا فرماتا ہے، تمہیں اسرائیل میں یہ کہاوت استعمال کرنے کا مزید موقع نہیں ملے گا۔\n4. دیکھو، تمام روحیں میری ہیں؛ جیسے باپ کی روح ہے، ویسے ہی بیٹے کی روح بھی میری ہے: جو روح گناہ کرتی ہے، وہ مر جائے گی۔\n5۔ لیکن اگر کوئی شخص عادل ہو، اور وہ کام کرے جو جائز اور درست ہے، {وہ...: عبرانی۔ فیصلہ اور انصاف}\n6۔ {اور} نہ پہاڑوں پر کھایا، نہ اسرائیل کے گھر کے بتوں کی طرف اپنی آنکھیں اٹھائیں، نہ اپنے پڑوسی کی بیوی کو ناپاک کیا، نہ کسی حیض والی عورت کے قریب گیا،\n7۔ اور کسی پر ظلم نہیں کیا، {بلکہ} مقروض کو اس کا وعدہ واپس کیا، کسی کو ظلم سے خراب نہیں کیا، اپنی روٹی بھوکوں کو دی، اور ننگے کو لباس میں ڈھانپ دیا؛\n8۔ جس نے سود پر نہ دیا، نہ کوئی اضافہ کیا، {جن} نے گناہ سے اپنا ہاتھ ہٹایا، انسان اور انسان کے درمیان سچا فیصلہ کیا،\n9۔ اس نے میرے قوانین میں قدم رکھا ہے، اور میرے فیصلوں کو برقرار رکھا ہے، تاکہ سچائی سے معاملہ کرے؛ وہ عادل ہے، وہ ضرور زندہ رہے گا، خداوند خدا فرماتا ہے۔\n10۔ اگر وہ بیٹا پیدا کرے {یعنی} ڈاکو، خون بہانے والا، اور {جو} ان میں سے کسی ایک چیز کے لیے ایسا کرے، {ڈاکو: یا گھر توڑنے والا} {جو کرے...: یا جو اپنے بھائی کے ساتھ ان میں سے کسی کے علاوہ کچھ کرے}\n11۔ اور جو ان میں سے کوئی ذمہ داری پوری نہیں کرتا، بلکہ پہاڑوں پر کھا چکا ہے، اور اپنے پڑوسی کی بیوی کو ناپاک کر چکا ہے،\n12۔ اس نے غریبوں اور محتاجوں پر ظلم کیا، تشدد سے بگاڑ دیا، وعدہ واپس نہیں کیا، اور اپنی نظریں بتوں کی طرف اٹھا لیں، اور گناہ کیا ہے،\n13۔ اس نے سود پر حملہ کیا اور بڑھا دیا ہے: کیا وہ زندہ رہے گا؟ وہ زندہ نہیں رہے گا: اس نے یہ سب گنایاں کی ہیں؛ وہ یقینی طور پر مر جائے گا؛ اس کا خون اس پر ہوگا۔ {خون: عبرانی۔ bloods}\n14۔ اب، دیکھو، اگر وہ بیٹا پیدا کرے، جو اپنے والد کے تمام گناہوں کو دیکھتا ہے جو اس نے کیے ہیں، اور غور کرتا ہے، اور ایسا نہیں کرتا،\n15۔ {جس نے} نہ پہاڑوں پر کھایا ہے، نہ ہی اسرائیل کے گھر کے بتوں کی طرف آنکھیں اٹھا کر دیکھی، نہ اپنے پڑوسی کی بیوی کو ناپاک کیا ہے،\n16۔ نہ کسی نے ظلم کیا، نہ وعدہ روکا، نہ تشدد سے بگاڑا، {بلکہ} اپنی روٹی بھوکوں کو دی، اور ننگے کو لباس میں ڈھانپ دیا، {نہیں...: عبرانی۔ کیا اس نے عہد نہیں کیا، یا وعدہ نہیں لیا ہے؟\n17۔ {جو} نے غریبوں سے اپنا ہاتھ چھین لیا، {جس نے} نہ سود لیا اور نہ ہی بڑھا، میرے فیصلے نافذ کیے، میرے قوانین میں چلتا رہا؛ وہ اپنے والد کی بدکاری کے لیے نہیں مرے گا، وہ ضرور زندہ رہے گا۔\n18. جہاں تک اس کے والد کا تعلق ہے، کیونکہ اس نے ظلم کیا، اپنے بھائی کو ظلم سے بگاڑا، اور وہ کیا جو اس کے لوگوں میں اچھا نہیں، تو وہ بھی اپنی بدکاری میں مر جائے گا۔\n19۔ پھر بھی تم کہو، کیوں؟ کیا بیٹا باپ کی گناہ برداشت نہیں کرتا؟ جب بیٹے نے وہ کام کر لیا جو جائز اور درست ہے، {اور} میرے تمام قوانین کو پورا کر لیا، تو وہ یقینا زندہ رہے گا۔\n20۔ جو روح گناہ کرتی ہے، وہ مر جائے گی۔ بیٹا باپ کی بدکاری برداشت نہیں کرے گا، اور نہ ہی باپ بیٹے کی بدکاری برداشت کرے گا: راستبازوں کی نیکی اس پر ہوگی، اور بدکاروں کی برائی اس پر ہوگی۔\n21۔ لیکن اگر بدکار اپنے تمام گناہوں سے منہ موڑے، میرے تمام قوانین کی پاسداری کرے، اور جو جائز اور درست ہے وہ کرے گا، تو وہ ضرور زندہ رہے گا، وہ نہیں مرے گا۔\n22۔ اس کے تمام گناہ جو اس نے کیے ہیں، وہ اس کے سامنے ذکر نہیں کیے جائیں گے: اس کی نیکی میں جو اس نے کی ہے وہ زندہ رہے گا۔\n23. کیا مجھے کوئی خوشی ہے کہ بدکار مر جائیں؟ خداوند خدا فرماتا ہے: {اور} کہ وہ اپنے راستوں سے واپس جائے اور زندہ رہے؟\n24. لیکن جب نیک اپنی راستبازی سے منہ موڑ کر گناہ کرتا ہے، {اور} بدکار {انسان} کی تمام گناہوں کے مطابق کرتا ہے، تو کیا وہ زندہ رہے گا؟ اس کی تمام راستبازی کا ذکر نہیں کیا جائے گا: اس کے گناہ میں جو اس نے گناہ کیا، اور جو گناہ کیا، وہ انہی میں مر جائے گا۔\n25۔ پھر بھی تم کہتے ہو، خداوند کا راستہ برابر نہیں۔ اب سنو، اے اسرائیل کے گھر؛ کیا میرا طریقہ برابر نہیں؟ کیا آپ کے طریقے غیر مساوی نہیں ہیں؟\n26۔ جب کوئی نیک انسان اپنی راستبازی سے منہ موڑ لے، گناہ کرے اور اسی میں مر جائے؛ اس کے کیے گئے گناہوں کے لیے وہ مر جائے گا۔\n27۔ پھر جب بدکار {انسان} اپنی کی ہوئی برائی سے منہ موڑ لے اور وہ کام کرے جو جائز اور درست ہے، تو وہ اپنی جان کو زندہ بچائے گا۔\n28. کیونکہ وہ غور کرے گا، اور اپنی تمام گناہوں سے منہ موڑ لے گا جو اس نے کی ہیں، وہ یقینی طور پر زندہ رہے گا، وہ نہیں مرے گا۔\n29۔ پھر بھی اسرائیل کا گھر فرماتا ہے، خداوند کا راستہ برابر نہیں۔ اے اسرائیل کے گھر، کیا میرے طریقے برابر نہیں؟ کیا آپ کے طریقے غیر مساوی نہیں ہیں؟\n30. اسی لیے میں تمہیں فیصلہ کروں گا، اے اسرائیل کے گھرانے پر، ہر ایک اپنے طریقے کے مطابق، خداوند خدا فرماتا ہے۔ توبہ کرو، اور اپنے تمام گناہوں سے معذرت کرو؛ تو بدکاری تمہاری بربادی نہیں ہوگی۔ {تم خود: یا، دوسرے}\n31۔ اپنی تمام گناہوں کو جو تم نے گناہ کیے ہیں، اپنے اندر سے دور کر دو؛ اور تمہیں نیا دل اور نئی روح دوں: کیونکہ تم کیوں مرو گے، اے اسرائیل کے گھرانے کے لیے؟\n32۔ کیونکہ مجھے اس کی موت میں کوئی خوشی نہیں، خداوند خدا فرماتا ہے: کیوں مڑ جاؤ اور زندہ رہو۔ {تم خود: یا، دوسرے}","1۔ مزید یہ کہ اسرائیل کے شہزادوں کے لیے نوحہ اٹھاؤ،\n2۔ اور کہو، تیری ماں کیا ہے؟ شیرنی: وہ شیروں کے درمیان لیٹتی تھی، اپنے بچوں کو نوجوان شیروں کے درمیان پالتی۔\n3۔ اور اس نے اپنے ایک بچے کی پرورش کی: وہ ایک نوجوان شیر بن گیا، اور شکار پکڑنا سیکھ گیا؛ یہ مردوں کو نگل جاتا تھا۔\n4۔ قوموں نے بھی ان کے بارے میں سنا؛ اسے ان کے گڑھے میں لے جایا گیا، اور اسے زنجیروں میں جکڑ کر مصر کی سرزمین لے آئے۔\n5۔ اب جب اس نے دیکھا کہ وہ انتظار کر چکی ہے، {اور} اس کی امید ختم ہو گئی ہے، تو اس نے اپنے ایک اور بچے کو لے لیا، {اور} اسے ایک نوجوان شیر بنا دیا۔\n6۔ اور وہ شیروں کے درمیان اوپر نیچے گیا، ایک نوجوان شیر بن گیا، اور شکار پکڑنا سیکھا، {اور} انسانوں کو کھا گیا۔\n7۔ اور وہ ان کے ویران محلوں کو جانتا تھا، اور اس نے ان کے شہروں کو تباہ کر دیا؛ اور زمین ویران تھی، اور اس کی بھرپوریت بھی، اس کی دہاڑ کی آواز سے۔ {ان کی ویرانی...: یا، ان کی بیوائیں ہیں} {مکمل پن...: یا، اس میں موجود سب کچھ}\n8۔ پھر قوموں نے صوبوں سے ہر طرف اس کے خلاف کھڑے ہو کر اس پر جال پھیلا دیا: وہ ان کے گڑھے میں گرفتار ہو گیا۔\n9۔ اور انہوں نے اسے زنجیروں میں جکڑ کر بابل کے بادشاہ کے پاس لے گئے: اسے قید میں لے آئے تاکہ اس کی آواز اسرائیل کے پہاڑوں پر نہ سنائی دے۔ {زنجیروں میں: یا، ہکس میں}\n10۔ تیری ماں {ہے} تمہارے خون میں بیل کی مانند ہے، جو پانیوں سے بوئی گئی ہے: وہ بہت سے پانیوں کی وجہ سے زرخیز اور شاخوں سے بھری ہوئی تھی۔ {میں...: یا، تمہاری خاموشی میں، یا، تمہاری شکل میں}\n11۔ اور اس کے پاس ان کے عصا کے لیے مضبوط چھڑیاں تھیں جو حکمرانی نہیں کر سکتیں، اور اس کی قامت موٹی شاخوں میں بلند تھی، اور وہ اپنی شاخوں کی کثرت کے ساتھ بلند نظر آتی تھی۔\n12۔ لیکن وہ غصے میں اٹھائی گئی، اسے زمین پر گرا دیا گیا، اور مشرقی ہوا نے اس کے پھل کو خشک کر دیا: اس کی مضبوط چھڑیاں ٹوٹ گئیں اور مرجھا گئیں؛ آگ نے انہیں جلا لیا۔\n13۔ اور اب وہ {ہے} جنگل میں، ایک خشک اور پیاسی زمین میں۔\n14۔ اور اس کی شاخوں کی ایک چھڑی سے آگ نکل جاتی ہے، {جس نے} اس کے پھل کو کھا لیا ہے، یہاں تک کہ اس کے پاس کوئی مضبوط عصا نہیں بنے جو حکمرانی کرے۔ یہ {ہے} ایک نوحہ، اور ایک نوحہ کے لیے ہوگا۔","1۔ اور یہ ساتویں سال، پانچویں مہینے میں، مہینے کے دسواں دن ہوا، {کہ} اسرائیل کے کچھ بزرگ خداوند سے پوچھنے آئے اور میرے سامنے بیٹھ گئے۔\n2۔ پھر خداوند کا کلام میرے پاس آیا، جس نے کہا،\n3۔ اے انسان کے بیٹے، اسرائیل کے بزرگوں سے بات کر، اور ان سے کہو، خداوند خدا یہ فرماتا ہے؛ کیا تم مجھ سے پوچھنے آئے ہو؟ {As} میں زندہ ہوں، خداوند خدا فرماتا ہے، تم مجھ سے سوال نہیں کرو گے۔\n4. کیا تم ان کا فیصلہ کرو گے، انسان کے بیٹے، کیا تم ان کا فیصلہ کرو گے؟ انہیں ان کے باپ و اجداد کی گناہوں کا علم دلاؤ: {کیا تم ان کے لیے درخواست کرو گے}\n5۔ اور ان سے کہو، خداوند خدا یہ فرماتا ہے؛ جب میں نے اسرائیل کو چنا، اور یعقوب کے خاندان کی نسل کی طرف اپنا ہاتھ اٹھایا، اور مصر کی سرزمین میں ان کے سامنے خود کو ظاہر کیا، جب میں نے ان کی طرف ہاتھ اٹھایا اور کہا، میں خداوند تمہارا خدا ہوں؛ {اٹھایا...: یا، قسم کھانا}\n6۔ اس دن میں نے ان کی طرف ہاتھ اٹھایا، انہیں مصر کی سرزمین سے نکال کر اس سرزمین میں لے جا سکا جس کی میں نے ان کے لیے جاسوسی کی تھی، جو دودھ اور شہد سے بہتی ہے، جو تمام زمینوں کی شان ہے:\n7۔ پھر میں نے ان سے کہا، تم ہر انسان کی آنکھوں کی گناہیتیں پھینک دو، اور مصر کے بتوں سے خود کو ناپاک نہ کرو: میں تمہارا خداوند خدا ہوں۔\n8۔ لیکن انہوں نے میرے خلاف بغاوت کی، اور میری بات نہیں سنے: انہوں نے ہر آدمی نے اپنی آنکھوں کی گناہوں کو نہیں پھینکا، نہ ہی مصر کے بتوں کو چھوڑا: پھر میں نے کہا، میں ان پر اپنا غصہ نکالوں گا، تاکہ مصر کی سرزمین کے بیچ میں ان پر اپنا غصہ نکال سکوں۔\n9۔ لیکن میں نے اپنے نام کے لیے یہ کوشش کی کہ یہ ان کافروں کے سامنے آلودہ نہ ہو، جن میں سے وہ تھے، جن کے سامنے میں نے انہیں مصر کی سرزمین سے نکالا تھا۔\n10۔ اسی لیے میں نے انہیں مصر کی سرزمین سے باہر نکالا اور بیابان میں لے آیا۔\n11۔ اور میں نے انہیں اپنے قوانین دیے، اور اپنے فیصلے دکھائے، جو {اگر کوئی آدمی} کرے تو وہ ان میں بھی زندہ رہے گا۔ {دکھایا...: ہیب۔ انہیں بتا دیا}\n12۔ مزید برآں، میں نے انہیں اپنے سبت دیے، تاکہ وہ میرے اور ان کے درمیان ایک نشان بن سکیں، تاکہ وہ جان سکیں کہ میں وہ خداوند ہوں جو انہیں پاک کرتا ہے۔\n13۔ لیکن اسرائیل کے خاندان نے بیابان میں میرے خلاف بغاوت کی: وہ میرے قوانین میں نہیں چلے، اور میرے فیصلوں سے نفرت کی، جو {اگر کوئی ایسا کرے} تو وہ ان میں بھی زندہ رہے گا؛ اور میرے سبت بہت آلودہ تھے: پھر میں نے کہا، میں ان پر صحرا میں اپنا غصہ نکالوں گا، تاکہ انہیں نگل جاؤں۔\n14۔ لیکن میں نے اپنے نام کے لیے دعا کی کہ یہ ان کافروں کے سامنے آلودہ نہ ہو، جن کے سامنے میں نے انہیں باہر نکالا۔\n15۔ پھر بھی میں نے بیابان میں ان کی طرف ہاتھ اٹھایا، تاکہ میں انہیں اس زمین میں نہ لے جاؤں جو میں نے انہیں دی تھی، جو دودھ اور شہد سے بہتی ہے، جو تمام زمینوں کی شان ہے؛\n16۔ کیونکہ انہوں نے میرے فیصلوں سے نفرت کی، اور میرے قوانین میں نہیں چلے، بلکہ میرے سبت کو آلودہ کیا: کیونکہ ان کا دل اپنے بتوں کے پیچھے گیا۔\n17. پھر بھی میری آنکھ نے انہیں تباہ کرنے سے بچایا، نہ ہی میں نے انہیں جنگل میں ختم کیا۔\n18۔ لیکن میں نے ان کے بچوں سے بیابان میں کہا، اپنے باپ اجداد کے قوانین میں نہ چلو، نہ ان کے فیصلوں کی پابندی کرو، اور نہ ہی اپنے آپ کو ان کے بتوں سے آلودہ کرو:\n19. میں {ہوں} خداوند تمہارا خدا؛ میرے قوانین میں چلیں، اپنے فیصلوں کو برقرار رکھیں، اور ان پر عمل کریں؛\n20۔ اور میرے سبت مقدس ہوں؛ اور وہ میرے اور تمہارے درمیان ایک نشان ہوں گے، تاکہ تم جان سکو کہ میں تمہارا خداوند خدا ہوں۔\n21۔ اگرچہ بچوں نے میرے خلاف بغاوت کی: وہ میرے قوانین میں نہیں چلے، نہ ہی میرے فیصلے پر عمل کرتے، جو {اگر کوئی ایسا کرتا ہے} تو وہ ان میں بھی زندہ رہے گا؛ انہوں نے میرے سبت کو آلودہ کیا: پھر میں نے کہا، میں ان پر اپنا غصہ نکالوں گا، تاکہ ان پر صحرا میں اپنا غصہ پورا کر سکوں۔\n22۔ پھر بھی میں نے اپنا ہاتھ ہٹا لیا، اور اپنے نام کے لیے یہ کوشش کی کہ وہ ان کافروں کی نظر میں آلودہ نہ ہو جن کے سامنے میں نے انہیں پیش کیا۔\n23۔ میں نے ان کے لیے جنگل میں بھی ہاتھ اٹھایا، تاکہ انہیں کافروں میں بکھیر دوں، اور دیہات میں پھیلا دوں؛\n24۔ کیونکہ انہوں نے میرے فیصلوں پر عمل نہیں کیا، بلکہ میرے قوانین سے نفرت کی، میرے سبت آلودہ کیے، اور ان کی نظریں اپنے باپ کے بتوں پر تھیں۔\n25۔ اسی لیے میں نے انہیں ایسے قوانین بھی دیے جو اچھے نہیں تھے، اور ایسے فیصلے بھی دیے جن پر وہ زندہ نہیں رہ سکتے؛\n26۔ اور میں نے انہیں ان کے اپنے تحفوں میں آلودہ کیا، کیونکہ انہوں نے {آگ} سے رحم کے ہر حصے کو گزرنے پر مجبور کیا، تاکہ میں انہیں ویران کر سکوں، تاکہ وہ جان سکیں کہ میں {ہوں} خداوند ہوں۔\n27. لہٰذا، اے انسان کے بیٹے، اسرائیل کے گھر سے بات کر، اور ان سے کہو، خداوند خدا یہ فرماتا ہے؛ پھر بھی اس میں تمہارے آباؤ اجداد نے میری توہین کی ہے، کیونکہ انہوں نے میرے خلاف گناہ کیا ہے۔ {کمیٹڈ...: ہیب۔ غیر قانونی داخلہ}\n28۔ {کیونکہ} جب میں نے انہیں زمین میں لایا، {کیونکہ میں نے اپنا ہاتھ اٹھا کر انہیں دیا تھا، تو انہوں نے ہر اونچی پہاڑی اور گھنے درخت دیکھے، اور وہاں اپنی قربانیاں پیش کیں، اور وہاں انہوں نے اپنی پیشکش کی تحریک دی: وہاں انہوں نے بھی اپنی میٹھا ذائقہ پیش کیا،  اور انہوں نے وہاں اپنے مشروبات کی پیشکشیں نکالیں۔\n29۔ پھر میں نے ان سے کہا، وہ بلند مقام کیا ہے جہاں تم جاتے ہو؟ اور اس کا نام آج تک بامہ کہلاتا ہے۔ {میں نے کہا...: یا، میں نے انہیں بتایا کہ اونچی جگہ کیا ہے، یا، باما}\n30۔ لہٰذا اسرائیل کے گھر سے کہو، خداوند خدا یہ فرماتا ہے؛ کیا تم اپنے باپ والد کی طرح آلودہ ہو؟ اور ان کی مکروہ حرکتوں کے بعد بدکاری کرتے ہو؟\n31۔ کیونکہ جب تم اپنے تحفے پیش کرتے ہو، جب تم اپنے بیٹوں کو آگ سے گزارنے پر مجبور کرتے ہو، تو تم اپنے تمام بتوں سے خود کو آلودہ کرتے ہو، آج تک: اور کیا تم مجھ سے پوچھتے ہو، اے اسرائیل کے گھرانہ؟ {As} میں زندہ ہوں، خداوند خدا فرماتا ہے، تم مجھ سے سوال نہیں کرو گے۔\n32۔ اور جو کچھ تمہارے ذہن میں آئے گا وہ بالکل نہیں ہوگا کہ تم کہو، ہم کافروں کی طرح، ملکوں کے خاندانوں کی طرح لکڑی اور پتھر کی خدمت کریں گے۔\n33۔ {جوں} میں زندہ ہوں، خداوند خدا فرماتا ہے، یقینا ایک طاقتور ہاتھ، پھیلائے ہوئے بازو کے ساتھ، اور غصے کے ساتھ، میں تم پر حکومت کروں گا:\n34۔ اور میں تمہیں لوگوں میں سے نکالوں گا، اور تمہیں ان ملکوں سے نکالوں گا جہاں تم بکھرے ہوئے ہو، طاقتور ہاتھ، بازو پھیلا کر، اور غصے کے ساتھ۔\n35۔ اور میں تمہیں لوگوں کے بیابان میں لے جاؤں گا، اور وہاں تم سے آمنے سامنے درخواست کروں گا۔\n36۔ جیسے میں نے تمہارے آباؤ اجداد سے مصر کی سرزمین کے بیابان میں التجا کی، ویسے ہی میں تم سے درخواست کروں گا، خداوند خدا فرماتا ہے۔\n37۔ اور میں تمہیں چھڑی کے نیچے لے جاؤں گا، اور تمہیں عہد کی بندھن میں لے آؤں گا: {بندھن: یا، نجات دینا}\n38۔ اور میں تم میں سے باغیوں اور جو میرے خلاف گناہ کریں گے انہیں نکال دوں گا: میں انہیں اس ملک سے نکالوں گا جہاں وہ رہتے ہیں، اور وہ اسرائیل کی سرزمین میں داخل نہیں ہوں گے: اور تم جان لو گے کہ میں خداوند ہوں۔\n39۔ اور تم، اے اسرائیل کے گھرانہ، خداوند خدا یہ فرماتا ہے؛ تم جاؤ، ہر ایک کے بتوں کی عبادت کرو، اور آخرت میں بھی، اگر تم میری بات نہیں سنتے: لیکن میرے مقدس نام کو اپنے تحفوں اور بتوں سے مزید آلودہ نہ کرو۔\n40۔ کیونکہ میرے مقدس پہاڑ میں، اسرائیل کی بلندی کے پہاڑ پر، خداوند خدا فرماتا ہے، وہاں اسرائیل کا سارا گھر، زمین میں سب میرے لیے عبادت کریں گے: وہاں میں انہیں قبول کروں گا، اور وہاں میں تمہاری نذرانے اور تمہارے نذرانے کے پہلے پھل، تمہاری تمام مقدس چیزوں کے ساتھ طلب کروں گا۔ {فرسٹ فروٹس: یا، چیف}\n41. میں تمہیں تمہاری میٹھی خوشبو کے ساتھ قبول کروں گا، جب میں تمہیں لوگوں سے نکالوں گا، اور تمہیں ان ملکوں سے نکالوں گا جہاں تم بکھرے ہوئے تھے؛ اور میں تم میں کافروں کے سامنے پاک ہو جاؤں گا۔ {میٹھا...: عبرانی۔ آرام کا ذائقہ}\n42. اور تم جان لو گے کہ میں خداوند ہوں، جب میں تمہیں اسرائیل کی سرزمین میں لے آؤں گا، اس ملک میں {کیونکہ میں نے اپنا ہاتھ اٹھا کر تمہارے آباؤ اجداد کو دیا ہے۔'\n43۔ اور وہاں تم اپنے طریقے اور اپنے تمام اعمال کو یاد کرو گے جن میں تم ناپاک ہوئے؛ اور تم اپنی نظر میں اپنی تمام برائیوں کے لیے خود کو ناپسند کرو گے۔\n44. اور تم جان لو گے کہ میں خداوند ہوں، جب میں نے تمہارے ساتھ اپنے نام کے لیے کیا ہے، نہ تمہارے برے طریقوں کے مطابق، نہ تمہارے برے اعمال کے مطابق، اے اسرائیل کے گھرانے، خداوند خدا فرماتا ہے۔\n45۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا،\n46۔ اے انسان کے بیٹے، اپنا رخ جنوب کی طرف کرو، اور اپنا کلام جنوب کی طرف گرا دو، اور جنوبی میدان کے جنگل کے خلاف پیش گوئی کرو؛\n47۔ اور جنوب کے جنگل سے کہو، خداوند کا کلام سنو؛ خداوند خدا یہ فرماتا ہے؛ دیکھو، میں تمہارے اندر آگ جلاؤں گا، جو تمہارے ہر سبز درخت اور ہر خشک درخت کو نگل جائے گی: شعلہ بجھائے گا نہیں، اور جنوب سے شمال تک کے تمام چہرے اس میں جل جائیں گے۔\n48۔ اور ہر جسم دیکھے گا کہ میں خداوند نے اسے جلا دیا ہے: یہ بجھا نہیں جائے گا۔\n49۔ پھر میں نے کہا، اے خداوند! وہ میرے بارے میں کہتے ہیں، کیا وہ تمثیلیں نہیں بولتا؟","1۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، اپنا چہرہ یروشلم کی طرف موڑو، اور مقدس مقامات کی طرف اپنا کلام پھینک دو، اور اسرائیل کی سرزمین کے خلاف نبوت کرو،\n3۔ اور اسرائیل کی سرزمین سے کہے، خداوند نے ایسا فرمایا؛ دیکھو، میں تمہارے خلاف ہوں، اور اپنی تلوار اس کے غلاف سے نکالوں گا، اور تم سے نیک اور بدکاروں کو کاٹ دوں گا۔\n4۔ جب میں دیکھتا ہوں کہ میں تم سے نیک اور بدکاروں کو کاٹ دوں گا، تو میری تلوار اس کی میان سے نکلے گی اور جنوب سے شمال تک تمام جسموں پر حملہ کرے گی:\n5۔ تاکہ ہر انسان جان لے کہ میں خداوند نے اپنی تلوار اس کی میان سے نکالی ہے: وہ اب واپس نہیں آئے گی۔\n6. لہٰذا، اے انسان کے بیٹے، اپنی کمر ٹوٹنے پر آہ بھرو؛ اور تلخی کے ساتھ ان کی آنکھوں کے سامنے آہ بھری۔\n7۔ اور جب وہ تم سے کہیں گے، تم کیوں آہ بھرتے ہو؟ کہ تم جواب دو گے، خبر کے لیے؛ کیونکہ یہ آتا ہے: اور ہر دل پگھل جائے گا، اور سب ہاتھ کمزور ہو جائیں گے، اور ہر روح بے ہوش ہو جائے گی، اور سب گھٹنے کمزور ہو جائیں گے جیسے پانی: دیکھو، یہ آتا ہے اور پورا ہو جائے گا، خداوند خدا فرماتا ہے۔ {کمزور ہو جائے گا...: عبرانی۔ پانی میں جائے گا}\n8۔ پھر خداوند کا کلام میرے پاس آیا، جس میں کہا،\n9۔ اے انسان کے بیٹے، نبوت کرو اور کہو، خداوند یوں فرماتا ہے؛ کہو، ایک تلوار، تلوار تیز کی جاتی ہے، اور ساتھ ہی سجائی جاتی ہے:\n10۔ اسے تیز کر کے ذبح کیا جاتا ہے؛ یہ اس لیے تیار کیا گیا ہے کہ وہ چمکے: کیا ہمیں پھر خوشی پیدا کرنی چاہیے؟ یہ میرے بیٹے کی چھڑی کو قید کرتی ہے، {ویسے} جیسے ہر درخت۔ {یہ حقارت کرتا ہے...: یا، یہ میرے بیٹے کی چھڑی ہے، یہ ہر درخت سے نفرت کرتی ہے}\n11۔ اور اس نے اسے تیار کرنے کے لیے دیا ہے، تاکہ اسے سنبھالا جا سکے: یہ تلوار تیز کی جاتی ہے، اور اسے سلیر کے ہاتھ میں دینے کے لیے تیار کی جاتی ہے۔\n12۔ چیخ و پکار کر، اے انسان کے بیٹے: کیونکہ یہ میرے لوگوں پر ہوگا، یہ اسرائیل کے تمام شہزادوں پر ہوگا: تلوار کی وجہ سے میرے لوگوں پر دہشت ہوگی: لہٰذا تیری ران پر وار کرو۔ {دہشت...: یا، انہیں میرے لوگوں کے ساتھ تلوار کے حوالے کر دیا جاتا ہے}\n13. کیونکہ {یہ} ایک آزمائش ہے، اور اگر {تلوار} لاٹھی کو بھی نقصان پہنچائے تو؟ یہ {اب مزید نہیں} ہوگا، خداوند خدا فرماتا ہے۔ {کیونکہ...: یا، جب آزمائش ہو جائے، تو پھر کیا؟ کیا وہ بھی حقیر لاٹھی کے ساتھ نہیں ہوں گے؟}\n14. تو، انسان کے بیٹے، نبوت کر، اور اپنے ہاتھوں کو ایک ساتھ مارو، اور تلوار کو تیسری بار دوہرا کر دوہرا کر دو، مارے گئے کی تلوار: یہ عظیم {مرد} کی تلوار ہے جو ان کے کمرے میں داخل ہوتی ہے۔ {ہاتھ...: عبرانی۔ ہاتھا پائی\n15. میں نے تلوار کی نوک ان کے تمام دروازوں کے خلاف رکھی ہے، تاکہ ان کا دل بے ہوش ہو جائے اور ان کے کھنڈرات بڑھ جائیں: آہ! {یہ} روشن کیا گیا ہے، {یہ} قتل کے لیے لپٹا ہوا ہے۔ {نقطہ: یا، چمکدار، یا، خوف} {لپیٹا ہوا: یا، تیز کیا گیا}\n16. کسی ایک طرف جاؤ، {یا تو} دائیں طرف، {یا} بائیں طرف، جہاں تمہارا چہرہ {لگا} ہو۔ {یا پر...: عبرانی۔ خود کو سنبھالو، بایاں ہاتھ پکڑو}\n17. میں اپنے ہاتھوں کو بھی آپس میں ماروں گا، اور اپنے غصے کو آرام دوں گا: میں نے خداوند کہا ہے {یہ}۔\n18۔ خداوند کا کلام دوبارہ میرے پاس آیا، اور کہا،\n19۔ اور اے انسان کے بیٹے، اپنے لیے دو راستے مقرر کر، تاکہ بابل کے بادشاہ کی تلوار آ سکے: دونوں ایک ہی زمین سے نکلیں گے: اور ایک جگہ چنو، جو شہر جانے کے راستے کے سرے پر ہو۔\n20۔ ایک راستہ مقرر کرو تاکہ تلوار عمونیوں کے رباط اور یروشلم میں یہوداہ کے دفاع میں آ سکے۔\n21. کیونکہ بابل کا بادشاہ راستے کے جدائی پر، دو راستوں کے سرے پر کھڑا تھا، فال گیری کے لیے: اس نے {اپنے} تیر روشن کیے، تصاویر سے مشورہ کیا، جگر میں دیکھا۔ {الوداع: عبرانی۔ ماں} {تیر: یا، چھریاں} {تصاویر: عبرانی۔ ٹیرافیم}\n22۔ اس کے دائیں ہاتھ پر یروشلم کے لیے پیش گوئی تھی، کپتان مقرر کرنا، قتل عام میں زبان کھولنا، آواز بلند کرنا، دروازوں پر مینڈھے مارنا، گھوڑا پھینکنا، اور قلعہ بنانا۔ {کپتان: یا، بیٹرنگ ریمز: عبوری۔ ریمز}\n23۔ اور یہ ان کے سامنے جھوٹی پیش گوئی ہوگی، ان کے لیے جنہوں نے قسم کھائی ہے، لیکن وہ گناہوں کو یاد کرنے کی دعوت دے گا، تاکہ انہیں گرفتار کیا جا سکے۔ {ان سے...: یا، ان سے کیے گئے حلفوں کے لیے}\n24۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ کیونکہ تم نے اپنی گناہوں کو یاد دلایا ہے، تاکہ تمہاری غلطیاں ظاہر ہوں، تاکہ تمہارے تمام اعمال میں تمہارے گناہ ظاہر ہوں؛ کیونکہ، {میں کہتا ہوں}، جب تم یاد میں آئے ہو، تو تم ہاتھ سے پکڑے جاؤ گے۔\n25۔ اور تم، اسرائیل کے ناپاک بدکار شہزادے، جس کا دن آ گیا ہے، جب گناہ کا انجام ہوگا،\n26۔ خداوند خدا یہ فرماتا ہے؛ تاج اتارو، اور تاج اتار دو: یہ {ہوگا} وہی نہیں ہوگا: {جو نیچا ہے} کو بلند کرے، اور جو بلند ہے اسے نیچا کرے۔\n27. میں اسے الٹ دوں گا، الٹ دوں گا، الٹ دوں گا: اور یہ {اب تک} نہیں ہوگا، جب تک کہ وہ نہ آ جائے جس کا حق ہے؛ اور میں اسے دے دوں گا۔ {میں الٹ دوں گا...: عبرانی۔ منفی، بگاڑ، بگاڑ، کیا میں کامیاب ہو جاؤں گا}\n28۔ اور تو، انسان کے بیٹے، نبوت کرو اور کہو، خداوند خدا نے عمونیوں اور ان کی ملامت کے بارے میں یہی فرمایا؛ یہاں تک کہ کہو، تلوار، تلوار {نکالی} گئی ہے: ذبح کے لیے {یہ} تیار کی گئی ہے، چمکدار روشنی کی وجہ سے کھانے کے لیے:\n29۔ جب وہ تمہیں دھوکہ دیکھتے ہیں، جبکہ وہ تم سے جھوٹ گھڑتے ہیں، تاکہ تمہیں ان لوگوں کی گردن میں لگا دیں جو مارے گئے، بدکاروں کی، جن کا دن آ چکا ہے، جب ان کی گناہوں کا انجام ہوگا۔\n30۔ کیا میں اسے اس کے غلاف میں واپس لے آؤں؟ میں تمہیں اس جگہ پر فیصلہ کروں گا جہاں تم پیدا ہوئے، تمہاری پیدائش کی زمین میں۔ {کرے...: یا، اسے واپس لے آئے}\n31۔ اور میں اپنی ناراضگی تم پر نکالوں گا، اپنے غضب کی آگ میں تم پر پھونک ماروں گا، اور تمہیں ظالم لوگوں کے ہاتھوں میں دے دوں گا، {اور} ماہر تباہ کرنے کے لیے۔ {وحشی: یا، جلنا}\n32۔ تم آگ کے ایندھن کے لیے بنو گے؛ تمہارا خون زمین کے بیچ ہوگا؛ تمہیں دوبارہ یاد نہیں رکھا جائے گا: کیونکہ میں خداوند نے کہا ہے۔","1۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اب، اے انسان کے بیٹے، کیا تم فیصلہ کرو گے، کیا تم اس خونریز شہر کا فیصلہ کرو گے؟ ہاں، تم اسے اس کی تمام گناہوں کو دکھاؤ گے۔ {جج: یا، درخواست کریں} {خون آلود...: عببرانی۔ خون کا شہر؟} {اسے دکھاؤ: عبرانی۔ اسے بتاؤ}\n3۔ پھر کہو، خداوند خدا یوں فرماتا ہے، شہر خون بہاتا ہے تاکہ اس کا وقت آ جائے، اور اپنے خلاف بت بنائے تاکہ خود کو ناپاک کرے۔\n4۔ تم اپنے خون میں مجرم بن گئے ہو جو تم نے بہایا ہے؛ اور اپنے بنائے ہوئے بتوں میں خود کو ناپاک کیا ہے؛ اور تم نے اپنے دنوں کو قریب کر دیا ہے، اور تم اپنی عمر میں بھی آ گئے ہو: اس لیے میں نے تمہیں کافروں کے لیے ملامت اور تمام ملکوں کے لیے مذاق بنا دیا ہے۔\n5. {جو قریب ہیں} اور {جو آپ سے دور ہیں} وہ آپ کا مذاق اڑائیں گے، {جو کہ بدنام زمانہ ہے {اور} بہت پریشان کن ہے۔ {بدنام...: عبرانی۔ نام سے آلودہ، اور بہت پریشان کن ہے}\n6۔ دیکھو، اسرائیل کے بادشاہوں، سب تمہارے اندر تھے تاکہ خون بہا سکے۔ {پاور: عبرانی آرم}\n7۔ انہوں نے باپ اور ماں کے ہاتھوں آپ میں روشنی ڈالی: آپ کے درمیان اجنبی کے ساتھ ظلم کیا: آپ میں انہوں نے یتیم اور بیوہ کو پریشان کیا۔ {ظلم: یا، دھوکہ}\n8۔ تو نے میری مقدس چیزوں کو حقیر سمجھا، اور میرے سبت کی بے حرمتی کی۔\n9۔ تم میں ایسے لوگ ہیں جو کہانیاں خون بہانے کے لیے لے جاتے ہیں: اور تم میں وہ پہاڑوں پر کھاتے ہیں: تمہارے درمیان وہ بے حیائی کرتے ہیں۔ {وہ...: عببرانی۔ بہتان کے بارے میں}\n10۔ انہوں نے اپنے باپ و اجداد کی برہنگی تیرے میں دریافت کی: تیرے اندر انہوں نے اس عورت کو ذلیل کیا جو آلودگی کے لیے مخصوص تھی۔\n11۔ اور ایک نے اپنے پڑوسی کی بیوی کے ساتھ گناہ کی ہے؛ اور ایک اور نے اس کی بہو کو بے حیائی سے بدنام کیا؛ اور تمہارے اندر ایک اور نے اس کی بہن، اس کے والد کی بیٹی کو عاجز کیا ہے۔ {ایک: یا، ہر ایک} {ایک اور: یا، ہر ایک} {فحش انداز میں: یا، فحش پن سے}\n12۔ تیرے اندر انہوں نے خون بہانے کے لیے تحفے لیے؛ تم نے سود لیا ہے اور بڑھا دیا ہے، اور تم نے اپنے پڑوسیوں سے لالچی طور پر بھتہ خوری سے حاصل کیا ہے، اور مجھے بھول گئے ہو، خداوند خدا فرماتا ہے۔\n13۔ دیکھو، میں نے تمہارے بے ایمان فائدے پر اپنا ہاتھ مارا ہے جو تم نے حاصل کیا، اور تمہارے خون پر جو تمہارے درمیان تھا۔\n14۔ کیا تمہارا دل برداشت کر سکتا ہے، یا تمہارے ہاتھ مضبوط ہو سکتے ہیں، ان دنوں میں جب میں تمہارے ساتھ معاملہ کروں گا؟ میں، خداوند، نے کہا ہے، اور یہ کروں گا۔\n15۔ اور میں تمہیں کافروں میں بکھیر دوں گا، تمہیں ملکوں میں بکھیر دوں گا، اور تمہاری گندگی تم سے نکال دوں گا۔\n16۔ اور تم اپنی وراثت اپنے اندر کافروں کے سامنے لو گے، اور تم جان جاؤ گے کہ میں خداوند ہوں۔ {لیا جائے گا...: یا، بے حرمتی کی جائے گی}\n17۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا،\n18۔ اے انسان کے بیٹے، اسرائیل کا گھر میرے لیے کچرا بن گیا ہے: سب کچھ پتل، ٹن، لوہا اور سیسہ ہے، بھٹی کے بیچ میں؛ وہ چاندی کا گندگی بھی ہیں۔ {چاندی کا فضلہ: عبرانی۔ ڈروسز، وغیرہ}\n19۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ کیونکہ تم سب فضلہ بن گئے ہو، دیکھو، اس لیے میں تمہیں یروشلم کے بیچ میں جمع کروں گا۔\n20۔ {جیسا کہ وہ چاندی، پیتل، لوہا، سیسہ اور ٹن جمع کرتے ہیں، بھٹی کے بیچ میں، تاکہ اس پر آگ پھونکیں، اسے پگھلا دیں}؛ اسی طرح میں تمہیں اپنے غصے اور غصے میں جمع کروں گا، اور تمہیں وہیں چھوڑ دوں گا، اور تمہیں پگھلا دوں گا۔ {یعنی...: عبرانی۔ اجتماع کے مطابق}\n21۔ ہاں، میں تمہیں جمع کروں گا، اور اپنے غضب کی آگ میں تم پر پھونک ماروں گا، اور تم اس کے بیچ پگھل جاؤ گے۔\n22۔ جیسے چاندی بھٹی کے بیچ میں پگھلتی ہے، ویسے ہی تم اس کے بیچ میں پگھلو گے؛ اور تم جان لو گے کہ میں، خداوند، نے تم پر اپنا غصہ نکالا ہے۔\n23۔ اور خداوند کا کلام میرے پاس آیا، جس نے کہا،\n24۔ اے انسان کے بیٹے، اس سے کہو، تو وہ زمین ہو جو نہ پاک کی گئی اور نہ ہی غصے کے دن بارش ہوئی۔\n25. اس کے انبیاء کی سازش اس کے درمیان ہے، جیسے دہاڑتا ہوا شیر شکار کو بھونکتا ہے؛ انہوں نے روحیں نگل لی ہیں؛ انہوں نے خزانہ اور قیمتی چیزیں لے لی ہیں؛ انہوں نے اس کے بیچ میں کئی بیوائیں بنا دی ہیں۔\n26. اس کے پادریوں نے میرے قانون کی خلاف ورزی کی ہے، اور میری مقدس چیزوں کی بے حرمتی کی ہے: انہوں نے پاک اور ناپاک میں کوئی فرق نہیں رکھا، نہ ہی ناپاک اور پاک میں فرق ظاہر کیا، اور میری سبت سے اپنی آنکھیں چھپا لیں، اور میں ان میں ناپاک ہوں۔ {خلاف ورزی کی گئی: عبرانی۔ تشدد کی پیشکش کی}\n27. اس کے شہزادے ان کے درمیان {بھیڑیے} کی طرح ہیں جو شکار کو بھونکتے ہیں، خون بہاتے ہیں، {اور} روحوں کو تباہ کرتے ہیں، بے ایمانی حاصل کرتے ہیں۔\n28۔ اور اس کے نبیوں نے انہیں بے قابو {morter} سے نوازا ہے، جو ان سے جھوٹ دیکھتے ہیں اور ان سے جھوٹ پیش کرتے ہیں، کہتے ہیں، خداوند خدا ایسا فرماتا ہے، جب خداوند نے کچھ نہیں کہا۔\n29۔ ملک کے لوگوں نے ظلم کیا، لوٹ مار کی، اور غریبوں اور محتاجوں کو پریشان کیا: ہاں، انہوں نے اجنبی پر ظلم کیا۔ {ظلم: یا، دھوکہ} {غلط طور پر: عبرانی۔ بغیر حق کے}\n30۔ اور میں نے ان میں سے ایک ایسا آدمی تلاش کیا جو جھاڑی کو پورا کرے، اور میرے سامنے زمین کے لیے کھائی میں کھڑا ہو، تاکہ میں اسے تباہ نہ کروں: لیکن مجھے کوئی نہ ملا۔\n31۔ اسی لیے میں نے ان پر اپنا غصہ بہا دیا ہے؛ میں نے انہیں اپنے غضب کی آگ سے جلا دیا ہے: میں نے ان کے اپنے طریقے سے ان کے سروں پر بدلہ دیا ہے، خداوند خدا فرماتا ہے۔","1۔ خداوند کا کلام دوبارہ میرے پاس آیا، کہتا ہے،\n2۔ بیٹے انسان، دو عورتیں تھیں، ایک ماں کی بیٹیاں:\n3۔ اور انہوں نے مصر میں بدکاری کی؛ انہوں نے اپنی جوانی میں بدکاری کی: ان کے سینے دبے ہوئے تھے، اور وہاں انہوں نے اپنی کنواری پن کے چھاتی کو زخمی کر دیا۔\n4۔ اور ان کے نام اہولا بزرگ اور اہولیبہ اس کی بہن تھے: اور وہ میرے تھے، اور ان کے بیٹے اور بیٹیاں تھیں۔ یوں ان کے نام تھے؛ سامریا {ہے} اہولا، اور یروشلم اہولیباہ۔ {آہولہ: یعنی، اس کا خیمہ یا، خیمہ خانہ} {اہولیبہ: یعنی، میرا خیمہ اس میں}\n5۔ اور اہولا نے جب میری تھی تو بدکار عورت بن گئی؛ اور وہ اپنے عاشقوں، آشوری (اپنے) پڑوسیوں پر پیار کرتی رہی،\n6۔ {جو} نیلے لباس میں ملبوس تھے، کپتان اور حکمران، سب پسندیدہ نوجوان، گھوڑوں پر سوار سوار تھے۔\n7۔ یوں اس نے اپنی بدکاری ان کے ساتھ کی، ان سب کے ساتھ جو آشور کے منتخب مرد تھے، اور ان سب کے ساتھ جن سے وہ محبت کرتی تھی، ان سب کے ساتھ اس نے خود کو ناپاک کیا۔ {کمیٹڈ...: ہیب۔ اپنی بدکاری ان پر عطا کی} {منتخب شدہ...: عبرانی۔ آشور کے بچوں کا انتخاب}\n8۔ اس نے اپنی فحاشی (جو مصر سے لائی تھی) نہیں چھوڑی، کیونکہ اس کی جوانی میں وہ اس کے ساتھ تھے، اور اس کی کنواری پن کے سینے زخمی کر دیے، اور اپنی بدکاری اس پر ڈال دی۔\n9۔ اسی لیے میں نے اسے اس کے عاشقوں کے ہاتھ میں دے دیا، آشوریوں کے ہاتھ میں، جن پر وہ محبت کرتی تھی۔\n10۔ ان لوگوں نے اس کی برہنگی دریافت کی: انہوں نے اس کے بیٹوں اور بیٹیوں کو لے کر تلوار سے قتل کر دیا؛ اور وہ عورتوں میں مشہور ہو گئی؛ کیونکہ انہوں نے اس پر فیصلہ سنایا تھا۔ {مشہور: عبوری۔ ایک نام}\n11۔ اور جب اس کی بہن اہولیبہ نے {یہ} دیکھا، تو وہ اپنی حد سے زیادہ محبت میں اور اپنی بدکاری میں اپنی بہن سے زیادہ بدکار ہو گئی۔ {وہ تھی...: عبرانی۔ اس نے اپنی غیر معمولی محبت کو اس سے بھی زیادہ خراب کیا، وغیرہ} {زیادہ...: عبرانی۔ اپنی بہن کی بدکاری سے بھی زیادہ}\n12۔ وہ آشوری کے پڑوسیوں، کپتانوں اور حکمرانوں پر بہت پیار کرتی تھی جو نہایت خوبصورت لباس میں ملبوس تھے، گھڑ سوار گھوڑوں پر سوار تھے، اور سب ہی پسندیدہ نوجوان تھے۔\n13۔ پھر میں نے دیکھا کہ وہ بے حرمتی کر چکی ہے، {کہ} انہوں نے دونوں کو ایک ہی طرف لے لیا،\n14۔ اور {یہ} اس نے اپنی بدکاری میں اضافہ کیا: کیونکہ جب اس نے دیوار پر مردوں کو دھوکہ دیا ہوا دیکھا، تو کلدانیوں کی تصویریں سرخی سے بھر گئیں،\n15۔ اپنی کمر پر بیلوں میں بندھے ہوئے، اپنے سروں پر رنگین لباس پہنے، سب شہزادے تھے جنہیں کلدیہ کے بابلیوں کی طرح اپنی پیدائش کی سرزمین پر دیکھنا ضروری تھا:\n16۔ اور جیسے ہی اس نے انہیں اپنی آنکھوں سے دیکھا، اس نے ان پر پیار کیا اور کلدیہ میں ان کے پاس قاصد بھیجے۔ {جیسے ہی...: عبرانی۔ اس کی آنکھوں کو دیکھ کر}\n17۔ اور بابلی اس کے پاس محبت کے بستر میں آئے، اور اپنی بدکاری سے اسے ناپاک کیا، اور وہ ان سے آلودہ ہو گئی، اور اس کا ذہن ان سے الگ ہو گیا۔ {بابلی: عبرانی۔ بابل کے بچے} {اجنبی شدہ: عبرانی۔ ڈھیلا، یا، بکھرہ}\n18۔ تو اس نے اپنی بدکاری دریافت کی، اور اپنی برہنگی کو دریافت کیا: پھر میرا ذہن اس سے الگ ہو گیا، جیسے میرا ذہن اس کی بہن سے الگ ہو گیا تھا۔\n19۔ پھر بھی اس نے اپنی بدکاری میں اضافہ کیا، اپنی جوانی کے دنوں کو یاد کرنے کے لیے، جب اس نے مصر کی سرزمین میں طوائف کا کردار ادا کیا تھا۔\n20۔ کیونکہ وہ اپنے محبوبوں پر بہت محبت کرتی تھی، جن کا گوشت گدھوں کے گوشت جیسا ہے، اور جن کی اولاد گھوڑوں کی اولاد کی طرح ہے۔\n21. اسی طرح تم نے اپنی جوانی کی بے حیائی کو یاد کرنے کی دعوت دی، جب تم نے اپنے جوانی کے پاپس کے لیے مصریوں کے ہاتھوں اپنے سینے کو زخمی کیا۔\n22. لہٰذا، اے اہولیبا، خداوند خدا یوں فرماتا ہے؛ دیکھو، میں تمہارے عاشقوں کو تمہارے خلاف اٹھاؤں گا، جن سے تمہارا ذہن الگ ہے، اور میں انہیں ہر طرف سے تمہارے خلاف لاؤں گا؛\n23۔ بابلی، اور تمام کلدانی، پیکوڈ، شوا، اور کوآ، {اور} تمام آشوری بھی ان کے ساتھ: یہ سب پسندیدہ نوجوان، کپتان اور حکمران، بڑے سردار اور مشہور تھے، سب گھوڑوں پر سوار تھے۔\n24۔ اور وہ تمہارے خلاف رتھوں، گاڑیوں اور پہیوں کے ساتھ آئیں گے، اور لوگوں کے ایک مجمع کے ساتھ، جو تمہارے خلاف بکلر، ڈھال اور ہیلمٹ لگا دیں گے، اور میں ان کے سامنے فیصلہ کروں گا، اور وہ تمہیں اپنے فیصلوں کے مطابق فیصلہ کریں گے۔\n25۔ اور میں اپنی حسد تم پر ڈالوں گا، اور وہ تم سے غصے میں ہوں گے: وہ تمہاری ناک اور کان چھین لیں گے؛ اور تمہاری باقیات تلوار کے ہاتھوں مارے جائیں گی: وہ تمہارے بیٹوں اور بیٹیوں کو لے جائیں گے؛ اور تمہاری باقیات آگ میں جل جائیں گی۔\n26۔ وہ تمہیں تمہارے کپڑے بھی اتاریں گے، اور تمہارے خوبصورت زیورات لے جائیں گے۔ {منصف...: عبدی۔ تمہاری سجاوٹ کے آلات}\n27۔ یوں میں تمہاری بے حیائی اور تمہاری فحاشی کو مصر کی سرزمین سے ختم کروں گا، تاکہ تم اپنی آنکھیں ان پر نہ اٹھاؤ، نہ مصر کو دوبارہ یاد رکھو۔\n28۔ کیونکہ خداوند خدا یہ فرماتا ہے؛ دیکھو، میں تمہیں ان کے ہاتھ میں دے دوں گا جنہیں تم چاہتے ہو، ان کے ہاتھ میں جن سے تمہارا ذہن الگ ہے:\n29۔ اور وہ تمہارے ساتھ نفرت سے پیش آئیں گے، تمہاری ساری محنت چھین لیں گے، اور تمہیں ننگا اور ننگا چھوڑ دیں گے: اور تمہاری فحاشی اور تمہاری بدکاری دونوں سامنے آ جائیں گے۔\n30۔ میں یہ سب تمہارے ساتھ کروں گا، کیونکہ تم نے کافروں کے پیچھے طوائف کیا ہے، اور اس لیے بھی کہ تم ان کے بتوں سے آلودہ ہو۔\n31۔ تو اپنی بہن کے راستے میں چلتی رہی؛ اسی لیے میں اس کا پیالہ تمہارے ہاتھ میں دوں گا۔\n32. خداوند خدا یہ فرماتا ہے؛ تم اپنی بہن کے پیالے سے گہرا اور بڑا پیو گے: تمہیں مذاق اڑایا جائے گا اور مذاق کیا جائے گا؛ اس میں بہت کچھ ہے۔\n33۔ تم نشے اور غم سے بھر جاؤ گے، حیرت اور ویرانی کے پیالے سے، اپنی بہن سامریا کے پیالے سے۔\n34۔ تم اسے پیو اور چوسنا، اور اس کے ٹکڑے توڑ دو، اور اپنے سینے بھی نوچ لو، کیونکہ میں نے کہا ہے، خداوند خدا فرماتا ہے۔\n35۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ کیونکہ تم نے مجھے بھلا دیا ہے، اور مجھے اپنی پیٹھ پیچھے چھوڑ دیا ہے، اس لیے اپنی فحاشی اور اپنی بدکاری بھی برداشت کرو۔\n36۔ خداوند نے مجھ سے مزید فرمایا؛ اے انسان کے بیٹے، کیا تم اہولا اور اہولیبہ کا فیصلہ کرو گے؟ ہاں، انہیں ان کی مکروہ حرکتوں کا اعلان کرو؛ {جج: یا، درخواست کریں}\n37۔ کہ انہوں نے کیا ہے، خون ان کے ہاتھوں میں ہے، اور اپنے بتوں کے ساتھ کیا ہے، اور اپنے بیٹوں کو، جنہیں انہوں نے میرے پاس پیدا کیا، انہیں آگ کے ذریعے لے جانے پر مجبور کیا ہے، تاکہ وہ انہیں کھا جائیں۔\n38۔ مزید یہ کہ انہوں نے میرے ساتھ کیا ہے: انہوں نے میرے مقدس مقام کو اسی دن ناپاک کیا ہے، اور میرے سبت کی بے حرمتی کی ہے۔\n39۔ کیونکہ جب انہوں نے اپنے بچوں کو ان کے بتوں کے لیے قتل کر دیا، تو اسی دن وہ میرے مقدس مقام میں آ کر اسے بے حرمتی کرنے آئے؛ اور، دیکھو، انہوں نے میرے گھر کے بیچ میں ایسا ہی کیا۔\n40۔ اور مزید یہ کہ تم نے دور سے لوگوں کو بلایا ہے، جن کے لیے ایک پیغام بھیجا گیا تھا؛ اور وہ آ گئے: جن کے لیے تم نے خود کو نہلایا، اپنی آنکھیں رنگیں، اور زیورات سے خود کو سجایا، {آنے والے: عبرانی آ رہا ہوں}\n41۔ اور ایک شاندار بستر پر، اور اس کے سامنے ایک میز پر بیٹھ جاؤ، جس پر تم نے میرا لوبان اور میرا تیل رکھا ہے۔ {باوقار: عبرانی۔ معزز\n42. اور ایک ہجوم کی آواز جو اس کے ساتھ مطمئن تھی: اور عام لوگوں کے ساتھ {تھے} نے سبین کو بیابان سے لایا، جنہوں نے اپنے ہاتھوں میں کنگن اور خوبصورت تاج سر پر پہنے۔ {میں سے...: عبرانی۔ انسانوں کی کثرت میں} {صابیوں: یا، نشے میں دھت لوگ}\n43۔ پھر میں نے اس سے کہا جو زنا میں بوڑھی تھی، کیا اب وہ اس کے ساتھ بدکاری کریں گے، اور وہ بھی ان کے ساتھ؟ {طوائف...: عبدی۔ اس کی بدکاری کے بارے میں}\n44۔ پھر بھی وہ اس کے پاس گئے، جیسے وہ ایک عورت کے پاس جاتے ہیں جو بدکار عورت ہے: اسی طرح وہ احولا اور اہولیبہ کے پاس گئے، جو فحش عورتیں تھیں۔\n45۔ اور نیک مرد، وہ انہیں کے طریقے اور خون بہانے والی عورتوں کے طریقے کے مطابق سزا دیں گے؛ کیونکہ وہ کرنے والی ہیں، اور خون ان کے ہاتھوں میں ہے۔\n46۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ میں ان پر ایک محفل لگاؤں گا، اور انہیں ہٹانے اور خراب کرنے کے لیے دے دوں گا۔ {ہونے والا...: عببرانی۔ ہٹانے اور خراب کرنے کے لیے}\n47۔ اور جماعت انہیں پتھروں سے مارے گی، اور تلواروں سے مار ڈالے گی؛ وہ اپنے بیٹوں اور بیٹیوں کو قتل کریں گے، اور اپنے گھروں کو آگ سے جلا دیں گے۔ {ڈسپیچ...: یا، انہیں الگ کر دو}\n48۔ یوں میں زمین سے فحاشی کو ختم کروں گا، تاکہ تمام عورتوں کو تمہاری بے حیائی کے بعد ایسا نہ کرنا سکھایا جائے۔\n49۔ اور وہ تمہاری بے حیائی کا بدلہ دیں گے، اور تم اپنے بتوں کے گناہ برداشت کرو گے: اور تم جان لو گے کہ میں خداوند خدا ہوں۔","1۔ پھر نویں سال، دسویں مہینے میں، مہینے کے دسویں دن، خداوند کا کلام میرے پاس آیا، جس میں کہا،\n2۔ اے انسان کے بیٹے، اسی دن کا نام لکھو: بابل کے بادشاہ نے اسی دن یروشلم کے خلاف جنگ کی۔\n3۔ اور باغی گھرانے کے لیے ایک تمثیل سناؤ، اور ان سے کہو، یہی فرماتا ہے خداوند خدا؛ ایک برتن پر رکھیں، {اسے} رکھیں، اور اس میں پانی بھی ڈالیں:\n4. اس کے ٹکڑے اس میں جمع کریں، {حتیٰ کہ} کہ ہر اچھا ٹکڑا، ران اور کندھا بھی؛ منتخب ہڈیوں سے {اسے} بھر دو۔\n5۔ ریوڑ کا انتخاب لو، اور اس کے نیچے کی ہڈیاں بھی جلا دو، {اور} اسے اچھی طرح ابالو، اور انہیں اس میں ہڈیاں اپنے دو۔ {جلنا: یا، ڈھیر}\n6۔ اسی لیے خداوند خدا فرماتا ہے؛ لعنت ہے اس خونریز شہر پر، اس برتن پر جس کی گندگی وہاں ہے، اور جس کی گندگی ابھی تک ختم نہیں ہوئی! اسے ٹکڑوں میں نکالیں؛ اس پر کوئی بوجھ نہ پڑے۔\n7۔ کیونکہ اس کا خون اس کے بیچ میں ہے؛ اس نے اسے ایک پتھر کی چوٹی پر رکھا؛ اس نے اسے زمین پر نہیں ڈالا، تاکہ اسے دھول سے ڈھانپ دے؛\n8۔ کہ اس سے انتقام لینے کے لیے غصہ آ جائے؛ میں نے اس کا خون ایک پتھر کی چوٹی پر رکھا ہے تاکہ اسے ڈھانپ نہ دیا جائے۔\n9۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ لعنت ہے اس خونخوار شہر پر! میں آگ کے لیے ڈھیر کو بھی بہترین بنا دوں گا۔\n10۔ لکڑی پر ڈھیر کرو، آگ جلاؤ، گوشت کو کھا لو، اچھی طرح مصالحہ دار کرو، اور ہڈیوں کو جلا دو۔\n11۔ پھر اسے اس کے کوئلوں پر خالی رکھ دو، تاکہ اس کا پیتل گرم ہو اور جل سکے، اور اس کی گندگی اس میں پگھل جائے، تاکہ اس کی گندگی کھا جائے۔\n12۔ اس نے جھوٹ سے خود کو تھکا دیا ہے، اور اس کی بڑی گندگی اس سے باہر نہیں نکلی: اس کی گندگی آگ میں ہوگی۔\n13۔ تمہاری گندگی میں فحش پن ہے: کیونکہ میں نے تمہیں پاک کیا ہے، اور تم پاک نہیں ہوئے، تم اپنی گندگی سے مزید پاک نہیں ہو جاؤ گے، جب تک میں اپنا غصہ تم پر نہ ڈال دوں۔\n14. میں، خداوند، نے کہا ہے: یہ ہو جائے گا، اور میں اسے کروں گا؛ میں واپس نہیں جاؤں گا، نہ بخشوں گا، نہ توبہ کروں گا؛ تمہارے طریقوں کے مطابق، اور تمہارے اعمال کے مطابق، وہ تمہارا فیصلہ کریں گے، خداوند خدا فرماتا ہے۔\n15۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا،\n16۔ اے انسان کے بیٹے، دیکھو، میں تیرے آنکھوں کی خواہش کو ایک جھٹکے سے چھین لیتا ہوں: پھر بھی نہ تم غم کرو گے، نہ رو گے، نہ تمہارے آنسو بہیں گے۔ {خلاصہ: عبوری۔ چلو}\n17۔ رونے سے باز رہو، مردوں کے لیے غم نہ کرو، اپنے سر کی تھکن اپنے اوپر باندھو، اور اپنے جوتے اپنے قدموں پر پہنو، اور اپنے ہونٹوں کو نہ ڈھانپو، اور انسانوں کی روٹی نہ کھاؤ۔ {فوربیئر: عبرانی۔ خاموش رہو} {ہونٹ: عبرانی۔ اوپر والا ہونٹ}\n18۔ تو میں نے صبح لوگوں سے کہا: اور یہاں تک کہ میری بیوی بھی فوت ہو گئی؛ اور میں نے صبح حکم کے مطابق کیا۔\n19۔ اور لوگوں نے مجھ سے کہا، کیا تم ہمیں نہیں بتاؤ گے کہ یہ {چیزیں} ہمارے لیے کیا ہیں، جو تم کر رہے ہو؟\n20۔ پھر میں نے ان کا جواب دیا، خداوند کا کلام میرے پاس آیا، اور کہا،\n21. اسرائیل کے گھر سے بات کرو، خداوند خدا یہ فرماتا ہے؛ دیکھو، میں اپنی پناہ گاہ، تمہاری طاقت کی عظمت، تمہاری آنکھوں کی خواہش، اور جس پر تمہاری روح ترس کھاتی ہے، بے حرمتی کروں گا؛ اور تمہارے بیٹے اور بیٹیاں جنہیں تم نے چھوڑا ہے، وہ تلوار کے ہاتھوں مارے جائیں گے۔ {وہ...: عببرانی۔ تمہاری روح کی ہمدردی}\n22۔ اور تم وہی کرو گے جو میں نے کیا ہے: تم اپنے ہونٹ نہیں ڈھانپو گے، نہ انسانوں کی روٹی کھاؤ گے۔\n23۔ اور تمہارے ٹائر تمہارے سروں پر ہوں گے، اور تمہارے جوتے تمہارے پیروں پر: تم نہ ماتم کرو گے نہ روؤ گے؛ لیکن تم اپنے گناہوں کے لیے ترس کرو گے، اور ایک دوسرے کے لیے ماتم کرو گے۔\n24. یوں حزقی ایل تمہارے لیے ایک نشانی ہے: جو کچھ اس نے کیا ہے اس کے مطابق تم کرو گے: اور جب یہ آئے گا، تم جان لو گے کہ میں خداوند خدا ہوں۔\n25. اور اے انسان کے بیٹے، {کیا یہ {ہوگا} اس دن جب میں ان سے ان کی طاقت، ان کی شان کی خوشی، ان کی آنکھوں کی خواہش، اور وہ چیز جو وہ اپنے ذہنوں، اپنے بیٹوں اور بیٹیوں کو رکھتے ہیں، چھین لوں گا، {کہ...: عبرانی۔ ان کی روح کو اٹھانا}\n26. {جو اس دن بچ نکلے} وہ تمہارے پاس آئے گا، تاکہ {تم} کو {تمہارے} کانوں سے سنے؟\n27۔ اس دن تمہارا منہ اس کے لیے کھلے گا جو بچ نکلا ہے، اور تم بولو گے، اور مزید گونگے نہیں بنو گے: اور تم ان کے لیے ایک نشانی بنو گے؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔","1۔ خداوند کا کلام دوبارہ میرے پاس آیا، کہتا ہے،\n2۔ اے انسان کے بیٹے، اپنا چہرہ عمونیوں کے خلاف رکھ دے، اور ان کے خلاف پیش گوئی کرو؛\n3۔ اور عمونیوں سے کہو، خداوند خدا کا کلام سنو؛ خداوند خدا یہ فرماتا ہے؛ کیونکہ تم نے کہا، آہا، میرے مقدس مقام کے خلاف، جب وہ بے حرمتی کی گئی؛ اور اسرائیل کی زمین کے خلاف، جب وہ ویران تھی؛ اور یہوداہ خاندان کے خلاف، جب وہ قید میں گئے؛\n4۔ دیکھو، میں تمہیں مشرق کے لوگوں کے پاس ملکیت کے طور پر پہنچاؤں گا، اور وہ اپنے محل تم میں قائم کریں گے، اور اپنے گھر تمہارے اندر بنائیں گے، وہ تمہارا پھل کھائیں گے، اور وہ تمہارا دودھ پیئیں گے۔ {مرد: عبرانی۔ بچے}\n5۔ اور میں ربا کو اونٹوں کے لیے اصطبل اور عمونیوں کو ریوڑوں کے لیے آرام گاہ بناؤں گا: اور تم جان لو گے کہ میں خداوند ہوں۔\n6۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ کیونکہ تم نے اپنے ہاتھوں پر تالیاں بجائیں، پاؤں سے پاؤں مارے، اور دل سے اپنی ساری بے باکی سے اسرائیل کی سرزمین پر خوشی منائی؛ {ہاتھ: عبرانی۔ ہاتھ} {پاؤں: عبرانی۔ پاؤں} {دل: عبرانی۔ روح}\n7۔ دیکھو، میں اپنا ہاتھ تم پر بڑھاؤں گا، اور تمہیں کافروں کے لیے لوٹ مار کے بدلے دوں گا؛ اور میں تمہیں لوگوں سے کاٹ دوں گا، اور تمہیں ملکوں سے نکال دوں گا: میں تمہیں تباہ کر دوں گا؛ اور تم جان لو گے کہ میں خداوند ہوں۔ {ایک لوٹ: یا، گوشت}\n8۔ خداوند خدا یہ فرماتا ہے؛ کیونکہ موآب اور سیر کہتے ہیں، دیکھو، یہوداہ کا گھر تمام کافروں جیسا ہے؛\n9۔ لہٰذا، دیکھو، میں موآب کے پہلو کو شہروں سے، اس کے شہروں {جو اس کی سرحدوں پر ہیں} سے ملک کی شان و شوکت کھولوں گا، بیت جیشیموت، بعلمیون اور کریاٹائم، {طرف...: عبرانی۔ موآب کا کندھا}\n10۔ مشرق کے لوگوں کو عمونیوں کے ساتھ، اور انہیں ملکیت میں دے دو تاکہ امونیوں کو قوموں میں یاد نہ رکھا جائے۔ {ساتھ...: یا، آمون کے بچوں کے خلاف}\n11۔ اور میں موآب پر فیصلے کروں گا؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔\n12. خداوند خدا یہ فرماتا ہے؛ کیونکہ ایڈوم نے یہوداہ خاندان کے خلاف انتقام لیا، اور ان سے بہت ناراض ہوا اور انتقام لیا؛ {بذریعہ...: عبرانی۔ انتقام لے کر}\n13۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ میں بھی اپنا ہاتھ ایڈوم پر بڑھاؤں گا، اور انسان اور جانور کو اس سے کاٹ دوں گا؛ اور میں اسے تیمان سے ویران کر دوں گا؛ اور ڈیدان کے وہ تلوار کے ہاتھوں مارے جائیں گے۔ {وہ...: یا، وہ تلوار کے ہاتھوں دیدان کے ہاتھوں گر جائیں گے}\n14۔ اور میں اپنے قوم اسرائیل کے ہاتھ سے ایڈم سے انتقام لوں گا: اور وہ ایڈوم میں میرے غصے اور غصے کے مطابق کریں گے؛ اور وہ میرے انتقام کو جان لیں گے، خداوند خدا فرماتا ہے۔\n15۔ خداوند خدا یہ فرماتا ہے؛ کیونکہ فلسطینیوں نے انتقام لیا ہے، اور انتقام دل سے لیا ہے، تاکہ پرانی نفرت کو تباہ کر سکیں؛ {لیے...: یا، ہمیشہ نفرت کے ساتھ}\n16۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ دیکھو، میں اپنا ہاتھ فلسطینیوں پر بڑھاؤں گا، اور میں چرتھیمز کو کاٹ دوں گا، اور سمندری ساحل کے باقیات کو تباہ کر دوں گا۔ {سمندری ساحل: یا، سمندر کا پناہ گاہ}\n17۔ اور میں ان پر شدید انتقام لوں گا اور شدید سرزنش کروں گا؛ اور وہ جان جائیں گے کہ میں خداوند ہوں، جب میں ان پر اپنا انتقام لوں گا۔ {عظیم انتقام: عبرانی۔ عظیم انتقام}","1۔ اور یہ گیارہویں سال میں، مہینے کے پہلے دن، {کہ} خداوند کا کلام میرے پاس آیا، جس نے کہا،\n2۔ اے انسان کے بیٹے، کیونکہ ٹائرس نے یروشلم کے خلاف کہا ہے، آہا، وہ لوگوں کے دروازے ٹوٹ چکی ہے: وہ میرے پاس ہے: میں دوبارہ توانائی حاصل کروں گا، {اب} وہ تباہ ہو چکی ہے:\n3۔ لہٰذا خداوند خدا فرماتا ہے؛ دیکھو، میں تمہارے خلاف ہوں، اے ٹائرس، اور بہت سی قوموں کو تمہارے خلاف لے آؤں گا، جیسے سمندر اپنی لہریں اٹھاتا ہے۔\n4۔ اور وہ ٹائرس کی دیواریں تباہ کر دیں گے، اور اس کے مینار گرا دیں گے: میں اس کی خاک بھی اس سے جھاڑ دوں گا، اور اسے چٹان کی چوٹی کی طرح بنا دوں گا۔\n5. یہ سمندر کے بیچ جال بچھانے کی جگہ ہوگی: کیونکہ میں نے کہا ہے، خداوند خدا فرماتا ہے: اور یہ قوموں کے لیے مال غنیمت بن جائے گا۔\n6۔ اور اس کی بیٹیاں جو میدان میں ہیں، تلوار سے مار دی جائیں گی؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔\n7۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ دیکھو، میں بابل کے بادشاہ ٹائرس نبوکدرز کو لے آؤں گا، جو شمال سے بادشاہوں کا بادشاہ تھا، گھوڑے، رتھوں کے ساتھ، گھڑ سواروں اور جماعتوں اور بہت سے لوگوں کے ساتھ۔\n8۔ وہ میدان میں تمہاری بیٹیوں کو تلوار سے مارے گا: اور تمہارے خلاف قلعہ بنائے گا، تمہارے خلاف ایک گھوڑا پھینکے گا، اور تمہارے خلاف بکلر اٹھائے گا۔ {cast...: یا، انجن آف شاٹ نکالو}\n9۔ اور وہ تمہاری دیواروں پر جنگ کے انجن لگائے گا، اور اپنی کلہاڑیوں سے تمہارے مینار توڑے گا۔\n10۔ اس کے گھوڑوں کی کثرت کی وجہ سے ان کی خاک تمہیں ڈھانپ دے گی: تمہاری دیواریں گھڑ سواروں کی آواز، پہیوں اور رتھوں کی آواز سے ہل جائیں گی، جب وہ تمہارے دروازوں میں داخل ہوگا، جیسے لوگ ایک ایسے شہر میں داخل ہوتے ہیں جہاں شگاف ہو جاتا ہے۔ {مردوں کے طور پر...: عبرانی۔ ایک ٹوٹے ہوئے شہر کے داخلے کے مطابق}\n11۔ وہ اپنے گھوڑوں کے کھروں سے تمہاری تمام گلیوں پر چلتا رہے گا: وہ تمہارے لوگوں کو تلوار سے مارے گا، اور تمہارے مضبوط دستے زمین پر گر جائیں گے۔\n12۔ اور وہ تمہاری دولت کا مال لوٹیں گے، تمہاری مال کا شکار بنائیں گے، اور تمہاری دیواریں توڑیں گے، تمہارے خوبصورت گھر تباہ کریں گے، اور تمہارے پتھر، لکڑی اور تمہاری خاک پانی کے بیچ میں رکھ دیں گے۔ {تمہاری خوشگواری...: عبرانی۔ تیری خواہش کے گھر}\n13۔ اور میں تمہارے گیتوں کی شور کو بند کر دوں گا؛ اور تمہارے ہارپ کی آواز اب نہیں سنی جائے گی۔\n14۔ اور میں تمہیں چٹان کی چوٹی کی طرح بنا دوں گا: تم جال بچھانے کی جگہ بنو گے؛ تم اب تعمیر نہیں ہو گے: کیونکہ میں خداوند نے کہا ہے {یہ}، خداوند فرماتا ہے۔\n15. خداوند خدا نے ٹائرس سے یوں فرمایا؛ کیا جزیرے تمہارے گرنے کی آواز پر نہیں ہلیں گے، جب زخمی چیخیں گے، جب تمہارے درمیان قتل عام ہوگا؟\n16۔ پھر سمندر کے تمام شہزادے اپنے تختوں سے نیچے آئیں گے، اپنے لباس اتاریں گے، اور اپنے کپڑے اتاریں گے: وہ کانپتے ہوئے لباس پہنیں گے؛ وہ زمین پر بیٹھیں گے، ہر لمحہ کانپیں گے، اور تم پر حیران ہوں گے۔ {کانپتے ہوئے: عبوری۔ کانپنا}\n17۔ اور وہ تمہارے لیے ایک نوحہ اٹھائیں گے، اور تم سے کہیں گے، تم کیسے تباہ ہو گئے ہو، {وہ ویسٹ} جو سمندری لوگوں سے آباد ہے، وہ مشہور شہر، جو سمندر میں مضبوط تھا، وہ اور اس کے باشندے، جو ہر اس شخص پر دہشت پیدا کرتے ہیں جو اسے پریشان کرتا ہے! {of...: عبرانی۔ سمندروں کا}\n18۔ اب جزیرے تمہارے زوال کے دن کانپیں گے؛ ہاں، وہ جزیرے جو سمندر میں ہیں، تمہارے روانگی پر پریشان ہوں گے۔\n19۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ جب میں تمہیں ویران شہر بنا دوں گا، جیسے وہ شہر جو آباد نہیں ہیں؛ جب میں تم پر گہرائی لے آؤں گا، اور عظیم پانی تمہیں ڈھانپ لے گا؛\n20۔ جب میں تمہیں ان لوگوں کے ساتھ جو گڑھے میں اترتے ہیں، پرانے زمانے کے لوگوں کے ساتھ نیچے لے جاؤں گا، اور تمہیں زمین کے نچلے حصے میں، پرانے ویران مقامات پر، ان لوگوں کے ساتھ رکھوں گا جو گڑھے میں اترتے ہیں، تاکہ تم آباد نہ رہو؛ اور میں زندہ لوگوں کی سرزمین میں جلال حاصل کروں گا؛\n21. میں تمہیں دہشت بنا دوں گا، اور تم {دوبارہ} نہیں بنو گے: چاہے تمہیں تلاش کیا جائے، پھر بھی تم دوبارہ کبھی نہیں پاؤ گے، خداوند خدا فرماتا ہے۔ {ایک دہشت: عبرانی۔ دہشتیں}","1۔ خداوند کا کلام دوبارہ میرے پاس آیا، کہتا ہے،\n2۔ اب، اے انسان کے بیٹے، ٹائرس کے لیے نوحہ کرو؛\n3۔ اور ٹائرس سے کہو، اے وہ جو سمندر کے داخلی راستے پر ہے، {جو لوگوں کے کئی جزیروں کے تاجر ہو}، خداوند خدا یہ فرماتا ہے؛ اے ٹائرس، تم نے کہا ہے، میں کامل خوبصورتی کا حامل ہوں۔ {کامل...: عبرانی۔ خوبصورتی کا کامل}\n4۔ تمہاری سرحدیں سمندروں کے بیچ میں ہیں، تمہارے معماروں نے تمہاری خوبصورتی کو مکمل کیا ہے۔ {درمیان: عبوری۔ دل}\n5. انہوں نے تمہارے تمام جہاز صنوبر کے درختوں سے بنائے ہیں: انہوں نے لبنان سے دیودار لے کر تمہارے لیے مستول بنائے ہیں۔ {بنایا: عبرانی۔ بنایا گیا}\n6. {Of} باشان کے بلوطوں نے تمہارے چپو بنائے ہیں؛ اشوریوں کی جماعت نے تمہارے بینچ ہاتھی دانت سے بنائے ہیں، {چتیم کے جزائر سے لائے ہیں}۔ {کمپنی...: یا، انہوں نے تمہارے ہاتھی دانت کے دروازے اچھی طرح پاؤں رکھ دیے ہیں} {کمپنی: ہیب۔ بیٹی}\n7۔ مصر سے نفیس کتان اور کٹے ہوئے کپڑے وہ تھے جو تم پھیلاتے ہو تاکہ تمہارا بادبان بن سکے؛ الیشع کے جزائر سے نیلا اور جامنی وہ تھا جو تمہیں ڈھانپ رہا تھا۔ {نیلا...: یا، جامنی اور سرخ رنگ}\n8۔ زیدون اور ارواد کے باشندے تیرے ملاح تھے: تیرے عقلمند، اے ٹائرس، جو تیرے میں تھے، تیرے پائلٹ تھے۔\n9۔ جبل کے قدیم اور اس کے دانا تمہارے اندر تھے: سمندر کے تمام جہاز اپنے ملاحوں کے ساتھ تمہارے سامان پر قبضہ کرنے کے لیے تھے۔ {کیلکرز: یا، چینیوں کے اسٹاپرز: عبرانی۔ مضبوط کرنے والے وغیرہ}\n10۔ فارس، لود اور فوٹ کے وہ تمہاری فوج میں تھے، تیرے جنگی آدمی: انہوں نے تمہارے اندر ڈھال اور خود لٹکایا؛ وہ تمہاری خوبصورتی بیان کرتے ہیں۔\n11۔ آرواد کے لوگ تمہاری فوج کے ساتھ تمہاری دیواروں کے ارد گرد تھے، اور گامادیمز تمہارے میناروں میں تھے: انہوں نے اپنے ڈھالیں تمہاری دیواروں پر لٹکا دی تھیں؛ انہوں نے تیری خوبصورتی کو کامل بنایا ہے۔\n12۔ ترشیش تمہارا تاجر تھا کیونکہ اس کے پاس تمام {قسم} کی دولت کی کثرت تھی؛ چاندی، لوہا، ٹن اور سیسہ کے ساتھ، وہ تمہارے میلے میں تجارت کرتے تھے۔\n13۔ جاوان، طبل، اور میشخ، وہ تمہارے تاجر تھے: وہ تمہارے بازار میں انسانوں اور برتنوں کے پیتل کے برتنوں کی تجارت کرتے تھے۔ {مارکیٹ: یا، مرچنڈائز}\n14۔ توگارما کے گھرانے کے لوگ تمہارے میلے میں گھوڑوں، گھڑ سواروں اور خچروں کے ساتھ تجارت کرتے تھے۔\n15۔ ڈیدان کے لوگ تمہارے تاجر تھے؛ کئی جزیرے تمہارے ہاتھ کی چیز تھے: انہوں نے تمہیں ہاتھی دانت اور کالا کے سینگ دیے۔\n16۔ شام تمہارا تاجر تھا کیونکہ تمہاری بنائی ہوئی اشیاء کی کثرت تھی: وہ تمہارے میلے میں زمرد، جامنی اور چوٹی کے کام، عمدہ کتان، مرجان اور عقیق میں مصروف تھے۔ {دی ویئرز...: عبوری۔ تیری اعمال} {اگیت: اور، کرسوپراس}\n17۔ یہودا، اور اسرائیل کی زمین، وہ تمہارے تاجر تھے: وہ تمہارے بازار میں منیتھ اور پناگ کی گندم، شہد، تیل، اور مرہم کی تجارت کرتے تھے۔ {مرہم: یا، روزن}\n18. دمشق تمہاری بنائی ہوئی اشیاء کی کثرت میں تمہارا تاجر تھا، تمام دولت کی کثرت کے لیے؛ ہیلبون کی شراب میں، اور سفید اون میں۔\n19۔ دان اور جاوان بھی تمہارے میلوں میں آتے جاتے رہے: چمکدار لوہا، کاسیا، اور کلامس تمہارے بازار میں تھے۔ {جا رہا ہے...: یا، میزال}\n20. دیدان تمہارا تاجر تھا قیمتی کپڑوں میں رتھ کے لیے۔ {قیمتی...: عبرانی۔ آزادی کے کپڑے}\n21۔ عرب، اور کیدار کے تمام شہزادے، وہ تمہارے ساتھ بھیڑوں، مینڈوں اور بکریوں میں مصروف تھے: ان میں وہ تمہارے تاجر تھے۔ {انہوں نے قبضہ کیا...: عبدی۔ وہ تیرے ہاتھ کے تاجر تھے}\n22۔ سبا اور راماہ کے تاجر، وہ تمہارے تاجر تھے: وہ تمہارے میلے میں تمام مصالحہ جات کے سردار، تمام قیمتی پتھروں اور سونے میں مصروف تھے۔\n23۔ ہاران، کنہ، اور عدن، سبا کے تاجر، اشور، {اور} چلمد، {تھے} تمہارے تاجر۔\n24۔ یہ آپ کے تاجر تھے، ہر قسم کی چیزوں میں، نیلے کپڑوں میں، چوٹی کے کپڑے پہنے ہوئے، اور قیمتی لباس کے صندوقوں میں، جو رسیوں سے بندھے ہوئے اور دیودار کے بنے ہوئے تھے، آپ کے سامان میں۔ {سب...: یا، بہترین چیزیں} {کپڑے: عبوری۔ فولڈنگز}\n25۔ ترشیش کے جہازوں نے تمہارے بازار میں تمہاری یاد میں گایا: اور تم دوبارہ بھر گئے، اور سمندروں کے بیچ میں بہت شان دار بن گئے۔\n26۔ تمہارے چپو چلانے والوں نے تمہیں عظیم پانیوں میں لے آیا ہے: مشرقی ہوا نے تمہیں سمندروں کے بیچ میں توڑ دیا ہے۔ {درمیان: عبوری۔ دل}\n27. تمہاری دولت، تمہاری خوبصورتی، تمہاری مال، تمہارے ملاح، تمہارے ملاح، تمہارے چلنے والے، تمہارے سامان کے قابض، اور تمہارے تمام جنگی سپاہی، جو تمہارے اندر ہیں، اور تمہارے تمام ساتھیوں میں جو تمہارے درمیان ہیں، تمہاری تباہی کے دن سمندروں کے بیچ میں گر جائیں گے۔ {اور میں...: یا، یہاں تک کہ سب کے ساتھ} {سمندروں کے درمیان: عبرانی۔ دل، وغیرہ}\n28. مضافات تمہارے پائلٹس کی پکار کی آواز پر لرز اٹھیں گے۔ {مضافات: یا، لہریں}\n29۔ اور جو بھی چپو سنبھالے گا، ملاح، {اور} سمندر کے تمام پائلٹ، اپنے جہازوں سے نیچے آئیں گے، وہ زمین پر کھڑے ہوں گے؛\n30۔ اور ان کی آواز تمہارے خلاف سنائی دے گا، اور تلخ آواز میں پکارے گا، اور ان کے سروں پر مٹی ڈالے گا، وہ خود کو راکھ میں ڈوبا دیں گے:\n31۔ اور وہ آپ کے لیے خود کو مکمل طور پر گنجا بنا لیں گے، انہیں تھیلے کے کپڑے سے لپیٹیں گے، اور وہ آپ کے لیے دل کی تلخی اور تلخ رونے کے ساتھ روئیں گے۔\n32۔ اور اپنی رونے میں وہ تمہارے لیے نوحہ اٹھائیں گے، اور تمہارے لیے ماتم کریں گے، {کہیں}، کون سا شہر ہے جو ٹائرس جیسا ہے، جیسے سمندر کے بیچ میں تباہ ہو جائے؟\n33۔ جب تمہارا سامان سمندر سے باہر نکلا، تو تم نے بہت سے لوگوں کو بھر دیا؛ تم نے زمین کے بادشاہوں کو اپنی دولت اور اپنی تجارت کی فراوانی سے مالا مال کیا۔\n34۔ جب {جب} تم سمندر سے ٹوٹ جاؤ گے، پانیوں کی گہرائیوں میں، تمہارا سامان اور تمہاری تمام ساتھی تمہارے درمیان گر جائیں گے۔\n35۔ جزائر کے تمام باشندے تم پر حیران ہوں گے، اور ان کے بادشاہ خوفزدہ ہوں گے، وہ اپنے چہرے سے پریشان ہوں گے۔\n36۔ لوگوں کے تاجر تم پر پھونکیں گے؛ تم ایک دہشت بنو گے، اور کبھی نہیں رہو گے۔ {ایک دہشت: عبرانی۔ دہشتیں} {کبھی نہیں...: عبوری۔ یہ ہمیشہ کے لیے نہیں رہے گا}","1۔ خداوند کا کلام دوبارہ میرے پاس آیا، کہتا ہے،\n2۔ اے انسان کے بیٹے، ٹائرس کے شہزادے سے فرماو، خداوند خدا یہ فرماتا ہے؛ کیونکہ تمہارا دل بلند ہو گیا ہے، اور تم نے کہا، میں خدا ہوں، میں خدا کی نشست پر بیٹھتا ہوں، سمندروں کے بیچ؛ پھر بھی تم انسان ہو، خدا نہیں، چاہے تم اپنا دل خدا کے دل کی طرح رکھو: {درمیان: عبرانی۔ دل}\n3۔ دیکھو، تو دانیال سے زیادہ دانا ہو؛ کوئی راز نہیں جو وہ تم سے چھپا سکیں:\n4۔ اپنی حکمت اور سمجھ بوجھ سے تم نے دولت حاصل کی، اور سونا اور چاندی اپنے خزانے میں شامل کی:\n5۔ اپنی عظیم حکمت سے {اور} اپنی تجارت سے تم نے اپنی دولت میں اضافہ کیا، اور تمہارا دل اپنی دولت کی وجہ سے بلند ہوا: {تمہاری عظیم...: عبرانی۔ تیری حکمت کی عظمت}\n6۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ کیونکہ تم نے اپنے دل کو خدا کا دل بنا دیا ہے؛\n7۔ دیکھو، اس لیے میں اجنبی لوگوں کو تم پر لاؤں گا، قوموں میں سے خوفناک، اور وہ تیری حکمت کی خوبصورتی کے خلاف اپنی تلواریں نکالیں گے، اور وہ تیری روشنی کو آلودہ کریں گے۔\n8۔ وہ تمہیں گڑھے میں لے جائیں گے، اور تم ان کی موت مرو گے جو سمندروں کے بیچ مارے گئے ہیں۔\n9. کیا تم اس کے سامنے کہو گے جو تمہیں مارتا ہے، میں خدا ہوں؟ لیکن تم انسان بنو گے، اور کوئی خدا نہیں، اس کے ہاتھ میں جو تمہیں مارے گا۔ {جو قتل کرتا ہے: یا جو زخمی کرتا ہے}\n10۔ تم غیر ختنہ شدہ لوگوں کی موت اجنبیوں کے ہاتھوں مرو گے: کیونکہ میں نے کہا ہے، خداوند خدا فرماتا ہے۔\n11۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا،\n12۔ اے انسان کے بیٹے، ٹائرس کے بادشاہ پر نوحہ اٹھا اور اس سے کہو، خداوند خدا یہ فرماتا ہے؛ تو مجموعہ کو مہر بند کرتا ہے، جو حکمت سے بھرپور اور خوبصورتی میں کامل ہے۔\n13۔ تم جنت میں خدا کے باغ میں تھے؛ ہر قیمتی پتھر تمہاری چادر تھی، سارڈیئس، ٹوپاز، ہیرا، بیریل، اونکس، جاسپر، نیلم، زمرد، اور کاربنکل، اور سونا: تمہارے ٹیبریٹس اور پائپوں کی کاریگری تم میں اس دن تیار کی گئی جب تم پیدا ہوئے۔ {سارڈیئس: یا، روبی} {بیریل: یا، کرائسولائٹ} {ایمرلڈ: یا، کرسوپراس}\n14۔ تو وہ مسح شدہ فرشتہ ہو جو ڈھانپتا ہے؛ اور میں نے تمہیں {یوں} مقرر کیا ہے: تو خدا کے مقدس پہاڑ پر تھا؛ تم آگ کے پتھروں کے درمیان اوپر نیچے چلتے رہے ہو۔\n15۔ تم نے اپنی راہوں میں اس دن سے مکمل قیام کیا جب سے تم پیدا ہوئے، جب تک کہ تم میں بدکاری نہ ہو گئی۔\n16۔ تمہارے مال کی کثرت سے انہوں نے تمہارے درمیان کو تشدد سے بھر دیا ہے، اور تم نے گناہ کیا ہے: اس لیے میں تمہیں خدا کے پہاڑ سے بے حرمتی کے طور پر نکال دوں گا: اور میں تمہیں تباہ کر دوں گا، اے پردہ کرنے والے فرشتہ، آگ کے پتھروں کے بیچ سے۔\n17۔ تمہارا دل تمہاری خوبصورتی کی وجہ سے بلند ہوا، تو نے اپنی حکمت کو اپنی روشنی کی وجہ سے خراب کر دیا: میں تمہیں زمین پر گرا دوں گا، میں تمہیں بادشاہوں کے سامنے رکھوں گا، تاکہ وہ تمہیں دیکھ سکیں۔\n18۔ تو نے اپنی گناہوں کی کثرت سے، اپنی تجارت کی گناہوں سے اپنے مقدس مقامات کو ناپاک کیا ہے؛ اسی لیے میں تمہارے بیچ سے آگ نکالوں گا، جو تمہیں نگل جائے گی، اور تمہیں زمین پر راکھ بنا دوں گا ان سب کے سامنے جو تمہیں دیکھتے ہیں۔\n19۔ جو لوگ تمہیں لوگوں میں جانتے ہیں وہ تم پر حیران رہ جائیں گے: تم خوفناک بنو گے، اور کبھی دوبارہ نہیں رہو گے۔ {ایک دہشت: عبرانی۔ دہشتیں}\n20. پھر خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n21۔ اے انسان کے بیٹے، اپنی چہرہ زدون کے خلاف رکھ دو، اور اس کے خلاف نبوت کرو،\n22۔ اور فرمایا، خداوند خدا یہ فرماتا ہے؛ دیکھو، میں تیرے خلاف ہوں، اے زیدون؛ اور میں تمہارے درمیان جلال پاؤں گا: اور وہ جان جائیں گے کہ میں خداوند ہوں، جب میں اس پر فیصلے کروں گا اور اس میں پاک ہوں گا۔\n23۔ کیونکہ میں اس میں وبا بھیجوں گا، اور خون اس کی گلیوں میں؛ اور زخمی کو اس کے بیچ میں ہر طرف تلوار سے پرکھا جائے گا؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔\n24۔ اور اب اسرائیل کے گھر کے لیے کوئی چبھتا ہوا کانٹا نہیں ہوگا، نہ ہی ان سب میں سے کوئی افسردہ کانٹا جو ان کے ارد گرد ہیں، جنہوں نے انہیں حقیر سمجھا؛ اور وہ جان جائیں گے کہ میں خداوند خدا ہوں۔\n25. خداوند خدا یہ فرماتا ہے؛ جب میں اسرائیل کے گھر کو ان لوگوں سے جمع کروں گا جن میں وہ بکھرے ہوئے ہیں، اور ان میں غیر مسلموں کی نظر میں پاک ہوں گے، تب وہ اپنے اس زمین میں بسیں گے جو میں نے اپنے خادم یعقوب کو دی ہے۔\n26۔ اور وہ وہاں محفوظ رہیں گے، گھر بنائیں گے، اور انگور کے باغات لگائیں گے؛ ہاں، وہ اعتماد کے ساتھ رہیں گے، جب میں ان سب پر فیصلے کر لوں گا جو ان کے ارد گرد نفرت کرتے ہیں؛ اور وہ جان جائیں گے کہ میں ان کا خداوند خدا ہوں۔ {محفوظ: یا، اعتماد کے ساتھ} {نفرت ہے: یا، خراب}","1۔ دسویں سال، دسویں مہینے میں، مہینے کے بارہویں دن میں، خداوند کا کلام میرے پاس آیا، جس میں کہا،\n2۔ اے انسان کے بیٹے، اپنا چہرہ مصر کے بادشاہ فرعون کے خلاف رکھ دو، اور اس کے خلاف اور پورے مصر کے خلاف نبوت کرو:\n3۔ بولو، اور کاؤ، خداوند خدا یہی فرماتا ہے؛ دیکھو، میں تمہارے خلاف ہوں، مصر کے بادشاہ فرعون، وہ عظیم اژدہا جو اس کی ندیوں کے بیچ میں پڑا ہے، جس نے کہا، میرا دریا {ہے} میرا ہے، اور میں نے اسے اپنے لیے بنایا ہے۔\n4۔ لیکن میں تمہارے جبڑوں میں کانٹے لگا دوں گا، اور تمہارے دریاؤں کی مچھلی کو تمہارے ترازو سے چپکاؤں گا، اور تمہیں تمہارے دریاؤں کے درمیان سے نکالوں گا، اور تمہارے دریاؤں کی تمام مچھلیاں تمہارے ترازو سے چپک جائیں گی۔\n5۔ اور میں تمہیں اور تمہارے دریا کی تمام مچھلیوں کو بیابان میں چھوڑ دوں گا: تم کھلے میدانوں پر گر جاؤ گے؛ تمہیں اکٹھا نہیں کیا جائے گا، نہ ہی جمع کیا جائے گا: میں نے تمہیں کھیت کے جانوروں اور آسمان کے پرندوں کے لیے گوشت کے طور پر دیا ہے۔ {کھولو...: عبرانی۔ میدان کا چہرہ}\n6۔ اور مصر کے تمام باشندے جان لیں گے کہ میں خداوند ہوں، کیونکہ وہ اسرائیل کے گھر کے لیے سرکنڈے کی چھڑی رہے ہیں۔\n7۔ جب انہوں نے تمہیں تمہارے ہاتھ سے پکڑ لیا، تو تم ٹوٹ گئے اور ان کے سارے کندھے پھاڑ دیے؛ اور جب وہ تم پر جھکے، تو تم نے توڑ دیا، اور ان سب کی کمر کو پاگل کر کے کھڑا کر دیا۔\n8۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ دیکھو، میں تم پر تلوار لاؤں گا، اور انسان اور جانور کو تمہارے اندر سے کاٹ دوں گا۔\n9۔ اور مصر کی زمین ویران اور ویران ہو جائے گی؛ اور وہ جان جائیں گے کہ میں خداوند ہوں: کیونکہ اس نے کہا، دریا میرا ہے، اور میں نے اسے بنایا ہے۔\n10۔ دیکھو، اس لیے میں تمہارے خلاف ہوں، اور تمہارے دریاؤں کے خلاف، اور میں مصر کی زمین کو مکمل طور پر ویران کر دوں گا، سیینے کے مینار سے لے کر ایتھوپیا کی سرحد تک۔ {بالکل...: عبوری۔ فضلہ کے فضلے} {سے...: یا، میگدول سے سیینے تک} {سیینی: عبرانی۔ سیونے}\n11۔ انسان کا کوئی پاؤں اس سے نہیں گزرے گا، نہ جانور کا پاؤں اس سے گزرے گا، اور نہ ہی چالیس سال تک آباد ہوگا۔\n12۔ اور میں مصر کی سرزمین کو ان ملکوں کے درمیان ویران بنا دوں گا جو ویران ہیں، اور اس کے شہروں میں سے جو تباہ ہو چکے ہیں، چالیس سال تک ویران ہو جائیں گے: اور میں مصریوں کو قوموں میں بکھیر دوں گا، اور انہیں ملکوں میں بکھیر دوں گا۔\n13۔ پھر بھی خداوند خدا یہ فرماتا ہے؛ چالیس سال کے آخر میں میں ان لوگوں سے مصریوں کو جمع کروں گا جہاں وہ بکھرے ہوئے تھے:\n14۔ اور میں مصر کی قید دوبارہ لاؤں گا، اور انہیں پاتھروس کی سرزمین میں واپس لے جاؤں گا، ان کی رہائش کی زمین میں؛ اور وہ وہاں ایک پست بادشاہت ہوں گے۔ {رہائش گاہ: یا، پیدائش} {بنیاد: عبوری۔ کم}\n15۔ یہ بادشاہتوں میں سب سے نچلے درجے کی ہوگی؛ نہ ہی وہ قوموں سے زیادہ بلند ہو جائے گا: کیونکہ میں انہیں نیچا دوں گا تاکہ وہ قوموں پر حکمرانی نہ کر سکیں۔\n16۔ اور یہ اب اسرائیل کے گھر کا اعتماد نہیں رہے گا، جو ان کی گناہوں کو یاد کرے گا، جب وہ ان کا خیال رکھیں گے: بلکہ وہ جان جائیں گے کہ میں خداوند خدا ہوں۔\n17۔ اور یہ سات اور بیسویں سال میں ہوا، پہلے مہینے میں، مہینے کے پہلے {دن} میں، خداوند کا کلام میرے پاس آیا، جس نے کہا،\n18۔ انسان کا بیٹا، بابل کے بادشاہ نبوکدرز نے اپنی فوج کو ٹائرس کے خلاف عظیم خدمت کے لیے بھیجا: ہر سر گنجا ہو گیا، اور ہر کندھا اتار دیا گیا، لیکن اس کے پاس ٹائرس کے لیے کوئی اجرت یا فوج نہیں تھی، اس خدمت کے بدلے جو اس نے اس کے خلاف کی تھی:\n19۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ دیکھو، میں مصر کی سرزمین بابل کے بادشاہ نبوکدرززار کو دوں گا؛ اور وہ اس کی کثرت لے گا، اس کا مال لے گا، اور اس کا شکار لے گا؛ اور یہ اس کی فوج کی اجرت ہوگی۔ {اس کی خوبصورتی لے لو...: ہیب۔ اس کا مال لوٹ لو، اور شکار کو شکار کرو}\n20. میں نے اسے مصر کی زمین دی ہے {اس کی محنت کے بدلے} جس سے اس نے اس کے خلاف خدمت کی، کیونکہ انہوں نے میرے لیے کام کیا، خداوند خدا فرماتا ہے۔ {اپنے...: یا، اس کی ملازمت کے لیے}\n21. اسی دن میں اسرائیل کے گھر کے سینگ کو پھوٹوں گا، اور تمہیں ان کے درمیان منہ کھولوں گا؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔","1۔ خداوند کا کلام دوبارہ میرے پاس آیا، کہتا ہے،\n2۔ انسان کے بیٹے، پیش گوئی کرو اور کہو، خداوند خدا یہ فرماتا ہے؛ ہاؤل اے یو، آج کے لیے افسوس!\n3۔ کیونکہ دن {قریب} ہے، حتیٰ کہ خداوند کا دن {ہے} قریب ہے، ایک ابر آلود دن؛ یہ کافروں کا وقت ہوگا۔\n4۔ اور تلوار مصر پر آئے گی، اور ایتھوپیا میں شدید درد ہوگا، جب شہید مصر میں گریں گے، اور وہ اس کی اکثریت کو چھین لیں گے، اور اس کی بنیادیں ٹوٹ جائیں گی۔ {درد: یا، خوف}\n5۔ ایتھوپیا، لیبیا، لیدیا، اور تمام مخلوط لوگ، اور چوب، اور اس سرزمین کے لوگ جو اتحاد میں ہیں، ان کے ساتھ تلوار کے ہاتھوں مارے جائیں گے۔ {لیبیا: عبرانی۔ پھٹ} {مرد: عبرانی۔ بچے}\n6۔ خداوند یہ فرماتا ہے؛ جو مصر کی حمایت کرتے ہیں وہ بھی گر جائیں گے؛ اور اس کی طاقت کا غرور نیچے آئے گا: سیینے کے مینار سے وہ تلوار کے ذریعے اس میں گریں گے، خداوند خدا فرماتا ہے۔ {سے...: یا، میگڈول سے سیینے تک}\n7۔ اور وہ ویران ملکوں کے درمیان ویران ہو جائیں گے، اور اس کے شہر ان شہروں کے درمیان ہوں گے جو تباہ ہو چکے ہیں۔\n8۔ اور وہ جان جائیں گے کہ میں خداوند ہوں، جب میں مصر میں آگ لگاؤں گا، اور {جب} اس کے تمام مددگار تباہ ہو جائیں گے۔ {تباہ شدہ: عبرانی۔ ٹوٹا ہوا}\n9۔ اس دن میرے ساتھ سے قاصد جہازوں میں نکلیں گے تاکہ لاپرواہ ایتھوپیائیوں کو خوفزدہ کریں، اور ان پر شدید تکلیف آئے گی، جیسا کہ مصر کے دن میں ہوا تھا: کیونکہ وہ آ رہا ہے۔\n10۔ خداوند خدا یہ فرماتا ہے؛ میں مصر کی ہجوم کو بابل کے بادشاہ نبوکدرزار کے ہاتھوں روک دوں گا۔\n11۔ وہ اور اس کے لوگ، جو قوموں میں سے خوفناک ہیں، زمین کو تباہ کرنے کے لیے لائے جائیں گے: اور وہ مصر کے خلاف اپنی تلواریں نکالیں گے، اور زمین کو مارے جانے والوں سے بھر دیں گے۔\n12۔ اور میں دریاؤں کو خشک کروں گا، اور زمین کو بدکاروں کے ہاتھ بیچ دوں گا: اور میں زمین اور اس میں موجود سب کچھ اجنبیوں کے ہاتھوں تباہ کر دوں گا: میں خداوند نے کہا ہے۔ {خشک: عبوری۔ خشک سالی} {سب...: عبرانی۔ اس کی مکمل شدت}\n13۔ خداوند خدا یہ فرماتا ہے؛ میں بتوں کو بھی تباہ کر دوں گا، اور ان کی تصاویر کو نوف سے ختم کر دوں گا؛ اور اب مصر کی سرزمین کا کوئی شہزادہ نہیں رہے گا: اور میں مصر کی سرزمین میں خوف پیدا کروں گا۔\n14۔ اور میں پاتھرو کو ویران کر دوں گا، زوآن میں آگ لگاؤں گا، اور نمبر {زوان: یا، تانس}\n15۔ اور میں اپنا غصہ گناہ پر ڈالوں گا، مصر کی طاقت پر؛ اور میں نمبر کی تعداد کو کاٹ دوں گا۔ {گناہ: یا، پیلوسیم}\n16۔ اور میں مصر میں آگ لگاؤں گا: گناہ کو شدید درد ہوگا، اور کوئی چیر نہیں پائے گا، اور نوف روزانہ تکلیفوں کا سامنا کرے گا۔\n17۔ ایون اور پیبیسیتھ کے نوجوان تلوار کے ہاتھوں مارے جائیں گے: اور یہ {شہر} قید میں چلے جائیں گے۔ {ایون: یا، ہیلیوپولس} {پیبیسیتھ: یا، پباسٹم}\n18۔ تہافنیحس میں بھی وہ دن تاریک ہو جائے گا، جب میں وہاں مصر کے جولے توڑوں گا: اور اس کی طاقت کی شان و شوکت اس میں ختم ہو جائے گی، اور اس پر بادل چھا جائے گا، اور اس کی بیٹیاں قید میں چلی جائیں گی۔ {تاریک: یا، محدود}\n19۔ یوں میں مصر میں فیصلے کروں گا: اور وہ جان جائیں گے کہ میں خداوند ہوں۔\n20۔ اور یہ گیارہویں سال میں ہوا، پہلے {مہینہ} میں، مہینے کے ساتویں {دن} میں، {کہ} خداوند کا کلام میرے پاس آیا، جس میں کہا،\n21. اے انسان کے بیٹے، میں نے مصر کے بادشاہ فرعون کا بازو توڑ دیا ہے؛ اور، دیکھو، اسے شفا دینے کے لیے بندھا نہیں جائے گا، اسے باندھنے کے لیے رولر نہیں رکھا جائے گا، اسے تلوار پکڑنے کے لیے مضبوط نہیں بنایا جائے گا۔\n22. لہٰذا خداوند خدا یہ فرماتا ہے؛ دیکھو، میں مصر کے بادشاہ فرعون کے خلاف ہوں، اور اس کے بازو توڑ دوں گا، طاقتور اور جو ٹوٹا ہوا تھا؛ اور میں تلوار کو اس کے ہاتھ سے گرا دوں گا۔\n23۔ اور میں مصریوں کو قوموں میں بکھیر دوں گا، اور انہیں ملکوں میں منتشر کر دوں گا۔\n24۔ اور میں بابل کے بادشاہ کے بازو مضبوط کروں گا، اور اپنی تلوار اس کے ہاتھ میں رکھوں گا: لیکن میں فرعون کے بازو توڑ دوں گا، اور وہ اس کے سامنے ایک مہلک زخمی {آدمی} کی کراہوں کے ساتھ کراہ رہا ہوگا۔\n25۔ لیکن میں بابل کے بادشاہ کے بازوؤں کو مضبوط کروں گا، اور فرعون کے بازو گر جائیں گے؛ اور وہ جان جائیں گے کہ میں خداوند ہوں، جب میں اپنی تلوار بابل کے بادشاہ کے ہاتھ میں رکھوں گا، اور وہ اسے مصر کی سرزمین پر پھیلائے گا۔\n26۔ اور میں مصریوں کو قوموں میں بکھیر دوں گا، اور انہیں ملکوں میں منتشر کر دوں گا؛ اور وہ جان جائیں گے کہ میں خداوند ہوں۔","1۔ اور یہ گیارہویں سال، تیسرے مہینے میں، مہینے کے پہلے دن میں ہوا، {کہ} خداوند کا کلام میرے پاس آیا، اور کہا،\n2. اے انسان کے بیٹے، مصر کے بادشاہ فرعون سے اور اس کی جماعت سے بات کرو؛ تم اپنی عظمت میں کس کی طرح ہو؟\n3۔ دیکھو، آشوری لبنان میں ایک دیودار تھا جس کی شاخیں خوبصورت تھیں، کفن سایہ دار تھا، اور وہ بلند قامت کا حامل تھا؛ اور اس کا ٹاپ موٹی شاخوں میں تھا۔ {خوبصورت شاخوں کے ساتھ: عبرانی۔ شاخوں کا میلہ}\n4۔ پانی نے اسے عظیم بنایا، گہرائی نے اسے اونچائی پر کھڑا کیا جہاں اس کے پودوں کے ارد گرد دریا بہتے تھے، اور اپنے چھوٹے دریا کھیت کے تمام درختوں تک بھیجتے تھے۔ {بنایا...: یا، اسے پالیا} {سیٹ...: یا، اس کا ذکر کیا} {چھوٹے دریا: یا، کنڈوئٹس}\n5۔ اس لیے اس کی قد کھیت کے تمام درختوں سے بلند تھی، اس کی شاخیں بڑھ گئیں، اور جب وہ نکلا تو اس کی شاخیں پانی کی کثرت کی وجہ سے لمبی ہو گئیں۔ {جب...: یا، جب اس نے انہیں بھیجا}\n6۔ آسمان کے تمام پرندوں نے اس کی شاخوں میں اپنے گھونسلے بنائے، اور اس کی شاخوں کے نیچے میدان کے تمام جانوروں نے اپنے بچے پیدا کیے، اور اس کے سائے تلے تمام عظیم قومیں رہتی تھیں۔\n7۔ یوں وہ اپنی عظمت میں خوبصورت تھا، اپنی شاخوں کی لمبائی میں: کیونکہ اس کی جڑ بڑے پانیوں سے تھی۔\n8۔ خدا کے باغ میں دیودار اسے چھپا نہیں سکتے تھے: فر کے درخت اس کی شاخوں جیسے نہیں تھے، اور شطرنج کے درخت اس کی شاخوں جیسے نہیں تھے؛ نہ ہی خدا کے باغ میں کوئی درخت اس کی خوبصورتی میں اس جیسا تھا۔\n9۔ میں نے اسے اس کی شاخوں کی کثرت سے خوبصورت بنایا ہے: یہاں تک کہ عدن کے تمام درخت، جو خدا کے باغ میں تھے، اس سے حسد کرتے تھے۔\n10۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ کیونکہ تم نے اپنی اونچائی میں خود کو بلند کیا، اور اس نے اپنی چوٹی موٹی شاخوں کے درمیان اٹھائی، اور اس کا دل اس کی اونچائی میں بلند ہوا؛\n11۔ لہٰذا میں نے اسے کافروں کے طاقتور کے ہاتھ میں دے دیا ہے؛ وہ ضرور اس سے نمٹے گا: میں نے اسے اس کی برائی کی وجہ سے نکال دیا ہے۔ {وہ...: عبرانی۔ ایسا کرتے ہوئے وہ اس کے ساتھ کرے گا}\n12۔ اور اجنبیوں نے، قوموں کے خوفناک لوگوں نے اسے کاٹ دیا ہے اور چھوڑ دیا ہے: پہاڑوں اور تمام وادیوں میں اس کی شاخیں گر چکی ہیں، اور اس کی شاخیں زمین کے تمام دریاؤں سے ٹوٹ گئی ہیں؛ اور زمین کے تمام لوگ اس کے سائے سے نیچے جا چکے ہیں، اور اسے چھوڑ چکے ہیں۔\n13۔ اس کی تباہی کے بعد آسمان کے تمام پرندے باقی رہیں گے، اور میدان کے تمام جانور اس کی شاخوں پر ہوں گے:\n14۔ اس مقصد کے لیے کہ پانی کے کنارے موجود تمام درختوں میں سے کوئی بھی اپنی اونچائی کے لیے بلند نہ ہو، نہ اپنی چوٹی پر گھنے شاخوں کے درمیان اچھلے، نہ ہی ان کے درخت اپنی اونچائی پر کھڑے ہوں، جو پانی پیتے ہیں: کیونکہ وہ سب موت کے لیے چھوڑ دیے گئے ہیں، زمین کے نچلے حصوں میں، انسانوں کے بچوں کے درمیان،  ان کے ساتھ جو گڑھے میں جاتے ہیں۔ {ان کے درخت...: یا، اپنی اونچائی کے لیے خود پر کھڑے ہوتے ہیں}\n15۔ خداوند خدا یہ فرماتا ہے؛ جس دن وہ قبر کے پاس گیا تو میں نے سوگ منایا: میں نے اس کے لیے گہرائی کو ڈھانپ دیا، اور اس کے سیلاب کو روکا، اور عظیم پانی رک گئے: اور میں نے لبنان کو اس کے لیے سوگ منایا، اور میدان کے تمام درخت اس کے لیے بے ہوش ہو گئے۔ {سوگ منانے کے لیے: عبرانی۔ سیاہ فام ہونے کے لیے}\n16. میں نے قوموں کو اس کے گرنے کی آواز پر ہلا دیا، جب میں نے اسے ان لوگوں کے ساتھ جہنم میں پھینک دیا جو گڑھے میں اترتے ہیں: اور عدن کے تمام درخت، لبنان کے منتخب اور بہترین، جو پانی پیتے ہیں، زمین کے نچلے حصوں میں تسلی پائیں گے۔\n17۔ وہ بھی اس کے ساتھ جہنم میں گئے تاکہ {جو لوگ ہوں} تلوار سے مارے گئے؛ اور {وہ لوگ} جو اس کے بازو تھے، {جو} اس کے سائے تلے کافروں کے درمیان رہتے تھے۔\n18. عدن کے درختوں میں تم کس کی شان و شوکت اور عظمت میں اس طرح ہو؟ پھر بھی تم عدن کے درختوں کے ساتھ زمین کے نچلے حصے میں لائے جاؤ گے: تم ختنہ شدہ لوگوں کے درمیان لیٹو گے، ان کے ساتھ جو تلوار سے مارے گئے ہیں۔ یہ {ہے} فرعون اور اس کے تمام لوگ، خداوند خدا فرماتا ہے۔","1۔ اور یہ بارہویں سال، بارہویں مہینے میں، مہینے کے پہلے دن میں ہوا، {کہ} خداوند کا کلام میرے پاس آیا، کہتا ہے،\n2۔ اے انسان کے بیٹے، مصر کے بادشاہ فرعون کے لیے ایک نوحہ اٹھا کر اسے کہو، تو قوموں کے نوجوان شیر کی مانند ہو، اور تم سمندروں میں وہیل کی طرح ہو، اور تو اپنے دریا لے کر آئے، اپنے قدموں سے پانیوں کو تنگ کیا، اور ان کی ندیوں کو گندا کیا۔ {وہیل: یا، ڈریگن}\n3۔ خداوند خدا یہ فرماتا ہے؛ لہٰذا میں اپنے جال کو تیرے اوپر پھیلاؤں گا اور بہت سے لوگوں کے ساتھ بھی؛ اور وہ تمہیں میرے جال میں لائیں گے۔\n4۔ پھر میں تمہیں زمین پر چھوڑ دوں گا، تمہیں کھلے میدان میں پھینک دوں گا، اور آسمان کے تمام پرندوں کو تم پر چھوڑ دوں گا، اور زمین کے تمام جانوروں کو تم سے بھر دوں گا۔\n5۔ اور میں تمہارا جسم پہاڑوں پر رکھوں گا، اور وادیوں کو تیری بلندی سے بھر دوں گا۔\n6۔ میں تیری خون سے اس زمین کو بھی سیراب کروں گا جس میں تم تیرتے ہو، {حتیٰ کہ} پہاڑوں تک؛ اور دریا تم سے بھر جائیں گے۔ {وہ زمین جس میں...: یا، تیری تیرنے کی زمین}\n7۔ اور جب میں تمہیں باہر نکالوں گا، تو میں آسمان کو ڈھانپ دوں گا، اور اس کے ستاروں کو تاریک کر دوں گا؛ میں سورج کو بادل سے ڈھانپ دوں گا، اور چاند اسے روشنی نہیں دے گا۔ {رکھو...: یا، تمہیں بجھا دو}\n8۔ آسمان کی تمام روشن روشنیوں کو میں تم پر تاریک کر دوں گا، اور تیری زمین پر تاریکی ڈالوں گا، خداوند خدا فرماتا ہے۔ {روشن...: عبرانی۔ آسمان میں روشنی کی روشنی} {تاریک: عبرانی۔ وہ ڈارک}\n9۔ میں بہت سے لوگوں کے دلوں کو بھی چبھاؤں گا، جب میں قوموں میں تمہاری تباہی لاؤں گا، ان ملکوں میں جنہیں تم نہیں جانتے۔ {وکس: عبرانی۔ غصہ یا غم کو بھڑکانا}\n10۔ ہاں، میں بہت سے لوگوں کو تم پر حیران کر دوں گا، اور ان کے بادشاہ تمہارے لیے خوفزدہ ہوں گے، جب میں ان کے سامنے اپنی تلوار لہرا دوں گا؛ اور وہ ہر لمحہ کانپیں گے، ہر آدمی اپنی جان کے لیے، تمہارے زوال کے دن۔\n11۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ بابل کے بادشاہ کی تلوار تم پر آئے گی۔\n12۔ طاقتوروں کی تلواروں سے میں تمہاری ہجوم کو گرا دوں گا، قوموں میں سے خوفناک سب کو، اور وہ مصر کی شان و شوکت کو برباد کریں گے، اور اس کی تمام کثرت تباہ ہو جائے گی۔\n13۔ میں اس کے تمام جانوروں کو بھی عظیم پانیوں کے کنارے سے تباہ کر دوں گا؛ نہ انسان کے پاؤں انہیں مزید پریشان کریں گے، نہ ہی جانوروں کے کھر انہیں پریشان کریں گے۔\n14۔ پھر میں ان کے پانی کو گہرا کر دوں گا، اور ان کی ندیاں تیل کی طرح بہاؤں گا، خداوند خدا فرماتا ہے۔\n15۔ جب میں مصر کی سرزمین کو ویران کر دوں گا، اور ملک اس چیز سے محروم ہو جائے گا جس سے وہ مکمل تھا، جب میں وہاں رہنے والوں کو شکست دوں گا، تب وہ جان جائیں گے کہ میں خداوند ہوں۔ {بے سہاری...: عبدی۔ اس کی مکمل ہونے سے ویران\n16. یہ وہ نوحہ ہے جس سے وہ اس پر ماتم کریں گے: قوموں کی بیٹیاں اس کے لیے ماتم کریں گی: وہ اس کے لیے ماتم کریں گی، یہاں تک کہ مصر کے لیے بھی، اور اس کی ساری کثرت کے لیے، خداوند خدا فرماتا ہے۔\n17۔ یہ بارہویں سال، مہینے کے پندرہویں دن میں بھی ہوا کہ خداوند کا کلام میرے پاس آیا، جس میں کہا،\n18۔ اے انسان کے بیٹے، مصر کی اکثریت کے لیے رو، اور انہیں بھی، اور مشہور قوموں کی بیٹیوں کو زمین کے نچلے حصے میں پھینک دو، ان کے ساتھ جو گڑھے میں جاتی ہیں۔\n19۔ خوبصورتی میں تم کس سے گزرتے ہو؟ نیچے جاؤ، اور ختنہ نہ ہونے والوں کے ساتھ بستر پر رہو۔\n20۔ وہ تلوار سے مارے جانے والوں کے درمیان گریں گے: اسے تلوار کے حوالے کر دیا جائے گا: اسے اور اس کے تمام ہجوم کو کھینچ لو۔ {وہ...: یا، تلوار رکھی گئی ہے}\n21. طاقتور لوگ جہنم کے بیچ سے ان لوگوں کے ساتھ اس سے بات کریں گے جو اس کی مدد کریں گے: وہ نیچے جا چکے ہیں، بغیر ختنہ کے پڑے ہیں، تلوار سے مارے گئے ہیں۔\n22۔ اشور وہاں ہے اور اس کے تمام ساتھی: اس کی قبریں اس کے گرد ہیں: سب مارے گئے، تلوار سے مارے گئے:\n23۔ جس کی قبریں گڑھے کے کناروں میں رکھی گئی ہیں، اور اس کی جماعت اس کی قبر کے گرد ہے: سب مارے گئے، تلوار سے گرے، جس نے زندہ لوگوں کی دنیا میں خوف پھیلایا۔ {دہشت: یا، افسوسناک}\n24۔ وہاں ایلام اور اس کی تمام قوم اس کی قبر کے گرد ہے، سب مارے گئے، تلوار سے گرے ہوئے، جو بغیر ختنہ کیے زمین کے نچلے حصے میں چلے گئے، جس نے زندہ زمین میں ان کا خوف پیدا کیا؛ پھر بھی انہوں نے اپنی شرمندگی ان لوگوں کے ساتھ اٹھائی ہے جو گڑھے میں جاتے ہیں۔\n25۔ انہوں نے اسے مقتولوں کے درمیان ایک بستر رکھا ہے اور اس کی پوری تعداد بھی: اس کی قبریں اس کے ارد گرد ہیں: سب غیر ختنہ شدہ ہیں، تلوار سے مارے گئے: اگرچہ ان کا خوف زندہ لوگوں کی سرزمین میں تھا، پھر بھی انہوں نے ان لوگوں کے ساتھ شرمندگی اٹھائی جو گڑھے میں جاتے ہیں:  اسے {ان لوگوں کے بیچ میں رکھا جاتا ہے جو مارے جاتے ہیں}۔\n26. یہاں مشخ، توبال، اور اس کی ساری ہجوم ہے: اس کی قبریں اس کے ارد گرد ہیں: سب غیر ختنہ شدہ ہیں، تلوار سے مارے گئے، حالانکہ انہوں نے زندہ لوگوں کی دنیا میں خوف پھیلایا۔\n27۔ اور وہ ان طاقتور لوگوں کے ساتھ نہیں سوٹے جائیں گے جو ختنہ شدہ کے ہاتھوں سے مارا گیا ہے، جو اپنے جنگی ہتھیاروں کے ساتھ جہنم میں چلے جاتے ہیں: اور انہوں نے اپنی تلواریں سر کے نیچے رکھ دی ہیں، لیکن ان کے گناہوں پر ان کی ہڈیوں پر ہوں گے، اگرچہ وہ زندہ زمین میں طاقتوروں کا خوف تھے۔ {ان کے...: عبرانی کے ساتھ۔ اپنی جنگ کے ہتھیاروں کے ساتھ}\n28۔ ہاں، تم ختنہ شدہ لوگوں کے درمیان ٹوٹ جاؤ گے، اور ان کے ساتھ لیٹو گے جو تلوار سے مارے گئے ہیں۔\n29۔ یہاں ادم، اس کے بادشاہ اور اس کے تمام شہزادے ہیں، جنہیں ان کی طاقت سے {ان لوگوں نے} تلوار سے مارے جو مارے گئے: وہ ختنہ نہ شدہ کے ساتھ اور ان کے ساتھ جو گڑھے میں جائیں گے۔ {لیڈ: عببرانی۔ دیا گیا، یا، لکھتا ہے}\n30۔ وہاں شمال کے شہزادے ہیں، سب اور تمام زیدونیان، جو مارے جانے والوں کے ساتھ نیچے چلے گئے؛ اپنے خوف سے وہ اپنی طاقت پر شرمندہ ہیں؛ اور وہ بغیر ختنہ کے (جو تلوار سے مارے گئے) کے ساتھ لیٹے ہیں، اور اپنی شرمندگی ان لوگوں کے ساتھ اٹھاتے ہیں جو گڑھے میں جاتے ہیں۔\n31۔ فرعون انہیں دیکھے گا، اور اپنے تمام ہجوم پر تسلی پائے گا، حتیٰ کہ فرعون اور اس کی تمام فوج تلوار سے مارے گئے، خداوند خدا فرماتا ہے۔\n32۔ کیونکہ میں نے اپنی دہشت زندہ زمین میں پیدا کی ہے: اور وہ ختنہ نہ ہونے والوں کے درمیان {ان لوگوں کے ساتھ جو تلوار سے مارے گئے ہیں} کے درمیان دفن کیا جائے گا، {حتیٰ کہ} فرعون اور اس کی تمام ہمواریوں کے ساتھ، خداوند خدا فرماتا ہے۔","1۔ پھر خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، اپنے لوگوں سے بات کر، اور انہیں کہو، جب میں تلوار کسی زمین پر لاؤں، اگر اس ملک کے لوگ اپنے ساحلوں کے کسی آدمی کو لے کر اسے اپنا محافظ مقرر کریں: {جب...: عبرانی۔ ایک زمین جب میں اس پر تلوار لاؤں گا}\n3۔ اگر وہ دیکھے کہ تلوار زمین پر آتی ہے، تو وہ بگل بجاتا ہے اور لوگوں کو خبردار کرتا ہے؛\n4۔ پھر جو بگل کی آواز سنتا ہے اور خبردار نہیں ہوتا؛ اگر تلوار آئے اور اسے لے جائے، تو اس کا خون اس کے اپنے سر پر ہوگا۔ {جو بھی...: عبرانی جو سنتا ہے}\n5۔ اس نے ترمپٹ کی آواز سنی، اور خبردار نہیں ہوا؛ اس کا خون اس پر ہوگا۔ لیکن جو خبردار کرے گا وہ اپنی جان کو نجات دے گا۔\n6۔ لیکن اگر چوکیدار تلوار کو آتے دیکھے، اور بگل نہ بجائے، اور لوگوں کو خبردار نہ کیا جائے؛ اگر تلوار آئے اور ان میں سے کوئی شخص لے جائے، تو وہ اپنی غلطی میں لے لیا جاتا ہے؛ لیکن اس کا خون مجھے چوکیدار کے ہاتھوں چاہیے ہوگا۔\n7۔ تو تو، اے انسان کے بیٹے، میں نے تمہیں اسرائیل کے گھر پر پہرہ دینے والا مقرر کیا ہے؛ اسی لیے تم میرے منہ سے لفظ سنو گے، اور انہیں مجھ سے خبردار کرو گے۔\n8۔ جب میں بدکاروں سے کہوں، اے بدکار {انسان}، تو تم ضرور مر جاؤ گے؛ اگر تم بدکاروں کو اس کے راستے سے خبردار کرنے کے لیے بات نہ کرو تو وہ بدکار {انسان} اپنی بدکاری میں مر جائے گا؛ لیکن اس کا خون مجھے تمہارے ہاتھ میں چاہیے۔\n9. پھر بھی، اگر تم بدکاروں کو اس کے راستے سے منہ موڑنے کی تنبیہ کرو؛ اگر وہ اپنے راستے سے نہ ہٹے تو وہ اپنی گناہی میں مر جائے گا؛ لیکن تم نے اپنی جان بچا لی ہے۔\n10. لہٰذا، اے انسان کے بیٹے، اسرائیل کے گھر سے بات کرو؛ یوں آپ کہتے ہیں، اگر ہمارے گناہ اور گناہ ہم پر ہوں اور ہم ان میں تڑپ رہے ہوں، تو پھر ہم کیسے جییں؟\n11۔ ان سے کہو، {جیسا کہ میں زندہ ہوں}، خداوند خدا فرماتا ہے، مجھے بدکاروں کی موت میں کوئی خوشی نہیں؛ بلکہ کہ بدکار اپنے راستے سے منہ موڑ کر زندہ رہے: تم اپنے برے راستوں سے منہ موڑ لو؛ کیونکہ تم کیوں مرو گے، اے اسرائیل کے گھر؟\n12۔ لہٰذا، اے انسان کے بیٹے، اپنے قوم کے بچوں سے کہو، نیک لوگوں کی راستبازی اسے اس کی گناہ کے دن نجات نہیں دے سکتی؛ اور بدکاروں کی بدکاری اس دن نہیں گرے گی جب وہ اپنی بدکاری سے پلٹ جائے گا؛ نہ ہی نیک لوگ اس دن اپنی {راستبازی} کے لیے جی سکیں گے جب وہ گناہ کرے گا۔\n13۔ جب میں نیک لوگوں سے کہوں گا، {کہ} وہ ضرور زندہ رہے گا؛ اگر وہ اپنی راستبازی پر بھروسہ کرے اور بدکاری کرے تو اس کی تمام نیکی یاد نہیں رکھی جائے گی؛ لیکن اس نے جو گناہ کیا ہے اس کی وجہ سے وہ مر جائے گا۔\n14. پھر جب میں بدکاروں سے کہوں، تو ضرور مر جاؤ گے؛ اگر وہ اپنے گناہ سے منہ موڑ لے، اور جو جائز اور درست ہے وہ کرے؛ {وہ...: عببرانی۔ فیصلہ اور انصاف}\n15۔ {اگر} بدکار نے وعدہ بحال کر دیا، تو جو لوٹا تھا اسے دوبارہ دے دے، زندگی کے قوانین میں چلو، بغیر کوئی گناہ کیے؛ وہ ضرور زندہ رہے گا، وہ نہیں مرے گا۔\n16۔ اس کے کیے گئے گناہوں میں سے کوئی بھی اس کے سامنے ذکر نہیں کیا جائے گا: اس نے وہ کیا ہے جو جائز اور درست ہے؛ وہ ضرور زندہ رہے گا۔\n17۔ پھر بھی تمہارے لوگوں کے بچے کہتے ہیں، خداوند کا راستہ برابر نہیں: لیکن ان کا راستہ برابر نہیں۔\n18۔ جب نیک اپنی راستبازی سے منہ موڑ کر گناہ کرے گا، تو وہ اسی وجہ سے مر جائے گا۔\n19۔ لیکن اگر بدکار اپنی برائی سے منہ موڑ لے اور جو جائز اور درست ہے وہ کرے گا، تو وہ اسی کے مطابق زندہ رہے گا۔\n20. پھر بھی تم کہتے ہو، خداوند کا راستہ برابر نہیں۔ اے اسرائیل کے گھرانہ، میں تم سب کو اس کے طریقوں کے مطابق فیصلہ کروں گا۔\n21۔ اور یہ ہمارے قید کے بارہویں سال میں ہوا، دسویں مہینے میں، مہینے کے پانچویں دن، وہ جو یروشلم سے فرار ہوا تھا میرے پاس آیا اور کہا، شہر تباہ ہو گیا ہے۔\n22۔ اب خداوند کا ہاتھ شام کو میرے اوپر تھا، اس سے پہلے کہ جو بچ گیا تھا وہ آ جائے؛ اور میں نے منہ کھولا، یہاں تک کہ وہ صبح میرے پاس آیا؛ اور میرا منہ کھل گیا، اور میں مزید بے وقوف نہیں رہا۔\n23۔ پھر خداوند کا کلام میرے پاس آیا، جس نے کہا،\n24۔ اے انسان کے بیٹے، جو لوگ اسرائیل کی سرزمین کے ان ویران علاقوں میں رہتے ہیں وہ کہتے ہیں، کہتے ہیں: ابراہیم ایک تھا، اور اس نے زمین کا وارث پایا: لیکن ہم بہت ہیں؛ زمین ہمیں وراثت کے لیے دی گئی ہے۔\n25۔ لہٰذا ان سے فرماو، خداوند خدا یہ فرماتا ہے؛ تم خون سے کھاتے ہو، اپنی نظریں اپنے بتوں کی طرف اٹھاتے ہو، اور خون بہاتے ہو: اور کیا تم زمین پر قبضہ کرو گے؟\n26۔ تم اپنی تلوار پر کھڑے ہو، گناہ کرتے ہو، اور ہر ایک کو اس کے پڑوسی کی بیوی کو ناپاک کرتے ہو: اور کیا تم زمین پر قبضہ کرو گے؟\n27. تو انہیں یوں کہو، خداوند خدا یہی فرماتا ہے؛ {As} میں زندہ ہوں، یقینا جو لوگ ویرانوں میں ہیں وہ تلوار سے مارا جائے گا، اور جو کھلے میدان میں ہے اسے میں ان جانوروں کو دوں گا جو کھا جائیں گے، اور جو قلعوں اور غاروں میں ہوں گے وہ وبا سے مر جائیں گے۔ {ہونے والا...: عببرانی۔ اسے نگلنے کے لیے}\n28۔ کیونکہ میں زمین کو سب سے ویران کر دوں گا، اور اس کی طاقت کی شان و شوکت ختم ہو جائے گی؛ اور اسرائیل کے پہاڑ ویران ہو جائیں گے، کہ کوئی گزر نہ سکے۔ {زیادہ تر...: عبرانی۔ ویرانی اور ویرانی}\n29۔ تب وہ جان جائیں گے کہ میں خداوند ہوں، جب میں نے زمین کو ان تمام گناہوں کی وجہ سے ویران کر دیا ہے جو انہوں نے کی ہیں۔\n30۔ اسی طرح، اے انسان کے بیٹے، تیری قوم کے بچے اب بھی دیواروں اور گھروں کے دروازوں پر تیرے خلاف بات کر رہے ہیں، اور ایک دوسرے سے، ہر ایک اپنے بھائی سے بات کر رہے ہیں، کہہ رہے ہیں، آؤ، میں تم سے دعا کرتا ہوں، اور وہ کلام سنو جو خداوند کی طرف سے نکلا ہے۔ {تمہارے خلاف: تمہارے بارے میں}\n31۔ اور وہ تمہارے پاس آتے ہیں جیسے لوگ آتے ہیں، اور وہ تمہارے سامنے بیٹھتے ہیں {بطور} میرے لوگ، اور وہ تمہارے الفاظ سنتے ہیں، لیکن وہ انہیں نہیں مانتے، کیونکہ وہ اپنے منہ سے بہت محبت ظاہر کرتے ہیں، {لیکن} ان کا دل ان کی لالچ کے پیچھے جاتا ہے۔ {جیسا کہ...: عبرانی۔ لوگوں کی آمد کے مطابق} {وہ بیٹھتے ہیں...: یا، میرے لوگ تیرے سامنے بیٹھتے ہیں} {وہ دکھاتے ہیں...: عبرانی۔ وہ محبت کرتے ہیں، یا، مذاق کرتے ہیں}\n32۔ اور دیکھو، تم ان کے لیے ایک بہت خوبصورت گیت کی طرح ہو جس کی آواز خوشگوار ہے، اور جو ساز پر اچھی طرح بجا سکتا ہے: کیونکہ وہ تمہارے الفاظ سنتے ہیں، لیکن وہ نہیں کرتے۔ {ایک بہت...: عبرانی۔ محبت کا گانا}\n33۔ اور جب یہ واقعہ ہوگا، (ہاں، یہ ہوگا)، تب وہ جان جائیں گے کہ ان میں ایک نبی تھا۔","1۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، اسرائیل کے چرواہوں کے خلاف نبوت کرو، پیش گوئی کر، اور ان سے کہو، خداوند خدا چرواہوں سے یوں فرماتا ہے؛ ہائے اللہ ان چرواہوں پر جو خود کو کھانا کھلاتے ہیں! کیا چرواہوں کو ریوڑوں کو کھلانا نہیں چاہیے؟\n3۔ تم چربی کھاتے ہو، اور خود کو اون سے ملبوس کرتے ہو، اور جنہیں کھایا جاتا ہے انہیں قتل کرتے ہو: {لیکن} تم ریوڑ کو نہیں کھلاتے۔\n4۔ تم نے بیماروں کو مضبوط نہیں کیا، نہ بیمار کو شفا دی، نہ ہی جو ٹوٹا ہوا تھا اسے باندھا، نہ ہی وہ چیز واپس لائی جو دور کی گئی تھی، نہ ہی کھوئی ہوئی چیز کی تلاش کی؛ لیکن تم نے طاقت اور ظلم کے ساتھ ان پر حکومت کی۔\n5۔ اور وہ بکھر گئے، کیونکہ {کوئی چرواہا} نہیں ہے: اور جب وہ بکھرے ہوئے تو وہ تمام کھیتوں کے جانوروں کے لیے گوشت بن گئے۔ {کیونکہ...: یا، بغیر چرواہے کے}\n6۔ میری بھیڑیں تمام پہاڑوں اور ہر اونچی پہاڑی پر گھومتی رہیں: ہاں، میرا ریوڑ زمین کے کنارے بکھرا ہوا تھا، اور کسی نے ان کی تلاش یا تلاش نہیں کی۔\n7۔ لہٰذا، اے چرواہوں، خداوند کا کلام سنو؛\n8. {جیسا کہ} میں زندہ ہوں، خداوند خدا فرماتا ہے، یقینا اس لیے کہ میرا ریوڑ شکار بن گیا، اور میرا ریوڑ ہر کھیت کے جانور کا گوشت بن گیا، کیونکہ {وہاں کوئی چرواہا نہیں تھا}، نہ میرے چرواہوں نے میرے ریوڑ کی تلاش کی، بلکہ چرواہوں نے خود کو کھلایا، اور میرے ریوڑ کو نہیں کھلایا؛ {کیونکہ...: یا، بغیر چرواہے کے}\n9۔ لہٰذا، اے چرواہوں، خداوند کا کلام سنو؛\n10۔ خداوند خدا یہ فرماتا ہے؛ دیکھو، میں چرواہوں کے خلاف ہوں؛ اور میں اپنے ریوڑ کو ان کے ہاتھ میں لاؤں گا، اور انہیں ریوڑ کو کھلانے سے روک دوں گا؛ نہ ہی چرواہے اب خود کو کھانا کھائیں گے؛ کیونکہ میں اپنے ریوڑ کو ان کے منہ سے نکال دوں گا، تاکہ وہ ان کے لیے گوشت نہ ہوں۔\n11۔ کیونکہ خداوند خدا ایسا فرماتا ہے؛ دیکھو، میں، {حتیٰ کہ} میں بھی، اپنی بھیڑوں کو تلاش کروں گا اور انہیں تلاش کروں گا۔\n12۔ جیسے چرواہا اپنے ریوڑ کو اس دن تلاش کرتا ہے جب وہ اپنی بھیڑوں میں بکھری ہوئی ہے؛ اسی طرح میں اپنی بھیڑوں کو تلاش کروں گا، اور انہیں ان تمام جگہوں سے نکالوں گا جہاں وہ ابر آلود اور تاریک دن میں بکھرے ہوئے ہیں۔ {یعنی...: عبرانی۔ تلاش کے مطابق}\n13۔ اور میں انہیں لوگوں سے نکالوں گا، اور ملکوں سے جمع کروں گا، اور ان کی سرزمین پر لے جاؤں گا، اور انہیں اسرائیل کے پہاڑوں پر دریاؤں کے کنارے اور ملک کے تمام آباد مقامات پر کھلاؤں گا۔\n14۔ میں انہیں اچھے چراگاہ میں کھلاؤں گا، اور اسرائیل کے بلند پہاڑوں پر ان کی چھٹی ہوگی: وہاں وہ اچھی جگہ میں لیٹیں گے، اور اسرائیل کے پہاڑوں پر موٹے چراگاہ میں کھلائیں گے۔\n15. میں اپنے ریوڑ کو کھلاؤں گا، اور انہیں سلا دوں گا، خداوند خدا فرماتا ہے۔\n16۔ میں کھوئی ہوئی چیزوں کو تلاش کروں گا، اور جو واپس لائے گئے تھے، اور جو ٹوٹا ہوا تھا اسے باندھ دوں گا، اور بیمار کو مضبوط کروں گا: لیکن میں موٹے اور طاقتور کو تباہ کر دوں گا؛ میں انہیں فیصلے کے ساتھ کھلاؤں گا۔\n17. اور {جہاں تک} تمہاری بات ہے، اے میرے ریوڑ، خداوند خدا یہ فرماتا ہے؛ دیکھو، میں مویشیوں اور مویشیوں کے درمیان، مینڈھے اور بکریوں کے درمیان فیصلہ کرتا ہوں۔ {مویشی: عبرانی۔ چھوٹے مویشی جو بھیڑ اور بچوں کا ہے} {وہ بکری بناتا ہے: عبرانی۔ زبردست بکریاں ہیں}\n18. {کیا یہ تمہارے لیے چھوٹی بات لگتی ہے} کہ تم نے اچھی چراگاہ کھا لی، لیکن تمہیں اپنے چراگاہوں کے باقیات کو اپنے قدموں سے چلنا ہوگا؟ اور گہرے پانیوں سے پینا، لیکن تمہیں اپنے پیروں سے باقیات کو گندا کرنا ہوگا؟\n19۔ اور {جہاں تک} میرے ریوڑ کا تعلق ہے، وہ وہ کھاتے ہیں جو تم نے اپنے قدموں سے چلایا ہے؛ اور وہ وہ پیتے ہیں جو تم نے اپنے پیروں سے گندا کیا ہے۔\n20۔ لہٰذا خداوند خدا ان سے یوں فرماتا ہے؛ دیکھو، میں، {حتیٰ کہ} میں بھی، موٹے مویشیوں اور دبلی پتلی مویشیوں کے درمیان فیصلہ کروں گا۔\n21۔ کیونکہ تم نے پہلو اور کندھے سے دھکا دیا، اور تمام بیمار لوگوں کو اپنے سینگوں سے دھکیل دیا، یہاں تک کہ تم نے انہیں باہر بکھیر دیا؛\n22۔ اس لیے میں اپنے ریوڑ کو بچاؤں گا، اور وہ اب شکار نہیں رہیں گے؛ اور میں مویشیوں اور مویشیوں کے درمیان فیصلہ کروں گا۔\n23۔ اور میں ان پر ایک چرواہا مقرر کروں گا، اور وہ انہیں کھلائے گا، حتیٰ کہ میرا خادم داؤد بھی؛ وہ انہیں کھلائے گا، اور وہ ان کا چرواہا ہوگا۔\n24۔ اور میں خداوند ان کا خدا ہوں گا، اور میرا بندہ داؤد ان میں شہزادہ ہوگا؛ میں نے خداوند نے کہا ہے۔\n25۔ اور میں ان کے ساتھ امن کا عہد کروں گا، اور برے جانوروں کو زمین سے نکال دوں گا، اور وہ جنگل میں محفوظ رہیں گے، اور جنگل میں سوئیں گے۔\n26۔ اور میں انہیں اور اپنے پہاڑی کے ارد گرد کی جگہوں کو برکت بناؤں گا؛ اور میں بارش کو اس کے موسم میں گروا دوں گا؛ برکتوں کی بارش ہوگی۔\n27۔ اور کھیت کا درخت اپنا پھل دے گا، اور زمین اپنا پھل دے گی، اور وہ اپنی زمین میں محفوظ رہیں گے، اور جان جائیں گے کہ میں خداوند ہوں، جب میں ان کے جوتے کی پٹیاں توڑ دوں گا اور انہیں ان کے ہاتھوں سے آزاد کر دوں گا جنہوں نے ان کی خدمت کی۔\n28۔ اور وہ اب غیر مسلموں کا شکار نہیں ہوں گے، نہ ہی زمین کا درندہ انہیں کھا جائے گا؛ لیکن وہ محفوظ رہیں گے، اور کوئی انہیں خوفزدہ نہیں کرے گا۔\n29۔ اور میں ان کے لیے ایک مشہور پودا اگاؤں گا، اور وہ زمین میں بھوک سے نہ کھائیں گے، نہ ہی کافروں کی شرمندگی برداشت کریں گے۔ {شہرت کے لیے: یا، شہرت کے لیے} {استعمال شدہ: عبرانی۔ لے جایا گیا}\n30۔ یوں وہ جان لیں گے کہ میں، خداوند ان کا خدا، ان کے ساتھ ہوں، اور وہ، حتیٰ کہ اسرائیل کا گھرانہ، میرے لوگ ہیں، خداوند خدا فرماتا ہے۔\n31. اور تم میرے ریوڑ، میرے چراگاہ کے ریوڑ، {ہو} انسان، {اور} میں {ہوں} تمہارا خدا، خداوند خدا فرماتا ہے۔","1۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، اپنا چہرہ سعیر پہاڑ کے خلاف رکھ دو، اور اس کے خلاف نبوت کرو،\n3۔ اور اس سے کہو، خداوند خدا یہ فرماتا ہے؛ دیکھو، اے ماؤنٹ سیئر، میں تمہارے خلاف ہوں، اور میں اپنا ہاتھ تمہارے خلاف بڑھاؤں گا، اور تمہیں سب سے زیادہ ویران کر دوں گا۔ {زیادہ تر...: عبرانی۔ ویرانی اور ویرانی}\n4۔ میں تمہارے شہروں کو تباہ کر دوں گا، اور تم ویران ہو جاؤ گے، اور تم جان لو گے کہ میں خداوند ہوں۔\n5. کیونکہ تم نے ہمیشہ نفرت رکھی، اور بنی اسرائیل کا خون تلوار کی طاقت سے ان کی مصیبت کے وقت بہایا جب ان کی بدکاری کا انجام ہوا: {دائمی...: یا، پرانی نفرت} {بہا دیا...: عبرانی۔ بچوں کو بہا دیا} {زبردستی: عبرانی۔ ہاتھ}\n6. لہٰذا، {جت} میں زندہ ہوں، خداوند خدا فرماتا ہے، میں تمہیں خون کے لیے تیار کروں گا، اور خون تمہارا پیچھا کرے گا: اگر تم نے خون سے نفرت نہیں کی، تو خون بھی تمہارا پیچھا کرے گا۔\n7۔ یوں میں ماؤنٹ سیئر کو سب سے ویران بنا دوں گا، اور جو بے ہوش ہو جائے گا اور جو واپس آئے گا اسے اس سے کاٹ دوں گا۔ {زیادہ تر...: عبرانی۔ ویرانی اور ویرانی}\n8۔ اور میں اس کے پہاڑوں کو اس کے مارے گئے لوگوں سے بھر دوں گا: تیری پہاڑیوں میں، تمہاری وادیوں میں، اور تمہارے تمام دریاؤں میں، وہ گریں گے جو تلوار سے مارے گئے۔\n9۔ میں تمہیں ہمیشہ کے لیے ویران کر دوں گا، اور تمہارے شہر واپس نہیں آئیں گے: اور تم جان لو گے کہ میں خداوند ہوں۔\n10۔ کیونکہ تم نے کہا ہے، یہ دو قومیں اور یہ دو ممالک میرے ہوں گے، اور ہم اسے حاصل کریں گے؛ جبکہ خداوند وہاں تھا: {جبکہ...: یا، اگر خداوند وہاں تھا}\n11۔ لہٰذا، {جیسا کہ میں زندہ ہوں} خداوند خدا فرماتا ہے، میں تیری غصے اور تیری حسد کے مطابق عمل کروں گا جو تم نے ان سے نفرت کی وجہ سے استعمال کی ہے؛ اور میں ان میں خود کو پہچان لوں گا، جب میں تمہارا فیصلہ کروں گا۔\n12۔ اور تم جان لو گے کہ میں خداوند ہوں، اور میں نے تمہاری تمام کفر سنی ہے جو تم نے اسرائیل کے پہاڑوں کے خلاف کہی ہیں، کہتی ہیں، وہ ویران ہیں، ہمیں نگلنے کے لیے دیے گئے ہیں۔ {پڑھنے کے لیے: عببرانی۔ کھانے کے لیے}\n13۔ یوں تم نے اپنے منہ سے میرے خلاف فخر کیا، اور اپنے الفاظ میرے خلاف بڑھا دیے: میں نے سنا ہے۔ {فخر سے کہا گیا: ہیب۔ بڑھا چڑھا کر}\n14. خداوند خدا یہ فرماتا ہے؛ جب پوری زمین خوش ہوگی، میں تمہیں ویران کر دوں گا۔\n15۔ جیسے تم اسرائیل کے گھر کی میراث پر خوش ہوئے، کیونکہ وہ ویران تھا، ویسا ہی میں تمہارے ساتھ کروں گا: اے ماؤنٹ سیئر، تم ویران ہو جاؤ گے، اور تمام ایدومیا بھی، {حتی} سب کچھ: اور وہ جان جائیں گے کہ میں خداوند ہوں۔","1. اے انسان کے بیٹے، اسرائیل کے پہاڑوں کو پیش گوئی کرو اور کہو، اے اسرائیل کے پہاڑوں، خداوند کا کلام سنو:\n2. خداوند خدا یہ فرماتا ہے؛ کیونکہ دشمن نے تمہارے خلاف کہا ہے، آہا، حتیٰ کہ قدیم بلندیاں بھی ہمارے قبضے میں ہیں:\n3۔ لہٰذا نبوت کرو اور فرماو، خداوند خدا یہ فرماتا ہے؛ کیونکہ انہوں نے {تم} کو ویران کر دیا ہے، اور تمہیں ہر طرف سے نگل لیا ہے، تاکہ تم کافروں کی باقیات کی ملکیت بن سکو، اور تم باتونی لوگوں کے ہونٹوں میں لے آئے ہو، اور لوگوں کی بدنامی ہو: {کیونکہ: عبرانی۔ کیونکہ کیونکہ کیونکہ} {آر...: یا، تم زبان کے کنارے پر آتے ہو}\n4. لہٰذا، اے اسرائیل کے پہاڑوں، خداوند خدا کا کلام سنو؛ یہی فرماتا ہے خداوند خدا پہاڑوں، پہاڑوں، دریاؤں کو، وادیوں کو، ویران ویران علاقوں کو، اور ان شہروں کو جو شکار بن گئے ہیں اور ان کے آس پاس موجود مشرکین کے باقیات کا مذاق بن چکے ہیں؛ {دریاؤں: اور، باٹمز، یا، ڈیلز}\n5۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ یقینا میں نے اپنی حسد کی آگ میں کافروں کے باقیات کے خلاف بات کی ہے، اور تمام ایڈومیا کے خلاف بھی، جنہوں نے میری زمین کو اپنے قبضے میں لے لیا ہے، دل کی خوشی اور نفرت کے ساتھ، اسے شکار کے لیے پھینکنے کے لیے۔\n6۔ لہٰذا اسرائیل کی سرزمین کے بارے میں پیش گوئی کرو، اور پہاڑوں، پہاڑوں، دریاؤں اور وادیوں کو کہو۔ خداوند خدا یہ فرماتا ہے؛ دیکھو، میں نے اپنی حسد اور غصے میں بات کی ہے، کیونکہ تم نے کافروں کی شرمندگی برداشت کی:\n7۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ میں نے اپنا ہاتھ اٹھایا ہے، یقینا وہ کافر جو تمہارے گرد ہیں، وہ اپنی شرمندگی برداشت کریں گے۔\n8۔ لیکن اے اسرائیل کے پہاڑوں، تم اپنی شاخیں نکالو اور اپنے پھل میرے قوم اسرائیل کو دلو؛ کیونکہ وہ آنے والے ہیں۔\n9۔ دیکھو، میں تمہارے لیے ہوں، اور میں تمہاری طرف رجوع کروں گا، اور تم جوئے اور بوئے جاؤ گے:\n10۔ اور میں تم پر انسانوں کو بڑھاؤں گا، پورے اسرائیل کے گھر، {حتیٰ کہ} سب کے، اور شہر آباد ہوں گے، اور ویران علاقے تعمیر کیے جائیں گے:\n11۔ اور میں تم پر انسان اور جانور کو بڑھاؤں گا؛ اور وہ بڑھیں گے اور پھل دیں گے: اور میں تمہیں تمہاری پرانی جائیدادوں کے بعد آباد کروں گا، اور تمہارے آغاز سے بہتر کروں گا: اور تم جان لو گے کہ میں خداوند ہوں۔\n12. ہاں، میں لوگوں کو تم پر چلنے پر مجبور کروں گا، {حتیٰ کہ} میرے لوگ اسرائیل؛ اور وہ تمہیں اپنے قبضے میں لے لیں گے، اور تم ان کی میراث بنو گے، اور اب سے تم انہیں انسانوں سے محروم نہیں کرو گے۔\n13۔ خداوند خدا یہ فرماتا ہے؛ کیونکہ وہ تم سے کہتے ہیں، تو نے انسانوں کو نگل لیا اور اپنی قوموں کو سوگ سے محروم کر دیا؛\n14۔ لہٰذا تو اب انسانوں کو نہیں کھا جاؤ گے، نہ اپنی قوموں کو مزید مایوس کرو گے، خداوند خدا فرماتا ہے۔ {غمگین: یا، گرنے کا سبب}\n15. نہ میں اب تم میں لوگوں کو کافروں کی شرمندگی سناؤں گا، نہ تم لوگوں کی ملامت برداشت کرو گے، نہ ہی تم اپنی قوموں کو مزید گرا دو گے، خداوند خدا فرماتا ہے۔\n16۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا،\n17۔ اے انسان کے بیٹے، جب بنی اسرائیل اپنے ملک میں آباد ہوئے تو انہوں نے اپنے طریقے اور اعمال سے اسے ناپاک کیا: ان کا راستہ میرے سامنے ایسے تھا جیسے ایک بے گھر عورت کی ناپاکی۔\n18۔ اسی لیے میں نے ان پر اپنا غصہ نکالا اس خون کے لیے جو انہوں نے زمین پر بہایا تھا، اور ان کے بتوں کے لیے جن سے انہوں نے اسے آلودہ کیا تھا:\n19۔ اور میں نے انہیں کافروں میں بکھیر دیا، اور وہ ملکوں میں بکھر گئے: ان کے طریقے اور عمل کے مطابق میں نے ان کا فیصلہ کیا۔\n20۔ اور جب وہ کافروں میں داخل ہوئے، جہاں وہ گئے، تو انہوں نے میرے مقدس نام کی توہین کی، جب انہوں نے ان سے کہا، یہ خداوند کے لوگ ہیں، اور اس کی سرزمین سے نکل چکے ہیں۔\n21. لیکن مجھے اپنے مقدس نام پر رحم آیا، جسے اسرائیل کے گھر نے کافروں کے درمیان بے حرمتی کی تھی، جہاں بھی وہ گئے۔\n22۔ لہٰذا اسرائیل کے گھر سے فرماو، خداوند خدا یہ فرماتا ہے؛ میں یہ تمہارے لیے نہیں، اے اسرائیل کے گھر، بلکہ اپنے مقدس نام کے لیے، جو تم نے کافروں میں بے حرمتی کی ہے، جہاں تم گئے تھے۔\n23۔ اور میں اپنے عظیم نام کو مقدس کروں گا، جو کافروں میں بے حرمتی کی گئی تھی، جسے تم نے ان کے درمیان بے حرمتی کی؛ اور کافر جان جائیں گے کہ میں خداوند ہوں، خداوند خدا فرماتا ہے، جب میں ان کی آنکھوں کے سامنے تجھ میں پاک ہو جاؤں گا۔ {ان کا: یا، تمہارا}\n24۔ کیونکہ میں تمہیں کافروں میں سے نکالوں گا، تمہیں تمام ملکوں سے جمع کروں گا، اور تمہیں تمہاری سرزمین میں لے آؤں گا۔\n25۔ پھر میں تم پر صاف پانی چھڑکوں گا، اور تم پاک ہو جاؤ گے: تمہاری تمام گندگی اور تمہارے تمام بتوں سے میں تمہیں پاک کروں گا۔\n26۔ میں تمہیں نیا دل بھی دوں گا، اور تمہارے اندر ایک نئی روح ڈالوں گا: اور میں تمہارے جسم سے پتھر کا دل نکال دوں گا، اور تمہیں گوشت کا دل دوں گا۔\n27۔ اور میں اپنی روح تمہارے اندر ڈالوں گا، اور تمہیں اپنے قوانین میں چلنے پر مجبور کروں گا، اور تم میرے فیصلوں کی حفاظت کرو گے، اور ان پر عمل کرو گے۔\n28۔ اور تم اس زمین میں رہو گے جو میں نے تمہارے آباؤ اجداد کو دی؛ اور تم میرے لوگ بنو گے، اور میں تمہارا خدا بنوں گا۔\n29۔ میں تمہیں تمہاری تمام گندگیوں سے بھی بچاؤں گا: اور میں اناج بلاؤں گا، اسے بڑھاؤں گا، اور تم پر قحط نہیں ڈالوں گا۔\n30۔ اور میں درخت کے پھل کو بڑھا دوں گا، اور کھیت میں اضافہ کروں گا، تاکہ تمہیں غیر مسلموں میں قحط کی کوئی ملامت نہ ملے۔\n31۔ پھر تم اپنے برے طریقوں اور اپنے اچھے اعمال کو یاد رکھو گے، اور اپنے گناہوں اور گناہوں کی وجہ سے اپنی نظر میں خود کو ناپسند کرو گے۔\n32. میں تمہارے لیے نہیں کہتا {یہ}، خداوند خدا فرماتا ہے، کہ تمہیں معلوم ہو: اے اسرائیل کے گھرانے کے اپنے طریقوں کے لیے شرمندہ اور پریشان ہو جاؤ۔\n33۔ خداوند خدا یہ فرماتا ہے؛ جس دن میں تمہیں تمہارے تمام گناہوں سے پاک کروں گا، میں تمہیں بھی شہروں میں آباد کروں گا، اور ویرانیاں تعمیر ہوں گی۔\n34۔ اور ویران زمین کو جوتا جائے گا، جبکہ وہ گزرنے والوں کے سامنے ویران ہے۔\n35۔ اور وہ کہیں گے، یہ زمین جو ویران تھی، جنت کے باغ کی طرح بن گئی ہے؛ اور ویران، ویران اور تباہ شدہ شہر باڑوں سے ڈھکے جا رہے ہیں، {اور} آباد ہو جاتے ہیں۔\n36۔ پھر جو کافر تمہارے ارد گرد رہ گئے ہیں وہ جان لیں گے کہ میں، خداوند، وہ تباہ شدہ {جگہیں} تعمیر کرتا ہوں اور جو ویران تھیں، وہ بوتا ہوں: میں خداوند نے کہا ہے {یہ}، اور میں یہ کروں گا۔\n37۔ خداوند خدا یہ فرماتا ہے؛ میں پھر بھی اسرائیل کے گھر کی طرف سے یہ درخواست کروں گا کہ وہ ان کے لیے یہ کام کرے؛ میں انہیں مردوں کی طرح بڑھاؤں گا۔\n38۔ مقدس ریوڑ کے طور پر، یروشلم کے ریوڑ کی طرح اپنی باوقار تہواروں میں؛ اسی طرح ویران شہر انسانوں کے جھنڈ سے بھر جائیں گے: اور وہ جان جائیں گے کہ میں خداوند ہوں۔ {مقدس...: عبرانی۔ مقدس چیزوں کا جھنڈ}","1۔ خداوند کا ہاتھ میرے اوپر تھا، اور اس نے مجھے خداوند کی روح میں باہر نکالا، اور مجھے اس وادی کے بیچ میں اتارا جو ہڈیوں سے بھری ہوئی تھی،\n2۔ اور مجھے ان کے ارد گرد سے گزرنے پر مجبور کیا: اور دیکھو، کھلی وادی میں بہت سے لوگ تھے؛ اور، دیکھو، {وہ} بہت خشک تھے۔ {ویلی: اوری، شیمپین}\n3۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، کیا یہ ہڈیاں زندہ رہ سکتی ہیں؟ اور میں نے جواب دیا، اے خداوند خدا، تو جانتا ہے۔\n4۔ پھر اس نے مجھ سے کہا، ان ہڈیوں پر نبوت کرو، اور ان سے کہو، اے خشک ہڈیوں، خداوند کا کلام سنو۔\n5۔ خداوند خدا ان ہڈیوں سے یوں فرماتا ہے؛ دیکھو، میں تمہارے اندر سانس داخل کروں گا، اور تم زندہ رہو گے:\n6۔ اور میں تم پر رگیں ڈالوں گا، تم پر گوشت لاؤں گا، تمہیں جلد سے ڈھانپ دوں گا، اور تم میں سانس دوں گا، اور تم زندہ رہو گے؛ اور تم جان لو گے کہ میں خداوند ہوں۔\n7۔ تو میں نے جیسا حکم دیا گیا تھا ویسا ہی پیش گوئی کی: اور جب میں نے پیش گوئی کی، تو ایک شور آیا، اور دیکھو ایک ہڈیاں آپس میں مل گئیں، ہڈی اس کی ہڈی سے ٹکرا گئی۔\n8۔ اور جب میں نے دیکھا، تو رگیں اور گوشت ان پر آ گئے، اور اوپر کی جلد نے انہیں ڈھانپ لیا: لیکن ان میں سانس نہیں تھی۔\n9۔ پھر اس نے مجھ سے کہا، ہوا کو پیش گوئی کرو، اے انسان کے بیٹے، اور ہوا سے کہو، خداوند خدا یہ فرماتا ہے؛ چار ہواؤں سے آؤ، اے سانس، اور ان مارے گئے پر سانس لے تاکہ وہ زندہ رہیں۔ {ہوا: یا، سانس}\n10۔ تو میں نے جیسا کہ اس نے حکم دیا ویسا ہی پیش گوئی کی، اور ان میں سانس آئی، اور وہ زندہ رہے، اور اپنے قدموں پر کھڑے ہو گئے، ایک بہت بڑی فوج۔\n11۔ پھر اس نے مجھ سے کہا، اے انسان کے بیٹے، یہ ہڈیاں اسرائیل کے پورے گھر کی ہیں: دیکھو، وہ کہتے ہیں، ہماری ہڈیاں خشک ہو گئیں، اور ہماری امید ختم ہو گئی: ہم اپنے حصوں کے لیے کٹ گئے ہیں۔\n12۔ لہٰذا نبوت کرو اور ان سے کہو، خداوند خدا یہ فرماتا ہے؛ دیکھو، اے میرے لوگو، میں تمہاری قبریں کھولوں گا، اور تمہیں قبروں سے نکالوں گا، اور تمہیں زمین اسرائیل میں لے آؤں گا۔\n13۔ اور تم جان لو گے کہ میں خداوند ہوں، جب میں تمہاری قبریں کھولوں گا، اے میرے لوگ، اور تمہیں تمہاری قبروں سے نکالوں گا،\n14۔ اور میں اپنی روح تم میں ڈالوں گا، اور تم زندہ رہو گے، اور میں تمہیں تمہاری اپنی زمین میں رکھوں گا: تب تم جان لو گے کہ میں خداوند نے کہا اور عمل کیا ہے، خداوند فرماتا ہے۔\n15۔ خداوند کا کلام میرے پاس دوبارہ آیا، اور کہا،\n16۔ مزید برآں، اے انسان کے بیٹے، ایک چھڑی لے کر اس پر لکھو، یہوداہ کے لیے، اور بنی اسرائیل کے ساتھیوں کے لیے، پھر ایک اور چھڑی لے کر اس پر لکھو، یوسف کے لیے، افرائیم کی چھڑی، اور {لیے} اس کے تمام اسرائیلی خاندان کے لیے:\n17۔ اور انہیں ایک لکڑی میں ایک لکڑی میں جوڑ دوں؛ اور وہ تمہارے ہاتھ میں ایک ہو جائیں گے۔\n18۔ اور جب تمہارے قوم کے بچے تم سے بات کریں گے، کہیں گے، کیا تم ہمیں نہیں دکھاؤ گے کہ تم ان سے کیا مراد لیتے ہو؟\n19۔ ان سے کہو، خداوند خدا یہ فرماتا ہے؛ دیکھو، میں یوسف کی چھڑی لیتا ہوں، جو افرایم کے ہاتھ میں ہے، اور اسرائیل کے قبائل اس کے ساتھیوں کے ہاتھ میں، اور انہیں اپنے ساتھ رکھوں گا، یہاں تک کہ یہوداہ کی چھڑی کے ساتھ، اور انہیں ایک لاٹھی بنا دوں گا، اور وہ میرے ہاتھ میں ایک ہوں گے۔\n20۔ اور جن لکڑیوں پر تم لکھتے ہو وہ تمہارے ہاتھ میں ان کی آنکھوں کے سامنے ہوں گی۔\n21۔ اور ان سے کہو، خداوند خدا یہی فرماتا ہے؛ دیکھو، میں بنی اسرائیل کو کافروں میں سے لے جاؤں گا، جہاں وہ چلے گئے ہیں، اور انہیں ہر طرف جمع کروں گا اور ان کی سرزمین میں لے جاؤں گا:\n22۔ اور میں انہیں اسرائیل کے پہاڑوں کی زمین میں ایک قوم بناؤں گا؛ اور ان سب کے لیے ایک بادشاہ ہوگا: اور وہ دو قومیں نہیں رہیں گے، نہ ہی دو سلطنتوں میں تقسیم ہوں گے:\n23۔ نہ وہ اپنے بتوں سے، نہ اپنی نفرت انگیز چیزوں سے، نہ اپنی کسی گناہ سے خود کو ناپاک کریں گے، بلکہ میں انہیں ان کے تمام گھروں سے بچاؤں گا جہاں انہوں نے گناہ کیا ہے، اور انہیں پاک کروں گا: اسی طرح وہ میرے لوگ ہوں گے، اور میں ان کا خدا بنوں گا۔\n24۔ اور میرا خادم داؤد ان پر بادشاہ ہوگا؛ اور ان سب کے پاس ایک چرواہا ہوگا: وہ بھی میرے فیصلوں میں چلیں گے، میرے قوانین کی پابندی کریں گے، اور عمل کریں گے۔\n25۔ اور وہ اس زمین میں بسیں گے جو میں نے اپنے خادم یعقوب کو دی ہے، جہاں تمہارے آباؤ اجداد رہتے تھے؛ اور وہ اسی میں رہیں گے، {حتی} وہ، ان کے بچے بھی، اور ان کے بچوں کے بچے ہمیشہ کے لیے رہیں گے: اور میرا خادم ڈیوڈ {ہمیشہ کے لیے} ان کا شہزادہ رہے گا۔\n26. مزید برآں، میں ان کے ساتھ امن کا عہد کروں گا؛ یہ ان کے ساتھ ایک دائمی عہد ہوگا: اور میں انہیں رکھوں گا، انہیں بڑھاؤں گا، اور ہمیشہ کے لیے ان کے درمیان اپنا پناہ گاہ قائم کروں گا۔\n27۔ میرا خیمہ بھی ان کے ساتھ ہوگا: ہاں، میں ان کا خدا بنوں گا، اور وہ میرے لوگ ہوں گے۔\n28۔ اور کافر جان جائیں گے کہ میں خداوند اسرائیل کو پاک کرتا ہوں، جب میرا مقدس مقام ہمیشہ کے لیے ان کے درمیان رہے گا۔","1۔ اور خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n2۔ اے انسان کے بیٹے، اپنا چہرہ گوج، مگوج کی زمین، مشک اور طوبال کے سردار شہزادے کے خلاف رکھو اور اس کے خلاف پیش گوئی کرو، {سردار...: یا، سردار کا شہزادہ}\n3۔ اور کہو، خداوند خدا یہ فرماتا ہے؛ دیکھو، میں تمہارے خلاف ہوں، اے جوگ، مشح اور طوبال کے سردار شہزادے:\n4۔ اور میں تمہیں واپس پلٹاؤں گا، تمہارے جبڑوں میں ہک لگاؤں گا، اور تمہیں اور تمہاری تمام فوج، گھوڑے اور گھڑ سوار، جو ہر قسم کے زرہ پوش ہوں گے، یہاں تک کہ ایک بڑی جماعت کے ساتھ بھی، جو سب تلواریں سنبھالے ہوئے ہوں گے:\n5۔ فارس، ایتھوپیا، اور لیبیا ان کے ساتھ؛ ان سب کے پاس ڈھال اور ہیلمٹ تھا: {لیبیا: یا، پھوت}\n6۔ گومر اور اس کے تمام بینڈز؛ شمالی کوارٹرز کے توگارمہ کے گھر، اور اس کے تمام گروہ: {اور} بہت سے لوگ آپ کے ساتھ۔\n7۔ تیار رہو، اور اپنے لیے، اپنے لیے، اور اپنی تمام جماعت کے لیے تیار ہو جاؤ جو تمہارے پاس جمع ہیں، اور ان کا محافظ بنو۔\n8۔ کئی دنوں کے بعد تمہیں دورہ کیا جائے گا: آخری سالوں میں تم اس زمین میں آؤ گے {جو تلوار سے واپس لائی گئی ہے}، {اور بہت سے لوگوں سے جمع ہو کر، اسرائیل کے پہاڑوں کے خلاف، جو ہمیشہ ویران رہے ہیں؛ لیکن یہ قوموں سے نکالا گیا ہے، اور وہ سب محفوظ رہیں گے۔\n9۔ تم اوپر چڑھو گے اور طوفان کی طرح آؤ گے، تم بادل کی طرح بنو گے جو زمین کو ڈھانپے گا، تم، اور تمہارے تمام گروہوں کو، اور تمہارے ساتھ بہت سے لوگ۔\n10۔ خداوند خدا یہ فرماتا ہے؛ یہ بھی ہو جائے گا، {کہ} ساتھ ہی آپ کے ذہن میں چیزیں آئیں گی، اور آپ ایک برا خیال سوچیں گے: {سوچو...: یا، کوئی شرارتی مقصد سوچو گے}\n11۔ اور تم کہو گے، میں بے دیوار دیہاتوں کی زمین پر جاؤں گا؛ میں ان لوگوں کے پاس جاؤں گا جو آرام کر رہے ہیں، جو محفوظ رہتے ہیں، سب بغیر دیواروں کے رہتے ہیں، اور ان کے پاس نہ سلاخیں ہیں نہ دروازے، {محفوظ: یا پراعتماد ساتھ}\n12۔ مال غنیمت لینا، اور شکار کرنا؛ اپنا ہاتھ ان ویران جگہوں پر موڑو جو اب آباد ہیں، اور ان لوگوں کی طرف جو ان قوموں سے جمع ہوئے ہیں جنہوں نے مویشی اور مال حاصل کیے ہیں، جو زمین کے بیچ میں رہتے ہیں۔ {لینے کے لیے...: عببرانی۔ غنیمت کو خراب کرنے کے لیے، اور شکار کو شکار کرنے کے لیے} {درمیان: عبرانی۔ ناف}\n13۔ شیبا، دیدان، اور ترشیش کے تاجر، ان کے تمام نوجوان شیروں کے ساتھ، تم سے کہیں گے، کیا تم مال غنیمت لینے آئے ہو؟ کیا تم نے شکار لینے کے لیے اپنی جماعت جمع کی ہے؟ چاندی اور سونا لے جانے کے لیے، مویشی اور مال لے جانے کے لیے، بڑی مال غنیمت لینے کے لیے؟\n14۔ لہٰذا، اے انسان کے بیٹے، نبوت کرو اور گوج سے کہو، خداوند خدا یہ فرماتا ہے؛ اس دن جب میرے لوگ اسرائیل محفوظ رہیں گے، کیا تم نہیں جانتے؟\n15۔ اور تم اپنی جگہ سے شمالی علاقوں سے آؤ گے، اور تمہارے ساتھ بہت سے لوگ ہوں گے، سب گھوڑوں پر، ایک بڑی جماعت اور ایک زبردست فوج کے ساتھ:\n16۔ اور تم میرے قوم اسرائیل کے خلاف آؤ گے، زمین کو ڈھانپنے کے لیے بادل کی طرح؛ یہ آخری دنوں میں ہوگا، اور میں تمہیں اپنی سرزمین کے خلاف لے جاؤں گا، تاکہ کافر مجھے جان سکیں، جب میں تمہارے اندر مقدس ہو جاؤں گا، اے جوج، ان کی آنکھوں کے سامنے۔\n17۔ خداوند خدا یہ فرماتا ہے؛ کیا تم وہی ہو جس کے بارے میں میں نے پرانے زمانے میں اپنے بندوں، اسرائیل کے نبیوں کے ذریعے بات کی تھی، جنہوں نے ان دنوں {بہت} سالوں میں پیش گوئی کی تھی کہ میں تمہیں ان کے خلاف لاؤں گا؟ {بذریعہ: عبرانی ہاتھوں سے}\n18۔ اور یہ اسی وقت ہوگا جب گوگ اسرائیل کی سرزمین پر حملہ کرے گا، خداوند خدا فرماتا ہے، {کہ} میرا غضب میرے چہرے پر اٹھے گا۔\n19۔ کیونکہ میں نے اپنی حسد میں {اور} اپنے غضب کی آگ میں بات کی ہے، یقینا اس دن زمین اسرائیل میں ایک بڑا ہلچل آئے گی؛\n20۔ تاکہ سمندر کی مچھلیاں، آسمان کے پرندے، اور میدان کے جانور، اور زمین پر رینگنے والے تمام جانور، اور زمین پر موجود تمام انسان، میری موجودگی سے ہل جائیں، اور پہاڑ گر جائیں گے، اور کھڑی جگہیں گر جائیں گی،  اور ہر دیوار زمین پر گر جائے گی۔ {ڈھلوان ہے...: یا، ٹاورز، یا، سیڑھیاں}\n21۔ اور میں اپنے تمام پہاڑوں میں اس کے خلاف تلوار کا مطالبہ کروں گا، خداوند خدا فرماتا ہے: ہر انسان کی تلوار اس کے بھائی کے خلاف ہوگی۔\n22۔ اور میں اس کے خلاف وبا اور خون سے درخواست کروں گا؛ اور میں اس پر، اس کے گروہوں پر، اور ان بہت سے لوگوں پر جو اس کے ساتھ ہیں، ایک تیز بارش، بڑی اولے برساؤں گا، آگ اور گندھک بھی۔\n23. یوں میں خود کو بڑھاؤں گا اور خود کو پاک کروں گا؛ اور میں بہت سی قوموں کی نظر میں پہچانا جاؤں گا، اور وہ جان جائیں گے کہ میں خداوند ہوں۔","1۔ لہٰذا، اے انسان کے بیٹے، گوگ کے خلاف نبوت کرو اور کہو، خداوند خدا یہ فرماتا ہے؛ دیکھو، میں تمہارے خلاف ہوں، اے جوگ، مشح اور طوبال کے سردار شہزادے:\n2۔ اور میں تمہیں واپس پلٹاؤں گا، اور صرف تمہارے چھٹے حصے کو چھوڑ دوں گا، اور تمہیں شمالی علاقوں سے اوپر لے آؤں گا، اور تمہیں اسرائیل کے پہاڑوں پر لے آؤں گا: {چھوڑ دو...: یا تمہیں چھ آفتوں سے ماروں گا؛ یا تمہیں چھ دانتوں والے کانٹے سے پیچھے کھینچوں گا} {شمال...: عبرانی۔ شمال کے کنارے}\n3۔ اور میں تمہارے بائیں ہاتھ سے کمان نکالوں گا، اور تمہارے تیر تیرے دائیں ہاتھ سے گرا دوں گا۔\n4. تم اسرائیل کے پہاڑوں پر گر جاؤ گے، تم، اور تمہارے تمام گروہ، اور وہ لوگ جو تمہارے ساتھ ہیں: میں تمہیں ہر قسم کے بھوکے پرندوں کے حوالے کروں گا، اور کھیتوں کے جانوروں کو کھائے جانے کے لیے۔ {ترتیب دینا: عبوری۔ ونگ} {ہونے والا...: عبرانی۔ کھانے کے لیے}\n5۔ تم کھلے میدان پر گر جاؤ گے: کیونکہ میں نے کہا ہے، خداوند خدا فرماتا ہے۔ {کھلا...: عبرانی۔ میدان کا چہرہ}\n6۔ اور میں ماجوج پر آگ بھیجوں گا، اور ان میں سے جو جزائر میں لاپرواہ رہتے ہیں، اور وہ جان جائیں گے کہ میں خداوند ہوں۔ {لاپرواہی: یا، اعتماد سے}\n7. اسی طرح میں اپنے مقدس نام کو اپنی قوم اسرائیل کے درمیان ظاہر کروں گا؛ اور میں انہیں اپنے مقدس نام کو مزید آلودہ نہیں کرنے دوں گا: اور کافر جان جائیں گے کہ میں اسرائیل میں خداوند ہوں، مقدس ہستی۔\n8۔ دیکھو، یہ آ گیا ہے، اور یہ ہو چکا ہے، خداوند خدا فرماتا ہے؛ آج وہ دن ہے جس کے بارے میں میں نے بات کی ہے۔\n9۔ اور جو لوگ اسرائیل کے شہروں میں رہتے ہیں وہ باہر نکلیں گے، اور ہتھیاروں کو آگ لگائیں گے اور جلا دیں گے، ڈھالیں اور بکلر، کمان اور تیر، اور چھڑیاں اور نیزے، اور انہیں سات سال تک آگ سے جلائیں گے: {ہاتھ کی چھڑیاں: یا، نیزے} {انہیں جلا دو...: یا آگ لگا دو}\n10۔ تاکہ وہ کھیت سے کوئی لکڑی نہ نکالیں، نہ ہی جنگلات سے کوئی لکڑی کاٹیں؛ کیونکہ وہ ہتھیاروں کو آگ سے جلائیں گے: اور وہ ان لوگوں کو لوٹیں گے جنہوں نے انہیں لوٹا، اور ان کو لوٹیں گے جنہوں نے انہیں لوٹا، خداوند خدا فرماتا ہے۔\n11۔ اور اسی دن یہ ہو جائے گا، {کہ} میں گوگ کو اسرائیل میں قبروں کی جگہ دوں گا، سمندر کے مشرق میں مسافروں کی وادی: اور یہ مسافروں کی ناکوں کو روک دے گا: اور وہاں وہ گوگ اور اس کے تمام لوگوں کو دفن کریں گے: اور وہ اسے ہامونگوگ کی وادی کہیں گے۔ {ناکیں: یا، منہ} {ہمونگوگ: یعنی، گوگ کی کثرت}\n12۔ اور سات مہینے اسرائیل کے گھر کو ان کی تدفین کرنی ہوگی تاکہ وہ زمین کو پاک کر سکیں۔\n13. ہاں، زمین کے تمام لوگ انہیں دفن کریں گے؛ اور یہ ان کے لیے اس دن شہرت ہوگی جب میں جلال پاؤں گا، خداوند خدا فرماتا ہے۔\n14۔ اور وہ مسلسل کام کرنے والے مردوں کو الگ کریں گے، جو زمین سے گزرتے ہوئے مسافروں کے ساتھ زمین پر باقی ماندہ لوگوں کو دفن کریں گے، تاکہ اسے صاف کیا جا سکے: سات ماہ کے بعد وہ تلاش کریں گے۔ {مرد...: عبرانی۔ مین آف کنٹینوئنس}\n15۔ اور جو مسافر زمین سے گزرتے ہیں، جب {کو} کسی کی ہڈی دیکھے گا، تو وہ اس کے پاس ایک نشان لگائے گا، جب تک کہ دفن کرنے والے اسے ہامونگوگ کی وادی میں دفن نہ کر دیں۔ {سیٹ اپ: عبوری۔ بلڈ}\n16۔ اور شہر کا نام بھی ہمونا ہوگا۔ یوں وہ زمین کو صاف کریں گے۔ {ہموناہ: یعنی، ہجوم}\n17۔ اور اے انسان کے بیٹے، خداوند خدا یہ فرماتا ہے؛ ہر پرندہ پرندے، اور میدان کے ہر جانور سے بات کرو، جمع ہو جاؤ اور آؤ؛ ہر طرف جمع ہو جاؤ میری قربانی کے لیے جو میں تمہارے لیے قربان کرتا ہوں، {حتیٰ کہ} اسرائیل کے پہاڑوں پر ایک عظیم قربانی بھی، تاکہ تم گوشت کھاؤ اور خون پی سکو۔ {ابھی...: عبرانی ہر پرندہ کے پرندے} {میری قربانی: یا، میری ذبح}\n18۔ تم طاقتوروں کا گوشت کھاؤ گے، اور زمین کے شہزادوں، مینڈوں، بھیڑوں، بکریوں، بیلوں کا خون پیو گے، جو سب باشان کے موٹے بچے ہیں۔ {بکریاں: عبرانی۔ گریٹ گوٹس}\n19۔ اور تم چربی کھاؤ گے جب تک کہ تم پیٹ بھر نہ جاؤ، اور خون پیو جب تک کہ تم نشے میں نہ ہو جاؤ، میری قربانی جو میں نے تمہارے لیے قربان کی ہے۔\n20. یوں تم میرے دسترخوان پر گھوڑوں اور رتھوں، طاقتور آدمیوں اور تمام جنگی مردوں سے بھر جاؤ گے، خداوند خدا فرماتا ہے۔\n21۔ اور میں اپنی شان کافروں میں رکھوں گا، اور تمام کافر دیکھیں گے کہ میں نے میرا فیصلہ کیا ہے، اور میرا ہاتھ جو میں نے ان پر رکھا ہے۔\n22. تاکہ اسرائیل کا گھر جان لے کہ میں اس دن سے ان کا خدا ہوں۔\n23۔ اور کافر جان لیں گے کہ اسرائیل کا گھر ان کے گناہوں کی وجہ سے قید ہو گیا: کیونکہ انہوں نے میرے خلاف زیادتی کی، اس لیے میں نے ان سے اپنا چہرہ چھپا لیا اور انہیں ان کے دشمنوں کے ہاتھ میں دے دیا، یوں وہ سب تلوار سے مارے گئے۔\n24۔ ان کی ناپاکی اور ان کی گناہوں کے مطابق میں نے ان کے ساتھ کیا ہے اور اپنا چہرہ ان سے چھپا لیا ہے۔\n25۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ اب میں یعقوب کی قید کو دوبارہ لاؤں گا، اور پورے اسرائیل کے گھر پر رحم کروں گا، اور اپنے مقدس نام کے لیے حسد کروں گا؛\n26۔ اس کے بعد انہوں نے اپنی شرمندگی اور تمام گناہوں کو برداشت کیا جن کی وجہ سے انہوں نے میرے خلاف گناہ کیا، جب وہ اپنے ملک میں محفوظ رہتے تھے اور کسی نے انہیں خوفزدہ نہیں کیا۔\n27۔ جب میں انہیں لوگوں سے دوبارہ لاتا ہوں، ان کے دشمنوں کی زمینوں سے نکالتا ہوں، اور ان میں کئی قوموں کی نظر میں پاک ہوتا ہوں؛\n28۔ تب وہ جان جائیں گے کہ میں خداوند ان کا خدا ہوں، جس نے انہیں کافروں کے درمیان قید میں لے جایا: لیکن میں نے انہیں ان کی اپنی زمین پر جمع کیا ہے اور وہاں کوئی نہیں چھوڑا۔ {جو کہ...: عبرانی میری وجہ سے، وغیرہ}\n29. اور میں اب ان سے اپنا چہرہ نہیں چھپاؤں گا: کیونکہ میں نے اپنی روح اسرائیل کے گھر پر انڈیل دی ہے، خداوند خدا فرماتا ہے۔","1۔ ہماری قید کے پانچویں اور بیسویں سال میں، سال کے آغاز میں، مہینے کے دسویں دن، چودہویں سال میں جب شہر متاثر ہوا، اسی دن خداوند کا ہاتھ مجھ پر تھا، اور مجھے وہاں لے آیا۔\n2۔ خدا کے خوابوں میں اس نے مجھے اسرائیل کی سرزمین میں لے آیا، اور مجھے ایک بہت اونچے پہاڑ پر بٹھایا، جس کے ذریعے وہ جنوب میں ایک شہر کے ڈھانچے کی طرح تھا۔ {کس سے: یا، کس پر}\n3۔ اور وہ مجھے وہاں لے آیا، اور وہاں ایک آدمی تھا، جس کی شکل پیتل کی طرح تھی، اس کے ہاتھ میں فلیس کی لکیر اور ایک ناپ تول والی سرکنڈہ تھی؛ اور وہ دروازے پر کھڑا تھا۔\n4۔ اور اس آدمی نے مجھ سے کہا، اے انسان کے بیٹے، اپنی آنکھوں سے دیکھو، اور اپنے کانوں سے سنو، اور اپنے دل کو اس سب پر رکھو جو میں تمہیں دکھاؤں گا؛ کیونکہ اس نیت کے لیے کہ میں تمہیں دکھا سکوں {کیا تم یہاں لائے ہو}: جو کچھ تم دیکھتے ہو اسے اسرائیل کے گھر کے سامنے بتانا۔\n5۔ اور دیکھو گھر کے باہر ایک دیوار ہے جو ارد گرد ہے، اور آدمی کے ہاتھ میں چھ ہاتھ لمبا اور ایک ہاتھ کی چوڑائی کی ناپ تول کی سرکنڈے ہے: اس نے عمارت کی چوڑائی ناپی، ایک سرکنڈہ؛ اور اونچائی، ایک ریڈ۔\n6۔ پھر وہ اس دروازے پر پہنچا جو مشرق کی طرف دیکھتا تھا، اور اس کی سیڑھیاں چڑھ کر دروازے کی دہلیز کو ناپا، جو ایک گھاسہ چوڑا تھا؛ اور دوسرا دروازے کا دروازہ، جو ایک ریڈ چوڑا تھا۔ {جو نظر آتا ہے...: عبرانی۔ جس کا چہرہ مشرق کی طرف راستہ تھا}\n7۔ اور ہر چھوٹا کمرہ ایک سرکنڈہ لمبا اور ایک چوڑا تھا؛ اور چھوٹے کمروں کے درمیان پانچ کیوبٹ تھے؛ اور دروازے کی دہلیز پر دروازے کے برآمدے کے پاس {تھا} کے اندر ایک سرکنڈہ تھا۔\n8۔ اس نے اندر کے دروازے کے برآمدے کی بھی پیمائش کی، جس میں ایک سرکنڈے تھا۔\n9۔ پھر اس نے دروازے کے برآمدے کو آٹھ کیوبٹ ناپا؛ اور ان کے ستون دو کیوبٹ ہیں؛ اور گیٹ کا پورچ اندر کی طرف تھا۔\n10۔ اور مشرق کی طرف دروازے کے چھوٹے کمرے اس طرف تین اور اس طرف تین تھے؛ وہ تین ایک ہی پیمانے کے تھے: اور ستونوں پر اس طرف اور اس طرف ایک پیمانہ تھا۔\n11۔ اور اس نے دروازے کے داخلے کی چوڑائی دس کیوبٹ ناپی؛ {اور} دروازے کی لمبائی، تیرہ کیوبٹ۔\n12۔ چھوٹے کمروں سے پہلے کی جگہ {اس طرف} ایک کیوبٹ {تھی} اور جگہ {تھی} اس طرف ایک کیوبٹ تھی: اور چھوٹے کمرے {اس طرف چھ کیوبٹ} تھے، اور اس طرف چھ کیوبٹ تھے۔ {جگہ: عبوری۔ حد بندی، یا، باؤنڈ}\n13۔ پھر اس نے ایک چھوٹے کمرے کی چھت سے دوسرے کمرے کی چھت تک دروازے کی پیمائش کی: چوڑائی پانچ بیس کیوبٹ تھی، دروازے کے خلاف دروازے۔\n14۔ اس نے دروازے کے ارد گرد دربار کے ستون تک بھی تین سو کیوبٹ کے ستون بنائے۔\n15۔ اور داخلی دروازے کے سامنے سے اندرونی دروازے کے پورچ کے سامنے تک پچاس کیوبٹ تھے۔\n16. اور چھوٹے کمروں کے لیے تنگ کھڑکیاں تھیں، اور ان کے ستون کے لیے دروازے کے اندر بھی، اور اسی طرح محرابوں کے لیے؛ اور کھڑکیاں اندر کی طرف تھیں: اور ہر کھمبے پر کھجور کے درخت تھے۔ {تنگ کرو: عبوری۔ بند} {محرابیں: یا، گیلریاں، یا، پورچز} {اندرونی طرف: یا، اندر}\n17۔ پھر اس نے مجھے باہر کے صحن میں لے آیا، اور وہاں کمرے تھے، اور عدالت کے لیے ایک فرش بنایا گیا تھا: تیس کمرے فرش پر تھے۔\n18۔ اور دروازوں کے ساتھ جو فرش دروازوں کی لمبائی کے ساتھ ہے، وہ نچلا فرش تھا۔\n19۔ پھر اس نے نچلے دروازے کے سامنے سے اندرونی صحن کے سامنے تک مشرق اور شمال کی طرف ایک سو کیوبٹ چوڑائی ناپی۔ {بغیر: یا، باہر سے}\n20۔ اور بیرونی صحن کا دروازہ جو شمال کی طرف دیکھتا تھا، اس نے اس کی لمبائی اور چوڑائی ناپی۔ {جو نظر آیا: عبوری۔ جس کا چہرہ تھا}\n21۔ اور اس کے چھوٹے کمرے اس طرف تین اور اس طرف تین تھے؛ اور اس کے ستون اور محرابیں پہلے دروازے کی پیمائش کے مطابق تھیں: اس کی لمبائی {پچاس کیوبٹ} تھی، اور چوڑائی پانچ سو بیس کیوبٹ۔ {محرابیں: اور، گیلریاں، یا، پورچز}\n22۔ اور ان کی کھڑکیاں، ان کے محراب، اور ان کے کھجور کے درخت، اس دروازے کی پیمائش کے مطابق تھے جو مشرق کی طرف دیکھتا ہے؛ اور وہ سات سیڑھیوں سے اس تک پہنچے؛ اور اس کے محرابیں ان کے سامنے تھیں۔\n23. اور اندرونی صحن کا دروازہ دروازے کے سامنے شمال اور مشرق کی طرف تھا؛ اور اس نے دروازے سے دروازے تک سو کیوبٹ ناپائے۔\n24۔ اس کے بعد وہ مجھے جنوب کی طرف لے گیا، اور جنوب کی طرف ایک دروازہ دیکھا: اور اس نے اس کے ستون اور اس کے محرابوں کو ان پیمانوں کے مطابق ناپا۔\n25۔ اور اس میں اور اس کے محرابوں میں کھڑکیاں تھیں، جیسے وہ کھڑکیاں: لمبائی {پچاس کیوبٹ} اور چوڑائی پانچ سو بیس کیوبٹ۔\n26۔ اور اس تک جانے کے لیے سات سیڑھیاں تھیں، اور ان کے سامنے محرابیں تھیں: اور اس میں کھجور کے درخت تھے، ایک اس طرف اور دوسری اس طرف، اس کے ستونوں پر۔\n27۔ اور اندرونی صحن میں جنوب کی طرف ایک دروازہ تھا، اور اس نے دروازے سے دروازے تک جنوب کی طرف سو کیوبٹ ناپے۔\n28۔ اور وہ مجھے جنوبی دروازے کے اندرونی صحن میں لے گیا: اور اس نے جنوبی دروازے کو ان پیمانوں کے مطابق ناپا؛\n29۔ اور اس کے چھوٹے کمرے، ان کے ستون اور ان کے محرابیں، ان پیمانوں کے مطابق؛ اور اس میں اور اس کے ارد گرد محرابوں میں کھڑکیاں تھیں: یہ پچاس ہاتھ لمبی اور پانچ بیس ہاتھ چوڑی تھی۔\n30۔ اور محرابیں تقریبا پانچ بیس ہاتھ لمبی اور پانچ ہاتھ چوڑی تھیں۔ {چوڑی: عبوری۔ وسعت}\n31۔ اور اس کے محرابیں مکمل دربار کی طرف تھیں؛ اور کھجور کے درخت ان کے ستونوں پر تھے: اور اس تک پہنچنے کے لیے آٹھ سیڑھیاں تھیں۔\n32۔ اور اس نے مجھے مشرق کی طرف اندرونی صحن میں لے آیا، اور اس نے دروازے کو ان پیمانوں کے مطابق ناپا۔\n33۔ اور اس کے چھوٹے کمرے، اس کے ستون اور ان کے محرابیں، ان پیمانوں کے مطابق تھے: اور وہاں کھڑکیاں تھیں اور ان کے محرابوں میں ارد گرد کھڑکیاں تھیں: یہ پچاس ہاتھ لمبی اور پانچ بیس کیوبٹ چوڑی تھی۔\n34۔ اور اس کے محرابیں بیرونی صحن کی طرف تھیں؛ اور اس کے ستونوں پر، اس طرف اور اس طرف کھجور کے درخت تھے: اور اس تک جانے کے لیے آٹھ سیڑھیاں تھیں۔\n35۔ اور وہ مجھے شمالی دروازے تک لے گیا، اور ان پیمانوں کے مطابق ناپا؛\n36۔ اس کے چھوٹے کمرے، اس کے ستون، اور اس کے محرابیں، اور اس کے گرد کھڑکیاں: لمبائی {پچاس} کیوبٹ، اور چوڑائی پانچ بیس کیوبٹ۔\n37۔ اور اس کے ستون مکمل دربار کی طرف تھے؛ اور اس کے ستونوں پر، اس طرف اور اس طرف کھجور کے درخت تھے: اور اس تک جانے کے لیے آٹھ سیڑھیاں تھیں۔\n38۔ اور کمرے اور ان کے داخلی راستے دروازوں کے ستونوں کے پاس تھے، جہاں وہ جلنے والی قربانی دھوتے تھے۔\n39۔ اور دروازے کے برآمدے میں اس طرف دو میزیں تھیں، اور اس طرف دو میزیں، تاکہ وہاں جلانے والی قربانی، گناہ کی قربانی اور ناجائز نذرانے کو کاٹ دیا جا سکے۔\n40۔ اور اس طرف کنارے پر، جب شمالی دروازے کے دروازے تک جاتا ہے، دو میزیں تھیں؛ اور دوسری طرف، جو {تھا} گیٹ کے برآمدے پر، {تھا} دو میزیں تھیں۔ {ایک کے طور پر...: یا، قدم پر}\n41۔ اس طرف چار میزیں {تھیں}، اور اس طرف چار میزیں، دروازے کے پاس؛ آٹھ میزیں، جن پر انہوں نے {اپنی قربانیاں} مار ڈالیں۔\n42۔ اور چار میزیں تراشے ہوئے پتھر کی تھیں، جو ایک ہاتھ اور آدھا لمبی، ایک ہاتھ اور آدھا چوڑی، اور ایک ہاتھ اونچی تھیں، اور اسی پر وہ آلات بھی رکھے گئے جن سے انہوں نے قربانی اور قربانی کو مارا۔\n43۔ اور اس کے اندر ہکس تھے، ایک چوڑا ہاتھ جو گرد بندھا ہوا تھا: اور میزوں پر نذرانہ کا گوشت تھا۔ {ہکس: اور، انڈآئرنز، یا، دو ہارتھ اسٹونز}\n44۔ اور اندرونی دروازے کے بغیر اندرونی صحن میں گلوکاروں کے کمرے تھے، جو شمالی دروازے کے کنارے تھے؛ اور ان کا منظر جنوب کی طرف تھا: ایک مشرقی دروازے کے کنارے شمال کی طرف تھا۔\n45۔ اور اس نے مجھ سے کہا، یہ کمرہ، جس کا منظر جنوب کی طرف ہے، پادریوں کے لیے ہے، جو گھر کے نگہبان ہیں۔ {چارج: یا، وارڈ، یا، آرڈیننس}\n46۔ اور وہ کمرہ جس کا منظر شمال کی طرف ہے، جو کاہنوں کے لیے ہے، جو قربان گاہ کے نگہبان ہیں: یہ صادوق کے بیٹے ہیں جو لاوی کے بیٹوں میں سے ہیں، جو خداوند کے قریب آتے ہیں تاکہ اس کی خدمت کریں۔\n47۔ تو اس نے صحن کی پیمائش کی، جو ایک سو ہوبیت لمبا اور سو ہاتھ چوڑا، چار چوکور تھا؛ اور وہ قربان گاہ {جو گھر کے سامنے تھی}۔\n48۔ اور اس نے مجھے گھر کے برآمدے تک لے جایا، اور برآمدے کے ہر ستون کی پیمائش کی، اس طرف پانچ کیوبٹ، اور اس طرف پانچ کیوبٹ: اور دروازے کی چوڑائی اس طرف تین کیوبٹ اور اس طرف تین کیوبٹ تھی۔\n49۔ برآمدے کی لمبائی بیس کیوبٹ تھی، اور چوڑائی گیارہ کیوبٹ؛ اور {اس نے مجھے سیڑھیوں سے لے کر لایا جہاں سے وہ اس کی طرف گئے: اور ستونوں کے پاس ستون تھے، ایک اس طرف اور دوسرا اس طرف۔","1۔ بعد میں اس نے مجھے مندر میں لے جایا، اور ستونوں کی پیمائش کی، ایک طرف چھ ہاتھ چوڑے اور دوسری طرف چھ ہاتھ چوڑے، جو کہ خیمہ کی چوڑائی تھی۔\n2۔ اور دروازے کی چوڑائی دس کیوبٹ تھی؛ اور دروازے کے اطراف ایک طرف پانچ ہاتھ اور دوسری طرف پانچ ہاتھ تھے: اور اس نے اس کی لمبائی چالیس کیوبٹ ناپی، اور چوڑائی بیس کیوبٹ۔ {دروازہ: یا، داخلہ}\n3۔ پھر وہ اندر گیا، اور دروازے کے ستون کی پیمائش کی، دو کیوبٹ؛ اور دروازہ، چھ کیوبٹ؛ اور دروازے کی چوڑائی، سات کیوبٹ۔\n4۔ تو اس نے اس کی لمبائی بیس کیوبٹ ناپی؛ اور چوڑائی، بیس کیوبٹ، مندر کے سامنے: اور اس نے مجھ سے کہا، یہ {ہے} سب سے مقدس {جگہ}۔\n5۔ گھر کی دیوار کی پیمائش کے بعد، چھ کیوبٹ؛ اور ہر طرف کے کمرے کی چوڑائی، چار کیوبٹ، گھر کے گرد ہر طرف۔\n6۔ اور سائیڈ چیمبرز تین تھے، ایک دوسرے کے اوپر، اور تیس ترتیب میں؛ اور وہ اس دیوار میں داخل ہوئے جو گھر کے ارد گرد کے کمروں کے لیے تھی، تاکہ وہ اسے روک سکیں، لیکن وہ گھر کی دیوار میں نہیں تھے۔ {ایک...: عبرانی۔ سائیڈ چیمبر اوور سائیڈ چیمبر} {تیس...: یا، تین اور تیس بار، یا، پاؤں} {ہولڈ: عبرانی۔ بی ہولڈن}\n7۔ اور وہاں ایک توسیع ہوئی، اور پھر بھی اوپر کی طرف مڑنا سائیڈ کمروں کی طرف بڑھا: کیونکہ گھر کا گھومنے والا حصہ گھر کے گرد اوپر کی طرف بڑھتا تھا: اس لیے گھر کی چوڑائی اب بھی اوپر کی طرف تھی، اور یوں سب سے نچلے کمرے سے درمیان سے سب سے اونچے تک بڑھ گئی۔ {وہاں...: عبرانی۔ اسے مزید چوڑا کیا گیا، اور یہ گھومتا رہا}\n8۔ میں نے ارد گرد گھر کی اونچائی بھی دیکھی: سائیڈ چیمبرز کی بنیادیں چھ بڑے کیوبٹس کی مکمل ریڈ تھیں۔\n9۔ دیوار کی موٹائی، جو اس سائیڈ چیمبر کے لیے {تھی} جو باہر نہیں تھی، {تھی} پانچ کیوبٹ: اور {وہ} جو {تھا} چھوڑ کر {تھا} وہ جگہ تھی جہاں سائیڈ چیمبرز {تھے}۔\n10۔ اور کمروں کے درمیان گھر کے ہر طرف بیس ہاتھ کی چوڑائی تھی۔\n11۔ اور سائیڈ کمروں کے دروازے {اس جگہ کو} تھے جو بائیں طرف تھا، ایک دروازہ شمال کی طرف، اور دوسرا دروازہ جنوب کی طرف: اور جو جگہ باقی تھی اس کی چوڑائی پانچ کیوبٹ تھی۔\n12۔ اب وہ عمارت جو مغرب کی طرف ایک الگ جگہ سے پہلے تھی، ستر کیوبٹ چوڑی تھی؛ اور عمارت کی دیوار پانچ کیوبٹ موٹی تھی، اور اس کی لمبائی نوے کیوبٹ تھی۔\n13۔ تو اس نے ایک سو ہاتھ لمبا گھر ناپا؛ اور الگ جگہ، اور عمارت، جس کی دیواریں ایک سو ہاتھ لمبی ہیں؛\n14۔ گھر کے چہرے کی چوڑائی، اور مشرق کی طرف الگ جگہ کی چوڑائی، سو کیوبٹ۔\n15۔ اور اس نے عمارت کی لمبائی کو اس الگ جگہ کے ساتھ ناپا جو اس کے پیچھے {تھا}، اور اس کی گیلریوں کو ایک طرف اور دوسری طرف سو کیوبٹس کے ساتھ، اندرونی مندر اور صحن کے برآمدے کے ساتھ؛ {گیلریاں: یا، کئی واک، یا، ستونوں کے ساتھ واک}\n16۔ دروازے کے ستون، تنگ کھڑکیاں، اور تین منزلہ گیلریاں، دروازے کے ساتھ، لکڑی سے لگی ہوئی تھیں، اور زمین سے کھڑکیوں تک، اور کھڑکیاں ڈھکی ہوئی تھیں؛ {cieled...: عبوری۔ لکڑی کی چھت} {اور ...: یا، اور زمین سے کھڑکیوں تک}\n17۔ دروازے کے اوپر، اندرونی گھر تک، اور باہر کی طرف بھی، اور اندر اور باہر کی تمام دیواروں کے پاس، پیمائش کے مطابق۔ {پیمائش: عبرانی۔ میجرز}\n18۔ اور یہ فرشتہوں اور کھجور کے درختوں سے بنایا گیا تھا، تاکہ ایک کھجور کا درخت فرشتہ اور فرشتہ کے درمیان ہو؛ اور {ہر} فرشتہ کے دو چہرے ہوتے تھے؛\n19۔ تاکہ ایک آدمی کا چہرہ ایک طرف کھجور کے درخت کی طرف اور نوجوان شیر کا چہرہ دوسری طرف کھجور کے درخت کی طرف ہو: یہ پورے گھر کے ارد گرد بنایا گیا تھا۔\n20۔ زمین سے دروازے کے اوپر تک کروبی اور کھجور کے درخت بنائے گئے، اور مندر کی دیوار پر بھی۔\n21۔ مندر کے ستون مربع تھے، اور مقدس مقام کا چہرہ بھی مربع تھا؛ ایک کی ظاہری شکل {دوسرے} کی ظاہری شکل کے طور پر۔ {پوسٹس: عبرانی۔ پوسٹ}\n22۔ لکڑی کی قربان گاہ تین ہاتھ اونچی تھی، اور اس کی لمبائی دو کیوبٹ تھی؛ اور اس کے کونے، اس کی لمبائی، اور اس کی دیواریں لکڑی کی تھیں: اور اس نے مجھ سے کہا، یہ وہ میز ہے جو خداوند کے سامنے ہے۔\n23۔ اور مندر اور مقدس مقام کے دو دروازے تھے۔\n24۔ اور دروازوں پر دو پتے {ایک} تھے، دو گھومنے والے پتے تھے؛ ایک دروازے کے لیے دو {پتے}، اور دوسرے {دروازے} کے لیے دو پتے۔\n25۔ اور ان پر، مندر کے دروازوں پر، فرشتہ اور کھجور کے درخت بنائے گئے، جیسے دیواروں پر بنے تھے؛ اور برآمدے کے سامنے موٹے تختے تھے۔\n26۔ اور ایک طرف تنگ کھڑکیاں اور کھجور کے درخت تھے اور دوسری طرف، برآمدے کے اطراف پر، گھر کے اطراف کے کمروں پر، اور موٹے تختے تھے۔","1۔ پھر اس نے مجھے مکمل دربار میں لے آیا، شمال کی طرف راستہ: اور اس نے مجھے اس کمرے میں لے آیا جو {تھا} الگ جگہ کے ساتھ، اور جو {تھا} عمارت کے سامنے شمال کی طرف۔\n2۔ ایک سو ہاتھ کی لمبائی سے پہلے شمالی دروازہ تھا، اور چوڑائی {پچاس کیوبٹ} تھی۔\n3۔ بیس {کیوبٹ} کے سامنے جو {تھے} اندرونی صحن کے لیے، اور اس فرش کے ساتھ جو {تھا} پورے دربار کے لیے تھا، {تھا} گیلری کے خلاف گیلری تین {منزلیں} میں۔\n4۔ اور کمروں کے سامنے دس ہاتھ چوڑائی کا ایک راستہ تھا جو اندر کی طرف تھا، ایک ہاتھ کا راستہ؛ اور ان کے دروازے شمال کی طرف تھے۔\n5. اب اوپری کمرے چھوٹے تھے: کیونکہ گیلریاں ان سے اونچے، نچلے اور عمارت کے سب سے درمیانی حصے سے اونچی تھیں۔ {اوپر تھے...: یا، ان میں سے کھایا تھا} {نچلے سے...: یا، اور عمارت نچلی اور درمیانی پر مشتمل تھی}\n6۔ کیونکہ وہ تین منزلوں میں تھے، لیکن ان کے ستون صحنوں کے ستون نہیں تھے: اس لیے عمارت سب سے نچلی اور درمیانی سے زیادہ تنگ کی گئی تھی۔\n7۔ اور وہ دیوار جو کمروں کے سامنے مکمل صحن کی طرف تھی، اس کی لمبائی پچاس کیوبٹ تھی۔\n8۔ کیونکہ پورے صحن میں جو کمرے {تھے} کی لمبائی {تھی} پچاس کیوبٹ: اور، دیکھو، مندر کے سامنے {تھے} سو کیوبٹ۔\n9۔ اور ان کمروں کے نیچے سے مشرق کی طرف کا داخلہ تھا، جب کوئی ان میں مکمل صحن سے داخل ہوتا ہے۔ {نیچے سے: یا، جگہ سے} {اندراج: یا، وہ جو مجھے لایا ہے} {جیسے...: یا، جیسا کہ وہ آیا}\n10۔ کمرے عدالت کی دیوار کی موٹائی میں مشرق کی طرف، الگ جگہ کے سامنے، اور عمارت کے ساتھ تھے۔\n11۔ اور ان کے سامنے کا راستہ ان کمروں کی شکل کی طرح تھا جو شمال کی طرف تھے، جتنے لمبے تھے، جتنے وہ چوڑے تھے: اور ان کے تمام راستے ان کے انداز اور دروازوں کے مطابق تھے۔\n12۔ اور ان کمروں کے دروازوں کے مطابق جو جنوب کی طرف تھے {تھا} راستے کے سر میں ایک دروازہ تھا، {حتی} وہ راستہ جو دیوار کے بالکل سامنے مشرق کی طرف تھا، جب کوئی ان میں داخل ہوتا ہے۔\n13۔ پھر اس نے مجھ سے کہا، شمالی کمرے اور جنوبی کمرے، جو الگ جگہ کے سامنے ہیں، مقدس کمرے ہیں، جہاں وہ پادری جو خداوند کے قریب آتے ہیں سب سے مقدس چیزیں کھائیں گے: وہاں سب سے مقدس چیزیں، گوشت کی قربانی، گناہ کی قربانی، اور گناہ کی قربانی، اور ناجائز قربانی پیش کریں گے؛ کیونکہ وہ جگہ {ہے} مقدس۔\n14۔ جب پادری وہاں داخل ہوں گے، تو وہ مقدس {جگہ} سے باہر نکل کر مکمل صحن میں نہیں جائیں گے، بلکہ وہاں اپنے لباس پہنائیں گے جہاں وہ خدمت کریں گے؛ کیونکہ وہ مقدس ہیں؛ اور دیگر لباس پہنیں گے، اور ان چیزوں کے قریب جائیں گے جو لوگوں کے لیے ہیں۔\n15۔ اب جب اس نے اندرونی گھر کی پیمائش مکمل کی، تو اس نے مجھے اس دروازے کی طرف لے گیا جس کا منظر مشرق کی طرف ہے، اور اس کے گرد ناپ لیا۔\n16۔ اس نے مشرقی جانب ناپنے والے ریڈ سے ناپا، پانچ سو ریڈز، اور ناپنے والی ریڈ کے ارد گرد تھا۔ {سائیڈ: عبوری۔ ہوا}\n17۔ اس نے شمالی جانب پانچ سو سرکنڈے ناپے، اور ناپنے والا سرکنڈے اس کے ارد گرد تھا۔\n18۔ انہوں نے جنوبی جانب، پانچ سو ریڈز، کو ناپنے والے ریڈ سے ناپا۔\n19۔ وہ مغربی جانب مڑا، {اور} ناپنے والے ریڈ سے پانچ سو ریڈز ناپے۔\n20۔ اس نے اسے چار اطراف سے ناپا: اس کے گرد ایک دیوار تھی، پانچ سو ریڈز لمبی اور پانچ سو چوڑی، تاکہ مقدس مقام اور مقدس جگہ کے درمیان فرق بن سکے۔","1۔ اس کے بعد اس نے مجھے دروازے تک پہنچایا، {حتیٰ کہ} وہ دروازہ جو مشرق کی طرف دیکھتا ہے:\n2۔ اور دیکھو، اسرائیل کے خدا کی شان مشرق کے راستے سے آئی: اور اس کی آواز {تھی} جیسے کئی پانیوں کی آواز: اور زمین اس کی شان سے چمک اٹھی۔\n3۔ اور {یہ} اس خواب کی شکل کے مطابق تھا جو میں نے دیکھا، {حتی} اس خواب کے مطابق جو میں نے دیکھا جب میں شہر کو تباہ کرنے آیا تھا: اور وہ خواب {تھا} جیسا کہ میں نے دریائے چبار کے کنارے دیکھا؛ اور میں اپنے چہرے کے بل گر گیا۔ {جب...: یا، جب میں پیش گوئی کرنے آیا کہ شہر تباہ ہو جائے گا}\n4۔ اور خداوند کی شان اس دروازے کے راستے سے گھر میں داخل ہوئی جس کا منظر مشرق کی طرف ہے۔\n5۔ تو روح نے مجھے اٹھایا اور اندرونی صحن میں لے آیا؛ اور دیکھو، خداوند کی شان نے گھر کو بھر دیا۔\n6۔ اور میں نے سنا {اسے} گھر سے مجھ سے بات کر رہا تھا؛ اور وہ آدمی میرے ساتھ کھڑا رہا۔\n7۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، میرے تخت کی جگہ، اور میرے قدموں کے تلووں کی جگہ، جہاں میں ہمیشہ کے لیے بنی اسرائیل کے درمیان رہوں گا، اور میرا مقدس نام، اسرائیل کا گھر نہ تو ان کے لیے اور نہ ہی ان کے بادشاہوں کو اپنی بدکاری سے ناپاک نہیں کرے گا،  نہ ہی ان کے بادشاہوں کی لاشوں سے جو ان کے اعلیٰ عہدوں پر تھے۔\n8۔ جب انہوں نے میرے دروازے کے پاس اپنی دہلیز رکھی، میرے ستونوں کے پاس اپنی جگہ بنائی، اور میرے اور ان کے درمیان دیوار قائم کی، تو انہوں نے میرے مقدس نام کو اپنی گناہوں سے بھی آلودہ کیا: اسی لیے میں نے انہیں اپنے غصے میں کھا لیا۔ {اور...: یا، کیونکہ میرے اور ان کے درمیان صرف ایک دیوار تھی}\n9۔ اب انہیں اپنی بدکاری اور اپنے بادشاہوں کی لاشیں مجھ سے دور رکھ دو، اور میں ہمیشہ ان کے درمیان رہوں گا۔\n10۔ اے انسان کے بیٹے، یہ گھر اسرائیل کے خاندان کو دکھاؤ تاکہ وہ اپنی گناہوں پر شرمندہ ہوں: اور وہ نمونہ ناپ لیں۔ {پیٹرن: یا، مجموعہ، یا، نمبر}\n11۔ اور اگر وہ اپنے کیے ہوئے تمام کاموں پر شرمندہ ہوں، تو انہیں گھر کی شکل، اس کا انداز، اس کے باہر جانے کے طریقے، اس کے آنے کے طریقے، اور اس کے تمام احکام اور اس کے تمام قوانین دکھاؤ، اور ان کے سامنے اسے لکھو،  تاکہ وہ اس کی پوری شکل اور اس کے تمام احکامات کو برقرار رکھ سکیں اور انہیں پورا کریں۔\n12. یہ گھر کا قانون ہے؛ پہاڑ کی چوٹی پر اس کی پوری حد {انتہائی مقدس} ہوگی۔ دیکھو، یہ گھر کا قانون ہے۔\n13. اور یہ {ہیں} قربان گاہ کے پیمائشیں کیوبٹس کے بعد: کیوبٹ {ایکوبٹ} اور ایک ہاتھ چوڑا ہے؛ یہاں تک کہ نیچے کا حصہ بھی ایک کیوبٹ ہوگا، اور چوڑائی ایک کیوبٹ، اور اس کے کنارے سے اس کے گرد ایک اسپین ہوگا: اور یہ قربان گاہ کی اونچی جگہ ہوگی۔ {نیچے: عبرانی۔ چھاتی} {ایج: عبرانی لپ}\n14۔ اور نیچے {اوپر} زمین {even} سے نیچے کی نشست {ہوگا} دو کیوبٹ، اور چوڑائی ایک کیوبٹ ہوگی؛ اور چھوٹے بستی {even} سے بڑے سیٹل {چار کیوبٹ} ہوں گے، اور چوڑائی {ایک} کیوبٹ ہوگی۔\n15۔ تو قربان گاہ چار کیوبٹس پر مشتمل ہوگی؛ اور قربان گاہ سے اوپر چار سینگ ہوں گے۔ {قربان گاہ (پہلا): عبرانی۔ ہارل، یعنی خدا کا پہاڑ} {قربان گاہ (دوسرا): عبرانی۔ ایریل، یعنی خدا کا شیر}\n16. اور قربان گاہ بارہ {کیوبٹ} لمبا، بارہ چوڑا، اس کے چار مربعوں میں مربع ہوگا۔\n17۔ اور اس کے چار مربعوں میں چودہ {کیوبٹ} لمبا اور چودہ چوڑا ہوگا؛ اور اس کے گرد سرحد {آدھا کیوبٹ ہوگی}؛ اور اس کے نیچے تقریبا ایک کیوبٹ ہوگا؛ اور اس کی سیڑھیاں مشرق کی طرف دیکھیں گی۔\n18۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، خداوند خدا یہ فرماتا ہے؛ یہ {ہیں} قربان گاہ کے اس دن کے احکامات جب وہ اسے بنائیں گے، اس پر جلانے کی نذرانہ پیش کرنے اور اس پر خون چھڑکنے کے لیے۔\n19۔ اور تم کاہنوں کو وہ لاوی دو جو زادوک کی نسل سے ہیں، جو میرے پاس آتے ہیں تاکہ میری خدمت کریں، خداوند خدا فرماتا ہے، ایک نوجوان بیل گناہ کی قربانی کے طور پر۔\n20۔ اور تم اس کا خون لے کر اس کے چار سینگوں پر، تہہ کے چاروں کونوں پر، اور اس کے گرد کے کنارے پر لگاؤ: یوں اسے صاف اور پاک کرو۔\n21۔ تم گناہ کی قربانی کا بیل بھی لو گے، اور وہ اسے گھر کی مقررہ جگہ پر، بغیر مقدس مقام کے جلا دے گا۔\n22۔ اور دوسرے دن تم گناہ کی قربانی کے بدلے بکریوں کے بچے کو بے داغ پیش کرو گے؛ اور وہ قربان گاہ کو صاف کریں گے، جیسے انہوں نے بیل سے صاف کیا۔\n23۔ جب تم صفائی ختم کر لو، تو تم ایک بے داغ ننھا بیل اور ریوڑ سے ایک بلا داغ مینڈھا پیش کرو گے۔\n24۔ اور تم انہیں خداوند کے سامنے پیش کرو گے، اور کاهن ان پر نمک ڈالیں گے، اور وہ انہیں خداوند کے سامنے جلنے کی قربانی کے طور پر پیش کریں گے۔\n25۔ سات دن تم ہر دن ایک بکری گناہ کی قربانی کے لیے تیار کرو گے: وہ ایک نوجوان بیل اور ریوڑ سے ایک مینڈھا بھی بغیر کسی داغ کے تیار کریں گے۔\n26۔ سات دن وہ قربان گاہ کو صاف کریں گے اور اسے پاک کریں گے؛ اور وہ خود کو مقدس کریں گے۔ {تقدیس...: عبرانی۔ ان کے ہاتھ بھرو}\n27۔ اور جب یہ دن ختم ہو جائیں گے، تو آٹھویں دن اور اس کے بعد پادری آپ کی سلائی کی قربانیاں قربان گاہ پر پیش کریں گے، اور آپ کی صلح کی نذرانے پیش کریں گے؛ اور میں تمہیں قبول کروں گا، خداوند خدا فرماتا ہے۔ {امن...: یا، نذرانے کا شکر}","1۔ پھر اس نے مجھے اس دروازے کی طرف لے آیا جو باہر کی طرف مزار کی طرف ہے اور مشرق کی طرف دیکھتا ہے؛ اور یہ {تھا} بند تھا۔\n2۔ پھر خداوند نے مجھ سے کہا؛ یہ دروازہ بند ہوگا، اسے نہیں کھولا جائے گا، اور کوئی شخص اس سے داخل نہیں ہو سکتا؛ کیونکہ خداوند، اسرائیل کا خدا، اس کے ذریعے داخل ہوا ہے، اس لیے یہ بند ہو جائے گا۔\n3. {یہ شہزادے کے لیے ہے}؛ شہزادہ، وہ اس میں بیٹھ کر خداوند کے سامنے روٹی کھائے گا؛ وہ {اس} دروازے کے برآمدے سے داخل ہوگا، اور اسی راستے سے باہر جائے گا۔\n4۔ پھر اس نے مجھے گھر کے سامنے شمالی دروازے کی طرف لے آیا، اور میں نے دیکھا، اور دیکھتے ہوئے خداوند کی شان خداوند کے گھر کو بھر دی، اور میں اپنے چہرے پر گر پڑا۔\n5۔ اور خداوند نے مجھ سے کہا، اے انسان کے بیٹے، اچھی طرح دیکھو، اور اپنی آنکھوں سے دیکھو، اور اپنے کانوں سے وہ سب کچھ سن جو میں تم سے خداوند کے گھر کے تمام احکامات اور ان کے تمام قوانین کے بارے میں کہتا ہوں؛ اور ہر بار عبادت گاہ کے باہر جانے کے ساتھ گھر میں داخلے کو اچھی طرح نوٹ کریں۔ {اچھی طرح مارک: عبرانی۔ اپنا دل سیٹ کرو} {اچھی طرح مارک: عبرانی۔ اپنا دل سیٹ کرو}\n6۔ اور تم باغیوں سے کہو {حتیٰ کہ} کہ اسرائیل کے گھر سے بھی، خداوند خدا یہ فرماتا ہے؛ اے اسرائیل کے گھرانہ، تمہیں اپنی تمام گناہوں سے کافی ہو،\n7۔ اس میں کہ تم نے میرے مقدس مقام میں اجنبیوں کو لایا ہے، جن کے دل میں ختنہ نہیں ہے، اور جسم میں بھی نہیں، تاکہ وہ میرے مقدس مقام میں ہوں، اسے آلودہ کریں، حتیٰ کہ میرے گھر کو بھی، جب تم میری روٹی، چربی اور خون پیش کرتے ہو، اور انہوں نے تمہارے تمام گناہوں کی وجہ سے میرا عہد توڑ دیا۔ {اجنبی: عبرانی۔ ایک اجنبی کے بچے}\n8۔ اور تم نے میری مقدس چیزوں کی حفاظت نہیں کی، بلکہ میرے مقدس مقام میں میرے محافظوں کو اپنے لیے مقرر کیا ہے۔ {میری ذمہ داری: یا، میرا وارڈ، یا، آرڈیننس}\n9۔ خداوند خدا یہ فرماتا ہے؛ کوئی اجنبی، جو دل میں ختنہ نہ ہوا ہو، اور جسم میں غیر ختنہ شدہ ہو، میرے مقدس مقام میں داخل نہیں ہو سکتا، کسی بھی اجنبی کا جو بنی اسرائیل میں سے ہو۔\n10۔ اور وہ لاوی جو مجھ سے دور چلے گئے، جب اسرائیل بھٹک گئے، اور جو اپنے بتوں کے پیچھے مجھ سے بھٹک گئے؛ وہ اپنی گناہوں کو بھی برداشت کریں گے۔\n11۔ پھر بھی وہ میرے مزار میں خادم ہوں گے، گھر کے دروازوں پر ذمہ داری سنبھالیں گے، اور گھر کی خدمت کریں گے: وہ لوگوں کے لیے قربانی اور قربانی قربان کریں گے، اور ان کے سامنے کھڑے ہو کر ان کی خدمت کریں گے۔\n12۔ کیونکہ انہوں نے اپنے بتوں کے سامنے ان کی خدمت کی، اور اسرائیل کے گھر کو بدکاری میں مبتلا کر دیا؛ اسی لیے میں نے ان کے خلاف ہاتھ اٹھا دیا ہے، خداوند خدا فرماتا ہے، اور وہ اپنی گناہوں کو برداشت کریں گے۔ {وجہ سے...: عبرانی۔ جو ظلم کی رکاوٹ کے لیے تھے، وغیرہ}\n13۔ اور وہ میرے قریب نہیں آئیں گے کہ میرے لیے پادری کا کام کریں، نہ ہی میری مقدس چیزوں کے قریب آئیں، سب سے مقدس جگہ، بلکہ وہ اپنی شرمندگی اور گناہوں کو برداشت کریں گے جو انہوں نے کیے ہیں۔\n14۔ لیکن میں انہیں گھر کے نگہبان بنا دوں گا، اس کی تمام خدمات کے لیے، اور اس میں ہونے والے تمام کاموں کے لیے۔\n15. لیکن وہ کاہن، لاوی، زادوک کے بیٹے، جنہوں نے میرے مقدس مقام کی حفاظت کی جب بنی اسرائیل مجھ سے بھٹک گئے، وہ میرے قریب آئیں گے تاکہ میری خدمت کریں، اور وہ میرے سامنے کھڑے ہو کر مجھے چربی اور خون پیش کریں گے، خداوند خدا فرماتا ہے:\n16۔ وہ میرے مقدس مقام میں داخل ہوں گے، اور میرے دسترخوان کے قریب آئیں گے، میری خدمت کریں گے، اور میری ذمہ داری سنبھالیں گے۔\n17۔ اور یہ ہو جائے گا کہ جب وہ اندرونی صحن کے دروازے سے داخل ہوں گے، تو انہیں لینن کے کپڑے پہنائے جائیں گے؛ اور جب تک وہ اندرونی صحن کے دروازوں اور اندر خدمت کر رہے ہوں، ان پر اون نہیں آئے گی۔\n18۔ ان کے سر پر لینن کے ٹوپیاں ہوں گی، اور ان کی کمر پر لینن بریچز ہوں گے؛ وہ خود کو کسی بھی ایسی چیز سے نہیں ڈھالیں گے جو پسینہ پیدا کرے۔ {ساتھ...: یا، پسینے میں بھیگے ہوئے مقامات پر: عبوری۔ اندر، یا پسینے کے ساتھ}\n19۔ اور جب وہ مکمل دربار میں نکلیں، {حتیٰ کہ} کہ عوام کے سامنے مکمل عدالت میں بھی، تو وہ اپنے کپڑے اتاریں گے جن میں انہوں نے خدمت کی تھی، اور انہیں مقدس کمروں میں لٹا دیں گے، اور دیگر کپڑے پہنیں گے؛ اور وہ لوگوں کو اپنے کپڑوں سے پاک نہیں کریں گے۔\n20۔ نہ وہ اپنے سر منڈوا سکتے ہیں، نہ اپنے بال لمبے ہونے دیں گے؛ وہ صرف اپنے سر چیک کریں گے۔\n21. نہ ہی کوئی پادری جب اندرونی صحن میں داخل ہو تو شراب نہیں پئے گا۔\n22۔ نہ تو وہ اپنی بیوہ کو بیوہ بنائیں گے، نہ ہی کسی کو جو نکالے گئے ہوں، بلکہ وہ اسرائیل کے خاندان کی دوشیزیوں یا اس بیوہ کو لیں گے جس کا پہلے کوئی پادری تھا۔ {put...: عبدی۔ آگے دھکیلیں} {جس نے...: عبرانی ایک پادری کی طرف سے}\n23۔ اور وہ میرے لوگوں کو مقدس اور ناپاک میں فرق سکھائیں گے، اور انہیں ناپاک اور پاک میں فرق کرنے پر مجبور کریں گے۔\n24۔ اور تنازعے میں وہ فیصلہ کریں گے؛ {اور} وہ میرے فیصلوں کے مطابق فیصلہ کریں گے: اور وہ میرے تمام اسمبلیوں میں میرے قوانین اور قوانین کو برقرار رکھیں گے؛ اور وہ میرے سبت کو مقدس بنائیں گے۔\n25۔ اور وہ کسی مردہ شخص کے لیے خود کو ناپاک کرنے نہیں آئیں گے: سوائے باپ، ماں، بیٹے، بیٹے، بھائی یا بہن کے لیے جس کا شوہر نہ ہو، وہ خود کو ناپاک کر سکتے ہیں۔\n26۔ اور جب وہ پاک ہو جائے گا، تو اس کے سات دن شمار ہوں گے۔\n27. اور جس دن وہ مقدس مقام میں جائے گا، اندرونی صحن میں، عبادت کے لیے، وہ اپنا گناہ کی قربانی دے گا، خداوند خدا فرماتا ہے۔\n28۔ اور یہ ان کے لیے وراثت ہوگی: میں ان کی وراثت ہوں: اور تم انہیں اسرائیل میں کوئی ملکیت نہیں دو گے: میں ان کی ملکیت ہوں۔\n29۔ وہ گوشت کی قربانی، گناہ کی قربانی، اور ناجائز قربانی کھائیں گے؛ اور اسرائیل میں ہر وقف چیز ان کی ہوگی۔ {وقف: یا، وقف شدہ}\n30۔ اور سب سے پہلے سب سے پہلے پھل، اور سب کی ہر قربانی، ہر قسم کی قربانی کاهن کی ہوگی: تم بھی پادری کو اپنی پہلی رقم دو تاکہ وہ برکت تمہارے گھر میں آرام کرے۔ {اور پہلا: یا، اور سردار}\n31۔ پادری کسی بھی ایسی چیز کو نہیں کھائیں گے جو خود سے مردہ ہو یا پھٹی ہو، چاہے وہ پرندہ ہو یا جانور۔","1۔ مزید برآں، جب آپ زمین کو وراثت کے لیے قرعہ اندازی سے تقسیم کریں گے، تو آپ خداوند کے لیے ایک مقدس حصہ پیش کریں گے: لمبائی پانچ ہزار بیس ہزار گھاس کے پتے، اور چوڑائی دس ہزار ہوگی۔ یہ {ہوگی} اس کے ارد گرد کی تمام سرحدوں میں مقدس ہوگی۔ {جب...: عبرانی۔ جب تم زمین کو گرا دو} {ایک مقدس...: عبرانی مقدس مقام}\n2۔ اس میں سے عبادت گاہ کے لیے پانچ سو {لمبائی} ہوگی، اور پانچ سو {چوڑائی}، چوکور چاروں طرف ہوں گی؛ اور اس کے مضافات کے لیے پچاس کیوبٹس کے ارد گرد بھی۔ {مضافات: یا، خالی مقامات}\n3۔ اور اس پیمانے سے تم پانچ بیس ہزار لمبائی اور چوڑائی دس ہزار کے برابر ناپو گے: اور اس میں مقدس مقام {اور} سب سے مقدس {جگہ} ہوگی۔\n4۔ زمین کا مقدس حصہ پادریوں کے لیے ہوگا، مقدس مقام کے وزیر، جو رب کی خدمت کے لیے قریب آئیں گے: اور یہ ان کے گھروں کے لیے جگہ اور مقدس جگہ ہوگی۔\n5۔ اور پانچ ہزار لمبائی اور دس ہزار چوڑائی، لاویوں کو، جو گھر کے وزیر ہیں، اپنے لیے بیس کمروں کی ملکیت کے طور پر رکھیں گے۔\n6۔ اور تم شہر کی ملکیت جو پانچ ہزار چوڑی اور پانچ ہزار لمبی ہے، مقدس {حصہ} کی قربانی کے خلاف مقرر کرو: یہ پورے اسرائیل کے گھرانے کے لیے ہوگی۔\n7۔ اور ایک {حصہ} شہزادے کے لیے مقدس {حصہ} کی قربانی کے ایک طرف اور دوسری طرف ہوگا، اور شہر کی ملکیت کے لیے، مقدس {حصہ} کی قربانی سے پہلے، اور شہر کی ملکیت سے پہلے، مغرب کی طرف مغرب کی طرف، اور مشرق کی طرف مشرق کی طرف:  اور لمبائی {ہوگی} ایک حصے کے ساتھ، مغربی سرحد سے مشرقی سرحد تک۔\n8۔ زمین میں اس کی ملکیت اسرائیل میں ہوگی: اور میرے شہزادے میرے لوگوں پر ظلم نہیں کریں گے؛ اور باقی زمین وہ اپنے قبائل کے مطابق اسرائیل کے خاندان کو دیں گے۔\n9۔ خداوند خدا یہ فرماتا ہے؛ اے اسرائیل کے شہزادوں، یہ کافی ہے: تشدد اور لوٹ مار کو ختم کرو، اور انصاف و انصاف نافذ کرو، اپنی سزا میرے لوگوں سے دور کرو، خداوند خدا فرماتا ہے۔ {ایگزکشنز: عبرانی۔ اخراج\n10۔ تمہیں عادل توازن ملے گا، ایک ایفہ منصفانہ ہوگا، اور ایک منصفانہ غسل ملے گا۔\n11۔ ایفا اور غسل ایک ہی پیمانے کے ہوں گے، تاکہ غسل میں ہومر کا دسواں حصہ ہو، اور ایفا ہومر کا دسواں حصہ: اس کی مقدار ہومر کے بعد ہوگی۔\n12۔ اور شیکل بیس گرہ ہوگا: بیس شیکل، پانچ اور بیس شیکل، پندرہ شیکل، تمہاری مانی ہوگی۔\n13۔ یہ وہ قربانی ہے جو تم پیش کرو گے؛ گندم کے ہومر کے ایفا کا چھٹا حصہ، اور جو کے ہومر کے ایفا کا چھٹا حصہ:\n14۔ تیل کے غسل کے حکم کے بارے میں، تیل کے غسل میں، {تم کور سے غسل کا دسواں حصہ پیش کرو گے، {جو دس حمام کا ہومر ہے}؛ دس غسل خانوں کے لیے ایک ہومر:\n15۔ اور ریوڑ میں سے ایک بھیڑ، دو سو میں سے، اسرائیل کے موٹے چراگاہوں سے؛ گوشت کی قربانی، اور جلنے کی قربانی، اور صلح کی قربانیوں کے لیے، ان کے لیے صلح کے لیے، خداوند خدا فرماتا ہے۔ {لیمب: یا، بچے} {امن...: یا، نذرانے کا شکر}\n16۔ زمین کے تمام لوگ یہ قربانی اسرائیل کے شہزادے کے لیے دیں گے۔ {ہوگا...: عبرانی will be for} {for: or, with}\n17۔ اور شہزادے کی ذمہ داری ہوگی کہ وہ تہواروں، نئے چاندوں میں، اور سبت کے دنوں میں، اسرائیل کے گھر کی تمام تقریبات میں جلنے کی قربانیاں، گوشت کی قربانیاں، اور شراب کی قربانیاں پیش کرے: وہ گناہ کی قربانی، گوشت کی قربانی، سلائی کی قربانی، اور صلح کی قربانیاں تیار کرے گا۔  تاکہ اسرائیل کے گھر کے لیے مصالحت کی جا سکے۔ {امن...: یا، نذرانے کا شکر}\n18. خداوند خدا یہ فرماتا ہے؛ پہلے مہینے میں، مہینے کے پہلے دن، تم ایک نوجوان بیل کو بغیر کسی داغ کے لے کر مقدس مقام کو صاف کرو گے:\n19۔ اور پادری گناہ کی قربانی کا خون لے کر گھر کے ستونوں، قربان گاہ کے چاروں کونوں پر، اور اندرونی صحن کے دروازے کے ستونوں پر رکھے گا۔\n20۔ اور اسی طرح تم مہینے کے ساتویں دن ہر اس شخص کے لیے کرو گے جو غلطی کرے، اور جو سادہ ہے: اسی طرح تم گھر کو صلح کرو گے۔\n21۔ پہلے {مہینے} میں، مہینے کے چودہویں دن پر، آپ کو فسح منایا جائے گا، جو سات دن کا تہوار ہے؛ بغیر خمیر کی روٹی کھائی جائے گی۔\n22۔ اور اس دن شہزادہ اپنے اور ملک کے تمام لوگوں کے لیے گناہ کی قربانی کے لیے ایک بیل تیار کرے گا۔\n23۔ اور تہوار کے سات دن وہ خداوند کے لیے ایک سلائی کی قربانی تیار کرے گا، سات بیل اور سات بے داغ مینڈھے روزانہ سات دنوں میں؛ اور روزانہ بکریوں کا ایک بچہ گناہ کی قربانی کے لیے۔\n24۔ اور وہ بیل کے لیے ایفاہ اور مینڈھے کے لیے ایفاہ اور ایفا کے لیے تیل کا گوشت کی نذرانہ تیار کرے گا۔\n25۔ ساتویں مہینے میں، مہینے کے پندرہویں دن پر، وہ سات دنوں کے تہوار میں ایسا ہی کرے گا، گناہ کی قربانی، جلنے کی قربانی، گوشت کی نذرانہ کے مطابق، اور تیل کے مطابق۔","1۔ خداوند خدا یہ فرماتا ہے؛ اندرونی صحن کا دروازہ جو مشرق کی طرف دیکھتا ہے، چھ کام کے دنوں کے لیے بند کیا جائے گا؛ لیکن سبت کو یہ کھولا جائے گا، اور نئے چاند کے دن کھولا جائے گا۔\n2۔ اور شہزادہ اس دروازے کے برآمدے سے اندر جائے گا، اور دروازے کے ستون کے پاس کھڑا ہوگا، اور پادری اپنی جلنے کی قربانی اور صلح کی نذرانے تیار کریں گے، اور وہ دروازے کے دروازے پر عبادت کرے گا: پھر وہ باہر جائے گا؛ لیکن دروازہ شام تک بند نہیں ہوگا۔\n3۔ اسی طرح زمین کے لوگ اس دروازے کے دروازے پر خداوند کے سامنے سبت اور نئے چاند میں عبادت کریں گے۔\n4۔ اور وہ سلائی کی قربانی جو شہزادہ سبت کے دن خداوند کو پیش کرے گا {وہ ہوگا} چھ بلا داغ بھیڑ اور ایک بے داغ مینڈھا۔\n5۔ اور گوشت کی قربانی ایک مینڈھے کے لیے ایفا ہوگی، اور گوشت کی قربانی بھیڑوں کے لیے جتنا وہ دے سکتا ہے، اور ایک ایفاہ کے لیے ایک ہین تیل۔ {جیسا کہ وہ...: عبرانی۔ اس کے ہاتھ کا تحفہ}\n6۔ اور نئے چاند کے دن ایک نوجوان بیل ہوگا جس پر کوئی داغ نہیں، اور چھ بھیڑ، اور ایک مینڈھا: وہ بے داغ ہوں گے۔\n7۔ اور وہ گوشت کی قربانی تیار کرے گا، بیل کے لیے ایفا، مینڈھے کے لیے ایفا، اور بھیڑوں کے لیے جیسا اس کا ہاتھ پہنچے گا، اور ایفا کے لیے ایک ہین تیل تیار کرے گا۔\n8۔ اور جب شہزادہ اندر آئے گا، تو وہ اس دروازے کے برآمدے سے داخل ہوگا، اور وہ اس کے راستے سے جائے گا۔\n9۔ لیکن جب زمین کے لوگ مقدس تہواروں میں خداوند کے سامنے آئیں گے، تو جو شمالی دروازے سے عبادت کے لیے داخل ہوگا وہ جنوبی دروازے سے باہر جائے گا؛ اور جو جنوبی دروازے سے داخل ہوگا وہ شمالی دروازے کے راستے سے باہر جائے گا: وہ اس دروازے سے واپس نہیں آئے گا جہاں سے آیا تھا، بلکہ اس کے خلاف جائے گا۔\n10۔ اور ان کے درمیان موجود شہزادہ، جب وہ اندر جائیں گے، تو اندر جائے گا؛ اور جب وہ نکلیں گے، تو نکلیں گے۔\n11۔ اور تہواروں اور تقریبات میں گوشت کی قربانی بیل کے لیے ایفاہ، مینڈھے کے لیے ایفاہ، اور بھیڑوں کے لیے جتنا وہ دے سکتا ہے، اور ایفاہ کے لیے ہین تیل ہوگا۔\n12۔ اب جب شہزادہ رضاکارانہ طور پر خداوند کے سامنے سلائی کی قربانی یا صلح کی نذرانے تیار کرے گا، تو پھر وہ دروازہ کھولے گا جو مشرق کی طرف دیکھتا ہے، اور وہ اپنی جلنے کی قربانی اور صلح کی نذرانے تیار کرے گا، جیسا کہ اس نے سبت کے دن کیا تھا: پھر وہ باہر جائے گا؛ اور اس کے جانے کے بعد {ایک} دروازہ بند کر دے گا۔\n13۔ تو روزانہ خداوند کے لیے ایک سجلنے کی قربانی تیار کرو گے، پہلے سال کے ایک بے داغ بھیڑ کا: تو اسے ہر صبح تیار کرو گے۔ {میں سے...: عبرانی۔ اپنے سال کا بیٹا} {ہر...: عبرانی صبح بہ صبح}\n14۔ اور تم ہر صبح اس کے لیے گوشت کی قربانی تیار کرو، ایفاہ کا چھٹا حصہ، اور تیل کا تیسرا حصہ، تاکہ باریک آٹے کے ساتھ نرم کیا جا سکے؛ ایک گوشت کی قربانی جو ہمیشہ خداوند کے لیے دائمی حکم کے تحت ہے۔\n15. یوں وہ ہر صبح بھیڑ کے بکری، گوشت کی قربانی اور تیل تیار کریں گے {ایک مسلسل جلنے والی قربانی کے لیے﴾۔\n16. خداوند خدا یہ فرماتا ہے؛ اگر شہزادہ اپنے بیٹوں میں سے کسی کو تحفہ دے تو اس کی وراثت اس کے بیٹوں کی ہوگی؛ یہ وراثت کے ذریعے ان کی ملکیت ہوگی۔\n17۔ لیکن اگر وہ اپنی وراثت کا تحفہ اپنے کسی خادم کو دے دے، تو وہ سال آزادی تک اس کا ہوگا؛ اس کے بعد یہ شہزادے کو واپس مل جائے گا: لیکن اس کی وراثت ان کے بیٹوں کی ہوگی۔\n18۔ مزید برآں، شہزادہ عوام کی میراث کو ظلم کے ذریعے نہیں لے گا تاکہ انہیں ان کی ملکیت سے نکال دے؛ {لیکن} وہ اپنے بیٹوں کی وراثت اپنی ملکیت سے دے گا: تاکہ میرے لوگ ہر آدمی کو اس کی ملکیت سے نہ بکھرائیں۔\n19۔ جب اس نے مجھے دروازے کے کنارے پر واقع داخلی دروازے سے گزارا، اور وہ پادریوں کے مقدس کمروں میں لے گیا، جو شمال کی طرف دیکھتا تھا: اور دیکھو، دونوں طرف مغرب کی طرف ایک جگہ تھی۔\n20۔ پھر اس نے مجھ سے کہا، یہ وہ جگہ ہے جہاں پادری گناہ کی قربانی اور گناہ کی قربانی ابالیں گے، جہاں وہ گوشت کی نذرانہ بنائیں گے؛ کہ وہ انہیں مکمل دربار میں نہ لے جائیں، لوگوں کو پاک کرنے کے لیے۔\n21۔ پھر اس نے مجھے مکمل دربار میں لے جایا اور مجھے صحن کے چاروں کونوں سے گزرنے پر مجبور کیا؛ اور دیکھیں، عدالت کے ہر کونے میں ایک عدالت تھی۔ {ہر...: عبرانی میں۔ کورٹ کے کونے میں کورٹ، اور کورٹ کے کونے میں کورٹ}\n22۔ صحن کے چاروں کونوں میں چالیس {کیوبٹ} لمبے اور تیس چوڑے صحنیں جڑے ہوئے تھے: یہ چار کونے ایک ہی پیمانے کے تھے۔ {جوڑا گیا: یا، چمنیوں سے بنایا گیا} {کونے تھے...: عبرانی۔ کونے میں پھنس جانا، وغیرہ}\n23. اور {وہاں ایک قطار {عمارتوں کی} تھی جو ان کے ارد گرد تھی، ان کے ارد گرد چار، اور {یہ تھی} قطاروں کے نیچے ابلنے والی جگہوں سے بنی ہوئی تھی۔\n24۔ پھر اس نے مجھ سے کہا، یہ وہ جگہیں ہیں جو ابلتی ہیں، جہاں گھر کے خادم لوگوں کی قربانی ابالیں گے۔","1۔ بعد میں وہ مجھے دوبارہ گھر کے دروازے تک لے آیا؛ اور دیکھو، گھر کے دہانے کے نیچے سے مشرق کی طرف پانی بہنے لگا: کیونکہ گھر کا اگلا حصہ مشرق کی طرف کھڑا تھا، اور پانی گھر کے دائیں طرف، قربان گاہ کے جنوب {طرف} سے نیچے آ رہا تھا۔\n2۔ پھر اس نے مجھے شمال کی طرف دروازے کے راستے سے ہٹایا، اور مجھے اس راستے سے لے گیا جو مشرق کی طرف دیکھتا ہے؛ اور دیکھو، دائیں طرف پانی ختم ہو گیا۔\n3۔ اور جب وہ آدمی جس کے ہاتھ میں رسی تھی، مشرق کی طرف روانہ ہوا، اس نے ہزار کیوبٹ ناپے، اور اس نے مجھے پانیوں سے گزارا؛ پانی ٹخنوں تک تھا۔ {پانی تھے...: عبرانی۔ ٹخنوں کے پانی}\n4۔ پھر اس نے ہزار ناپے اور مجھے پانیوں سے گزارا؛ پانی گھٹنوں تک گر چکا تھا۔ پھر اس نے ہزار ناپے، اور مجھے اندر لے آیا؛ پانی {کمر تک} تھا۔\n5۔ اس کے بعد اس نے ایک ہزار کی پیمائش کی؛ {اور یہ ایک ایسا دریا تھا} جسے میں عبور نہیں کر سکتا تھا: کیونکہ پانی بلند ہو چکا تھا، تیرنے کے لیے پانی، ایک ایسا دریا جسے عبور نہیں کیا جا سکتا تھا۔ {پانی میں...: عبرانی تیراکی کے پانی}\n6۔ اور اس نے مجھ سے کہا، اے انسان کے بیٹے، کیا تم نے یہ دیکھا؟ پھر اس نے مجھے لایا، اور مجھے دریا کے کنارے واپس لے آیا۔\n7۔ جب میں واپس آیا، تو دیکھو، دریا کے کنارے ایک طرف اور دوسری طرف بہت سے درخت تھے۔ {بینک: عبوری۔ لپ}\n8۔ پھر اس نے مجھ سے کہا، یہ پانی مشرقی علاقے کی طرف نکلتے ہیں، صحرا میں نیچے جاتے ہیں، اور سمندر میں جاتے ہیں: {جو سمندر میں نکالا جائے گا، پانی شفا پائے گا۔' {صحرا: یا، سادہ}\n9۔ اور یہ ہو جائے گا، {کہ} ہر وہ چیز جو زندہ ہے، جو حرکت کرتی ہے، جہاں بھی دریا آئیں گے، وہ زندہ رہے گی: اور وہاں مچھلیوں کی بہت بڑی تعداد ہوگی، کیونکہ یہ پانی وہاں آئیں گے: کیونکہ وہ شفا پائیں گے؛ اور ہر چیز وہاں زندہ رہے گی جہاں دریا آتا ہے۔ {ریورز: عبرانی۔ ٹو ریورز}\n10۔ اور یہ ہو جائے گا کہ ماہی گیر اس پر اینگیڈی سے اینگلیم تک کھڑے ہوں گے؛ وہ جال بچھانے کی جگہ ہوں گے؛ ان کی مچھلیاں اپنی نوع کے مطابق ہوں گی، جیسے عظیم سمندر کی مچھلیاں، بہت سے مچھلیوں سے زیادہ۔\n11۔ لیکن اس کے کیچڑ والے مقامات اور اس کے مارش شفا نہیں پا سکتے؛ انہیں نمک میں دیا جائے گا۔ {نہیں...: یا، اور وہ جو شفا نہیں پائے گا}\n12۔ اور دریا کے کنارے، اس کنارے اور اس طرف، گوشت کے لیے تمام درخت اگیں گے، جن کے پتے مرجھائے نہیں جائیں گے اور نہ ہی اس کا پھل کھائے گا، وہ اس کے مہینوں کے مطابق نیا پھل دے گا، کیونکہ ان کا پانی مقدس مقام سے نکلتا ہے، اور اس کا پھل گوشت کے لیے ہوگا،  اور اس کا پتہ دوا کے لیے۔ {بڑھے گا: عبرانی۔ اوپر آئے گا} {نیا: یا، پرنسپل} {دوا کے لیے: یا، زخموں اور زخموں کے لیے}\n13۔ خداوند خدا یہ فرماتا ہے؛ یہ سرحد ہوگی، جس کے تحت تم اسرائیل کے بارہ قبائل کے مطابق زمین کے وارث ہو گے: یوسف کے دو حصے ہوں گے۔\n14۔ اور تم اسے ایک ساتھ ساتھ وراثت میں پاؤ گے: {اس کے بارے میں} جو میں نے اپنے ہاتھ کو اٹھا کر تمہارے آباؤ اجداد کو دیا: اور یہ زمین تم پر وراثت کے طور پر ملے گی۔ {اٹھایا گیا...: یا، قسم کھایا}\n15۔ اور یہ زمین کی سرحد ہوگی جو شمال کی طرف ہے، عظیم سمندر سے، ہیتھلون کا راستہ، جب لوگ زیداد کی طرف جاتے ہیں؛\n16۔ حمتھ، بروتھا، سبریم، جو دمشق کی سرحد اور حماث کی سرحد کے درمیان واقع ہے؛ ہزارہٹیکون، جو ہاوران کے ساحل کے قریب واقع ہے۔ {Hazarhatticon: یا، درمیانی گاؤں}\n17۔ اور سمندر کی سرحد ہزارنان ہوگی، دمشق کی سرحد، اور شمال کی طرف شمال کی طرف، اور حمات کی سرحد۔ اور {یہ} شمالی طرف ہے۔\n18۔ اور مشرقی کنارہ کو تم حوران، دمشق، اور گلعاد سے، اور اسرائیل کی سرزمین سے اردن کے قریب، سرحد سے مشرقی سمندر تک ناپو گے۔ اور {یہ} مشرقی طرف ہے۔ {(حوران، دمشق، جلعاد، زمین سے): عبرانی۔ درمیان سے}\n19۔ اور جنوب کی طرف، تامار {حتی} سے قدیش میں جھگڑے کے پانیوں تک، دریا سے عظیم سمندر تک۔ اور یہ جنوب کی طرف ہے۔ {جھگڑا: یا، مریبہ} {دریا: یا، وادی} {جنوب کی طرف ہے: یا، جنوب کی طرف تیمان کی طرف}\n20۔ مغربی جانب بھی سرحد سے عظیم سمندر ہوگا، جب تک کہ کوئی آدمی حماث کے خلاف نہ آ جائے۔ یہ {ہے} مغربی طرف۔\n21. تو تم اس زمین کو اپنے اوپر اسرائیل کے قبائل کے مطابق تقسیم کرو گے۔\n22۔ اور یہ ہوگا کہ تم اسے قرعہ اندازی میں تقسیم کرو گے تاکہ تم اور اپنے درمیان رہنے والے اجنبیوں کے لیے وراثت حاصل کرو جو تم میں سے بچے پیدا کریں گے: اور وہ تمہارے لیے ہوں گے جیسے اسرائیل کے بچوں میں ملک میں پیدا ہوئے؛ وہ تمہارے ساتھ اسرائیل کے قبائل میں وراثت حاصل کریں گے۔\n23. اور یہ ہو جائے گا کہ جس قبیلے میں اجنبی قیام کرے گا، وہیں تم اسے اس کی میراث دو گے، خداوند خدا فرماتا ہے۔","1. اب یہ قبائل کے نام ہیں۔ شمالی سرے سے ہیتھلون کے راستے کے ساحل تک، جب آپ حمت، ہزارنان، دمشق کی سرحد شمال کی طرف جاتے ہیں، اور حماث کے ساحل تک جاتے ہیں؛ کیونکہ یہ اس کے مشرق اور مغرب کے اطراف ہیں؛ ایک {حصہ} ڈین۔ {ایک حصہ: عبرانی۔ ایک حصہ}\n2۔ اور دان کی سرحد کے پاس، مشرق سے مغرب کی طرف، آشر کے لیے ایک حصہ۔\n3۔ اور آشر کی سرحد کے قریب، مشرقی جانب سے مغرب کی طرف تک ایک {حصہ} نفتالی کے لیے۔\n4۔ اور نفتالی کی سرحد کے قریب، مشرق سے مغرب کی طرف مناسیہ کے لیے ایک {حصہ}۔\n5۔ اور منسی کی سرحد پر، مشرق سے مغرب کی طرف افرایم کے لیے ایک حصہ۔\n6۔ اور افرائیم کی سرحد کے پاس، مشرق سے مغرب کی طرف تک ایک {حصہ} روبن کے لیے۔\n7۔ اور روبن کی سرحد کے پاس، مشرق سے مغرب کی طرف ایک {حصہ} یہوداہ کے لیے۔\n8۔ اور یہوداہ کی سرحد کے پاس، مشرق سے مغرب کی طرف تک، وہ نذرانہ ہوگی جو تم پانچ اور بیس ہزار گھاس کی چوڑائی اور {دیگر} حصوں میں سے ایک کے برابر مشرقی جانب سے مغرب کی طرف پیش کرو گے: اور مقدس خانہ اس کے بیچ میں ہوگا۔\n9۔ جو قربانی آپ خداوند کو پیش کریں گے وہ پانچ ہزار لمبائی اور دس ہزار چوڑائی کی ہوگی۔\n10۔ اور ان کے لیے، {حتی} کاہنوں کے لیے بھی، {یہ} مقدس قربانی ہوگی؛ شمال کی طرف پانچ اور بیس ہزار لمبائی، مغرب کی طرف دس ہزار، اور مشرق کی طرف دس ہزار، اور جنوب کی طرف پانچ اور بیس ہزار لمبائی: اور خداوند کی مقدس جگہ اس کے بیچ میں ہوگی۔\n11۔ {یہ ان کاہنوں کے لیے ہوگا جو زادوک کے بیٹوں میں سے پاک ہیں؛ جنہوں نے میری ذمہ داری کو روکا، جو اسرائیل کے بچوں کے گمراہ ہونے پر گمراہ نہیں ہوئی، جیسا کہ لاوی گمراہ ہوئے۔ {یہ...: یا، مقدس حصہ کاہنوں کے لیے ہوگا} {چارج: یا، وارڈ، یا، آرڈیننس}\n12۔ اور یہ زمین کی قربانی جو پیش کی جائے گی، لاویوں کی سرحد پر ان کے لیے سب سے مقدس چیز ہوگی۔\n13۔ اور کاہنوں کی سرحد کے سامنے لاویوں کی لمبائی پانچ اور بیس ہزار اور چوڑائی دس ہزار ہوگی: تمام لمبائی پانچ بیس ہزار اور چوڑائی دس ہزار ہوگی۔\n14۔ اور وہ اسے نہ بیچیں گے، نہ تبادلہ کریں گے، اور نہ ہی زمین کے پہلے پھل بیچیں گے: کیونکہ یہ خدا کے لیے مقدس ہے۔\n15۔ اور جو پانچ ہزار پانچ ہزار کے مقابلے میں چوڑائی میں بچے ہیں، وہ شہر، رہائش اور مضافات کے لیے ایک ناپاک جگہ ہوں گے، اور شہر ان کے بیچ میں ہوگا۔\n16۔ اور یہ {اس کے پیمائش} ہوں گے؛ شمال کی طرف چار ہزار پانچ سو، اور جنوب کی طرف چار ہزار پانچ سو، مشرقی جانب چار ہزار پانچ سو، اور مغربی جانب چار ہزار پانچ سو۔\n17۔ اور شہر کے مضافات شمال کی طرف دو سو پچاس، جنوب کی طرف دو سو پچاس، اور مشرق کی طرف دو سو پچاس، اور مغرب کی طرف دو سو پچاس ہوں گے۔\n18۔ اور مقدس {حصہ} کی قربانی کے خلاف باقی ماندہ حصہ مشرق کی طرف دس ہزار اور مغرب کی طرف دس ہزار ہوگا؛ اور یہ مقدس {حصہ} کی قربانی کے خلاف ختم ہو جائے گا؛ اور اس میں اضافہ ان لوگوں کے لیے خوراک کے لیے ہوگا جو شہر کی خدمت کرتے ہیں۔\n19۔ اور جو لوگ شہر کی خدمت کریں گے، وہ اسرائیل کے تمام قبائل میں سے اس کی خدمت کریں گے۔\n20۔ تمام قربانی پانچ بیس ہزار بائی پانچ بیس ہزار ہوگی: تم مقدس قربانی چار چوکور کے ساتھ پیش کرو، شہر کی ملکیت کے ساتھ۔\n21۔ اور باقی ماندہ حصہ شہزادے کے لیے، مقدس قربانی کے ایک طرف اور دوسری طرف، اور شہر کی ملکیت کے لیے، قربانی کے پانچ اور بیس ہزار کے خلاف مشرقی سرحد پر، اور مغرب کی طرف پانچ اور بیس ہزار کے خلاف مغربی سرحد پر، شہزادے کے حصے کے مقابلے میں ہوگا:  اور یہ مقدس قربانی ہوگی؛ اور اس گھر کی مقدس جگہ اس کے بیچ میں ہوگی۔\n22. مزید برآں، لاویوں کی ملکیت سے، اور شہر کی ملکیت سے، {جو شہزادے کی ملکیت ہے} کے درمیان {میں}، یہوداہ کی سرحد اور بنیامین کی سرحد کے درمیان، شہزادے کے لیے ہوگا۔\n23۔ باقی قبائل کے لیے، مشرق سے مغرب کی طرف بنیامین {حصہ} رکھے گا۔ {ایک حصہ: عبرانی۔ ایک حصہ}\n24۔ اور بنیامین کی سرحد پر، مشرق سے مغرب کی طرف، شمعون {کو ایک {حصہ} ملے گا۔\n25۔ اور شمعون کی سرحد پر، مشرق سے مغرب کی طرف، اساکر ایک {حصہ}۔\n26۔ اور اساکر کی سرحد کے پاس، مشرق سے مغرب کی طرف، زبولون ایک {حصہ}۔\n27۔ اور زبولون کی سرحد کے پاس، مشرق سے مغرب کی طرف، گاد ایک {حصہ}۔\n28۔ اور گاد کی سرحد کے پاس، جنوب کی طرف جنوب میں، سرحد تامار {تک} سے قادیش میں جھگڑے کے پانیوں تک {اور} دریا تک عظیم سمندر کی طرف جائے گی۔ {جھگڑا...: یا، میری بہکادیش}\n29. یہ وہ زمین ہے جسے تم قرعہ اندازی کے ذریعے اسرائیل کے قبائل کو وراثت کے لیے تقسیم کرو گے، اور یہ ان کے حصے ہیں، خداوند خدا فرماتا ہے۔\n30۔ اور یہ شمالی جانب شہر سے باہر جانے والے واقعات ہیں، چار ہزار پانچ سو پیمانے۔\n31۔ اور شہر کے دروازے {ہوں گے} اسرائیل کے قبائل کے ناموں پر: تین دروازے شمال کی طرف؛ ایک دروازہ روبن کا، ایک دروازہ یہوداہ کا، ایک دروازہ لاوی کا۔\n32۔ اور مشرقی جانب چار ہزار پانچ سو: اور تین دروازے؛ اور یوسف کا ایک دروازہ، بنیامین کا ایک دروازہ، دان کا ایک دروازہ۔\n33۔ اور جنوب کی طرف چار ہزار پانچ سو پیمانے: اور تین دروازے؛ ایک دروازہ شمعون کا، ایک دروازہ اساکار کا، ایک دروازہ زبولون کا۔\n34۔ مغرب کی طرف چار ہزار پانچ سو، جن کے تین دروازے ہیں؛ ایک گڈ کا دروازہ، آشر کا ایک دروازہ، نفتالی کا ایک دروازہ۔\n35۔ {یہ تقریبا اٹھارہ ہزار {پیمائش} کے قریب تھا: اور شہر کا نام {و} دن {ہوگا}، خداوند {ہے} وہاں۔ {خداوند...: عبرانی۔ یہوواہشمہ}"];
